function report_handleGetStatuteMst(params) {
  const adminCode = params.admin_code || '';
  if (!report_isValidAdminCode(adminCode)) {
    return { success: false, message: '관리자 코드가 올바르지 않습니다.' };
  }

  const lawName = String(params.law_name || '').trim();
  if (!lawName) return { success: false, message: 'law_name이 필요합니다.' };

  const normalizedTarget = lawName.replace(/\s+/g, '');
  const cache = CacheService.getScriptCache();
  const cacheKey = 'statute_mst_' + normalizedTarget;
  const cached = cache.get(cacheKey);
  if (cached) {
    return { success: true, law_name: lawName, mst: cached, cached: true };
  }

  try {
    const url = 'https://www.law.go.kr/DRF/lawSearch.do?OC=' + REPORT_LAW_OC +
      '&target=law&type=XML&query=' + encodeURIComponent(lawName);
    const res = UrlFetchApp.fetch(url, { muteHttpExceptions: true });

    if (res.getResponseCode() !== 200) {
      return { success: false, message: '법령정보센터 응답 오류: ' + res.getResponseCode() };
    }

    const xml = XmlService.parse(res.getContentText('UTF-8'));
    const root = xml.getRootElement();
    const laws = root.getChildren('law');

    let mst = null;
    for (let i = 0; i < laws.length; i++) {
      const nameInResult = (laws[i].getChildText('법령명한글') || '').replace(/\s+/g, '');
      if (nameInResult === normalizedTarget) {
        mst = laws[i].getChildText('법령일련번호');
        break;
      }
    }
    if (!mst && laws.length > 0) {
      mst = laws[0].getChildText('법령일련번호');
    }

    if (!mst) return { success: false, message: '해당 법령을 찾을 수 없습니다: ' + lawName };

    cache.put(cacheKey, mst, 21600);
    return { success: true, law_name: lawName, mst: mst };

  } catch (err) {
    return { success: false, message: '조회 오류: ' + err.message };
  }
}

function report_tryReadReportFile(link) {
  try {
    const match = String(link).match(/\/file\/d\/([a-zA-Z0-9_-]+)/);
    if (!match) return null;

    const file = DriveApp.getFileById(match[1]);
    const name = file.getName().toLowerCase();

    if (name.endsWith('.html') || name.endsWith('.htm')) {
      return { type: 'html', content: file.getBlob().getDataAsString('UTF-8') };
    }
    if (name.endsWith('.md') || name.endsWith('.markdown')) {
      return { type: 'md', content: file.getBlob().getDataAsString('UTF-8') };
    }
    return null;
  } catch (err) {
    return null;
  }
}

function report_logAccess(ss, reportId) {
  const logSheet = ss.getSheetByName(REPORT_SHEET_LOG);
  logSheet.insertRowBefore(2);
  logSheet.getRange(2, 1, 1, 2).setValues([[reportId, new Date()]]);
}

function report_generateReportId(sheet, headers) {
  const data = sheet.getDataRange().getValues();
  const colReportId = headers.indexOf('report_id');

  const existingIds = new Set(
    data.slice(1).map(function (row) { return String(row[colReportId]).trim(); }).filter(Boolean)
  );

  function randomCode() {
    let code = '';
    for (let i = 0; i < REPORT_ID_LENGTH; i++) {
      code += REPORT_ID_CHARS[Math.floor(Math.random() * REPORT_ID_CHARS.length)];
    }
    return code;
  }

  let newId;
  do {
    newId = randomCode();
  } while (existingIds.has(newId));

  return newId;
}

function report_doPost(body) {
  // admin_list는 my 모듈과 이름이 겹쳐서, module:'my'로 명시된 경우만 my 쪽으로 넘긴다.
  if (body.action === 'admin_list' && body.module === 'my') {
    return my_handleAdminList(body.admin_code || '');
  }
  switch (body.action) {
    case 'admin_list':      return report_handleAdminList(body.admin_code || '');
    case 'create_report':   return report_handleCreateReport(body);
    case 'clear_password':  return report_handleClearPassword(body);
    case 'delete_report':   return report_handleDeleteReport(body);
    case 'get_statute_mst': return report_handleGetStatuteMst(body);
    case 'report_access':   return custGuard_('rpt', body, report_handleReportAccess);
    default: return { success: false, message: '알 수 없는 action: ' + body.action };
  }
}

// =========================================================
// my 모듈 — my.netax.kr(고객 통합 페이지) 백엔드 이관 (2026.08)
// admin_code 스크립트 속성은 report 모듈이 RPT_ADMIN_CODE로 옮겨가서 비게 된 원래
// 이름(ADMIN_CODE)을 그대로 재사용.
// =========================================================
let MY_SHEET_ID = '1-rHNUuds5QxmH9OoLpfIejnlPmNnlyuHGWTLZCM3XU4';
const MY_SHEET_CASES = 'Cases';
const MY_SHEET_SUB_LOG = 'SubmissionLog';
const MY_ROOT_FOLDER_ID = '1y1Wf0Dra6RQ0Nm5HA2Rm_DYwPl9LpiYc';
const MY_SUBFOLDER_UPLOAD = '제출자료';
const MY_SUBFOLDER_REPORT = '보고서_외부'; // [2026.09.16 변경] 예전 이름 '보고서' → 개명(WORK_SUBFOLDER_INTERNAL_REPORT 주석 참고)
const MY_REPORT_ID_CHARS = 'ABCDEFGHJKMNPQRSTUVWXYZ23456789';
const MY_REPORT_ID_LENGTH = 4;

function my_isValidAdminCode(inputCode) {
  const stored = PropertiesService.getScriptProperties().getProperty('ADMIN_CODE');
  if (!stored || !inputCode) return false;
  return String(inputCode).toLowerCase() === String(stored).toLowerCase();
}

function my_withAuth_(params, callback) {
  const reportId = String(params.report_id || '').trim();
  const passwordHash = params.password_hash || '';
  if (!reportId || !passwordHash) {
    return { success: false, message: 'report_id와 password_hash가 필요합니다.' };
  }

  const ss = SpreadsheetApp.openById(MY_SHEET_ID);
  const sheet = ss.getSheetByName(MY_SHEET_CASES);
  const data = sheet.getDataRange().getValues();
  const headers = data[0];
  const col = my_colMap_(headers);

  let row = null, rowIndex = -1;
  for (let i = 1; i < data.length; i++) {
    if (String(data[i][col.report_id]).trim() === reportId) { row = data[i]; rowIndex = i + 1; break; }
  }
  if (!row) return { success: false, message: '존재하지 않는 report_id입니다.' };

  const expiry = new Date(row[col.만료일]);
  expiry.setHours(0, 0, 0, 0);
  const today = new Date(); today.setHours(0, 0, 0, 0);
  if (today > expiry) return { success: false, message: '이용 기간이 만료되었습니다.' };

  const storedHash = String(row[col.비밀번호해시]).trim();
  if (!storedHash || passwordHash !== storedHash) {
    return { success: false, message: '인증에 실패했습니다.' };
  }

  return callback(params, { ss, sheet, data, headers, col, row, rowIndex });
}

function my_colMap_(headers) {
  const map = {};
  ['고객명', '사건명', 'report_id', '발급일', '비밀번호해시', '만료일', '폴더ID', '체크리스트', '제출상태', '권한']
    .forEach(function (name) { map[name] = headers.indexOf(name); });
  map.report_id = headers.indexOf('report_id');
  return map;
}

function my_handleLogin(params) {
  const reportId = String(params.report_id || '').trim();
  const passwordHash = params.password_hash || '';
  if (!reportId) return { success: false, message: 'report_id가 필요합니다.' };

  const lock = LockService.getScriptLock();
  try { lock.waitLock(10000); } catch (err) {
    return { success: false, message: '동시 접속이 많아 처리가 지연되고 있습니다. 잠시 후 다시 시도해주세요.' };
  }

  try {
    const ss = SpreadsheetApp.openById(MY_SHEET_ID);
    const sheet = ss.getSheetByName(MY_SHEET_CASES);
    const data = sheet.getDataRange().getValues();
    const headers = data[0];
    const col = my_colMap_(headers);

    let row = null, rowIndex = -1;
    for (let i = 1; i < data.length; i++) {
      if (String(data[i][col.report_id]).trim() === reportId) { row = data[i]; rowIndex = i + 1; break; }
    }
    if (!row) return { success: false, message: '존재하지 않는 report_id입니다.' };

    const expiry = new Date(row[col.만료일]);
    expiry.setHours(0, 0, 0, 0);
    const today = new Date(); today.setHours(0, 0, 0, 0);
    if (today > expiry) return { success: false, message: '이용 기간이 만료되었습니다.' };

    const storedHash = String(row[col.비밀번호해시]).trim();
    const hasPassword = storedHash.length > 0;

    if (!hasPassword) {
      if (!passwordHash) {
        return { success: false, needs_setup: true, customer_name: row[col.고객명], message: '최초 접속입니다. 비밀번호를 설정해주세요.' };
      }
      sheet.getRange(rowIndex, col.비밀번호해시 + 1).setValue(passwordHash);
      SpreadsheetApp.flush();
    } else {
      if (!passwordHash) {
        return { success: false, needs_login: true, customer_name: row[col.고객명], message: '비밀번호를 입력해주세요.' };
      }
      if (passwordHash !== storedHash) {
        return { success: false, message: '비밀번호가 일치하지 않습니다.' };
      }
    }

    let checklist = [];
    try { checklist = JSON.parse(row[col.체크리스트] || '[]'); } catch (e2) { checklist = []; }
    let status = {};
    try { status = JSON.parse(row[col.제출상태] || '{}'); } catch (e3) { status = {}; }

    return {
      success: true,
      customer_name: row[col.고객명],
      case_name: row[col.사건명],
      checklist: checklist,
      submission_status: status
    };
  } finally {
    lock.releaseLock();
  }
}

function my_handleGetChecklistStatus(params, ctx) {
  let checklist = [];
  try { checklist = JSON.parse(ctx.row[ctx.col.체크리스트] || '[]'); } catch (e) { checklist = []; }
  let status = {};
  try { status = JSON.parse(ctx.row[ctx.col.제출상태] || '{}'); } catch (e2) { status = {}; }
  return { success: true, checklist: checklist, submission_status: status };
}

function my_handleUploadFile(params, ctx) {
  const base64Data = params.base64_data || '';
  const fileName = String(params.filename || '제출파일').trim();
  const mimeType = params.mime_type || 'application/pdf';
  const checklistItem = String(params.checklist_item || '').trim();

  if (!base64Data) return { success: false, message: '업로드할 파일 데이터가 없습니다.' };

  const lock = LockService.getScriptLock();
  try { lock.waitLock(15000); } catch (err) {
    return { success: false, message: '다른 저장 작업이 진행 중입니다. 잠시 후 다시 시도해주세요.' };
  }

  try {
    const folderId = ctx.row[ctx.col.폴더ID];
    if (!folderId) return { success: false, message: '케이스 폴더가 설정되어 있지 않습니다.' };

    const caseFolder = DriveApp.getFolderById(folderId);
    const uploadFolder = my_getOrCreateSubfolder_(caseFolder, MY_SUBFOLDER_UPLOAD);

    const blob = Utilities.newBlob(Utilities.base64Decode(base64Data), mimeType, fileName);
    uploadFolder.createFile(blob);

    let status = {};
    try { status = JSON.parse(ctx.row[ctx.col.제출상태] || '{}'); } catch (e) { status = {}; }
    if (checklistItem) {
      status[checklistItem] = { submitted: true, fileName: fileName, uploadedAt: new Date().toISOString() };
    } else {
      if (!Array.isArray(status._extra)) status._extra = [];
      status._extra.push({ fileName: fileName, uploadedAt: new Date().toISOString() });
    }
    ctx.sheet.getRange(ctx.rowIndex, ctx.col.제출상태 + 1).setValue(JSON.stringify(status));
    SpreadsheetApp.flush();

    const logSheet = ctx.ss.getSheetByName(MY_SHEET_SUB_LOG);
    logSheet.appendRow([params.report_id, fileName, checklistItem || '(기타제출)', new Date()]);

    return { success: true, submission_status: status };
  } catch (err) {
    // [2026.09 버그수정] 사건 폴더가 드라이브에서 지워지는 등 예상 못한 오류가 나면 예전엔
    // 영어 기술 메시지가 그대로 고객 화면에 노출됐다 — 고객에게는 친절한 안내만 보여준다.
    console.log('my_handleUploadFile 오류: ' + err.message);
    return { success: false, message: '자료를 업로드하지 못했습니다. 잠시 후 다시 시도하시거나 담당 세무사에게 문의해주세요.' };
  } finally {
    lock.releaseLock();
  }
}

function my_handleGetReportList(params, ctx) {
  const folderId = ctx.row[ctx.col.폴더ID];
  if (!folderId) return { success: true, reports: [] };

  // [2026.09 버그수정] 폴더가 드라이브에서 지워지는 등 예상 못한 오류가 나면 예전엔 영어
  // 기술 메시지가 그대로 고객 화면에 노출됐다 — 고객에게는 친절한 안내만 보여준다.
  try {
    const caseFolder = DriveApp.getFolderById(folderId);
    const reportFolder = my_getOrCreateSubfolder_(caseFolder, MY_SUBFOLDER_REPORT);

    const reports = [];
    const files = reportFolder.getFiles();
    while (files.hasNext()) {
      const f = files.next();
      const name = f.getName().toLowerCase();
      if (name.endsWith('.html') || name.endsWith('.htm')) {
        reports.push({ id: f.getId(), name: f.getName(), updated: f.getLastUpdated().toISOString() });
      }
    }
    reports.sort(function (a, b) { return new Date(b.updated) - new Date(a.updated); });
    return { success: true, reports: reports };
  } catch (err) {
    console.log('my_handleGetReportList 오류: ' + err.message);
    return { success: false, message: '보고서 목록을 불러오지 못했습니다. 담당 세무사에게 문의해주세요.' };
  }
}

function my_handleGetReportFile(params, ctx) {
  const folderId = ctx.row[ctx.col.폴더ID];
  const fileId = String(params.file_id || '').trim();
  if (!folderId || !fileId) return { success: false, message: '파일 정보가 부족합니다.' };

  try {
    const caseFolder = DriveApp.getFolderById(folderId);
    const reportFolder = my_getOrCreateSubfolder_(caseFolder, MY_SUBFOLDER_REPORT);

    let belongs = false;
    const files = reportFolder.getFiles();
    while (files.hasNext()) {
      if (files.next().getId() === fileId) { belongs = true; break; }
    }
    if (!belongs) return { success: false, message: '이 케이스에 속한 보고서가 아닙니다.' };

    const file = DriveApp.getFileById(fileId);
    const content = file.getBlob().getDataAsString('UTF-8');
    return { success: true, html: content, name: file.getName() };
  } catch (err) {
    console.log('my_handleGetReportFile 오류: ' + err.message);
    return { success: false, message: '보고서를 불러오지 못했습니다. 담당 세무사에게 문의해주세요.' };
  }
}

function my_handleAdminCreateCase(params) {
  if (!my_isValidAdminCode(params.admin_code || '')) {
    return { success: false, message: '관리자 코드가 올바르지 않습니다.' };
  }
  const name = String(params.name || '').trim();
  const caseName = String(params.case_name || '').trim();
  const checklist = Array.isArray(params.checklist) ? params.checklist : [];
  const permission = String(params.permission || '허용').trim();

  if (!name || !caseName) {
    return { success: false, message: '고객명과 사건명은 필수입니다.' };
  }

  const lock = LockService.getScriptLock();
  try { lock.waitLock(10000); } catch (err) {
    return { success: false, message: '처리가 지연되고 있습니다. 잠시 후 다시 시도해주세요.' };
  }

  try {
    // [2026.09] 5단계 — folderId가 주어지면(사건처리 화면이 이미 만들어둔 work_ 사건의 폴더ID)
    // MY_ROOT_FOLDER_ID 밑에 별도 폴더를 새로 만들지 않고 그 폴더를 그대로 재사용한다 — 그래야
    // 고객이 my.netax.kr로 올리는 파일이 증빙관리가 보는 것과 같은 폴더에 쌓인다. folderId가 없으면
    // (work_ 사건과 무관하게 만드는 예전 방식) 기존처럼 MY_ROOT_FOLDER_ID 밑에 새로 만든다.
    const givenFolderId = String(params.folder_id || '').trim();
    let caseFolder = null;
    if (givenFolderId) {
      caseFolder = DriveApp.getFolderById(givenFolderId);
    } else {
      const folderName = (name + ' ' + caseName).trim();
      const rootFolder = DriveApp.getFolderById(MY_ROOT_FOLDER_ID);
      const existing = rootFolder.getFoldersByName(folderName);
      caseFolder = existing.hasNext() ? existing.next() : rootFolder.createFolder(folderName);
    }
    my_getOrCreateSubfolder_(caseFolder, MY_SUBFOLDER_UPLOAD);
    my_getOrCreateSubfolder_(caseFolder, MY_SUBFOLDER_REPORT);

    const ss = SpreadsheetApp.openById(MY_SHEET_ID);
    const sheet = ss.getSheetByName(MY_SHEET_CASES);
    const headers = sheet.getRange(1, 1, 1, sheet.getLastColumn()).getValues()[0];
    const col = my_colMap_(headers);

    const reportId = my_generateReportId_(sheet, col);
    const today = new Date();

    const rowValues = new Array(headers.length).fill('');
    rowValues[col.고객명] = name;
    rowValues[col.사건명] = caseName;
    rowValues[col.report_id] = reportId;
    rowValues[col.발급일] = today;
    rowValues[col.비밀번호해시] = '';
    rowValues[col.폴더ID] = caseFolder.getId();
    rowValues[col.체크리스트] = JSON.stringify(checklist);
    rowValues[col.제출상태] = JSON.stringify({});
    rowValues[col.권한] = permission;

    const newRow = sheet.getLastRow() + 1;
    sheet.getRange(newRow, 1, 1, headers.length).setValues([rowValues]);

    // [2026.09] 예전엔 "완성된 보고서 하나 열람"이 전부라 발급일+30일 고정이면 충분했지만,
    // 이제는 사건이 시작되자마자(자문용역이 진행 중일 때부터) 연결되므로, 진행 중에는
    // 만료를 두지 않는다(빈 값 — my_withAuth_/my_handleLogin은 만료일이 비어있으면
    // Invalid Date로 비교돼 항상 "만료 안 됨"으로 취급함). 실제 만료일은 work_updateCase가
    // 사건을 "완료" 처리하는 순간 완료일+30일로 확정한다(my_setExpiryByReportId_).
    SpreadsheetApp.flush();
    return { success: true, report_id: reportId, folder_url: caseFolder.getUrl() };
  } finally {
    lock.releaseLock();
  }
}

// [2026.09] 사건이 "완료" 처리될 때(work_updateCase) my.netax.kr 이용기간을 확정한다 —
// 완료일+30일로 설정하고, 완료가 취소되면(다시 진행/보류로) 만료를 없애 계속 쓸 수 있게
// 되돌린다(expiryDate가 null이면 만료일 칸을 비운다). reportId에 해당하는 행이 없으면
// (my.netax.kr에 연결 안 된 사건 등) 조용히 아무 것도 하지 않는다 — 실패해도 work_ 사건
// 완료 처리 자체를 막아서는 안 되므로 호출부에서 try/catch로 감싼다.
// [2026.10.09] job 사건명·고객명이 바뀌면 고객창구 시트의 같은 행도 맞춘다(work_updateCase에서 호출).
function my_setCaseNamesByReportId_(reportId, caseName, customerName) {
  if (!reportId) return;
  const sheet = SpreadsheetApp.openById(MY_SHEET_ID).getSheetByName(MY_SHEET_CASES);
  const data = sheet.getDataRange().getValues();
  const col = my_colMap_(data[0]);
  for (let i = 1; i < data.length; i++) {
    if (String(data[i][col.report_id]).trim() === String(reportId).trim()) {
      if (caseName && col.사건명 >= 0) sheet.getRange(i + 1, col.사건명 + 1).setValue(caseName);
      if (customerName && col.고객명 >= 0) sheet.getRange(i + 1, col.고객명 + 1).setValue(customerName);
      return;
    }
  }
}
function my_setExpiryByReportId_(reportId, expiryDate) {
  if (!reportId) return;
  const ss = SpreadsheetApp.openById(MY_SHEET_ID);
  const sheet = ss.getSheetByName(MY_SHEET_CASES);
  const data = sheet.getDataRange().getValues();
  const headers = data[0];
  const col = my_colMap_(headers);
  for (let i = 1; i < data.length; i++) {
    if (String(data[i][col.report_id]).trim() === String(reportId).trim()) {
      sheet.getRange(i + 1, col.만료일 + 1).setValue(expiryDate || '');
      return;
    }
  }
}

function my_handleAdminList(adminCode) {
  if (!my_isValidAdminCode(adminCode)) {
    return { success: false, message: '관리자 코드가 올바르지 않습니다.' };
  }
  const ss = SpreadsheetApp.openById(MY_SHEET_ID);
  const sheet = ss.getSheetByName(MY_SHEET_CASES);
  const data = sheet.getDataRange().getValues();
  const headers = data[0];
  const col = my_colMap_(headers);

  const cases = [];
  for (let i = 1; i < data.length; i++) {
    const row = data[i];
    if (!row[col.report_id]) continue;

    let checklist = [];
    try { checklist = JSON.parse(row[col.체크리스트] || '[]'); } catch (e) { checklist = []; }
    let status = {};
    try { status = JSON.parse(row[col.제출상태] || '{}'); } catch (e) { status = {}; }

    cases.push({
      name: row[col.고객명],
      case_name: row[col.사건명],
      report_id: row[col.report_id],
      issued: row[col.발급일],
      expiry: row[col.만료일],
      has_password: String(row[col.비밀번호해시]).trim().length > 0,
      folder_id: row[col.폴더ID],
      checklist: checklist,
      submission_status: status
    });
  }
  return { success: true, cases: cases };
}

// [2026.09] 4단계 — 사건처리 화면이 연결된 my.netax.kr 케이스 하나만 빠르게 조회할 때 씀
// (my_handleAdminList는 전체 케이스를 다 가져와야 해서 사건 하나 보려고 매번 쓰기엔 낭비).
function my_handleAdminGetCase(params) {
  if (!my_isValidAdminCode(params.admin_code || '')) {
    return { success: false, message: '관리자 코드가 올바르지 않습니다.' };
  }
  const reportId = String(params.report_id || '').trim();
  if (!reportId) return { success: false, message: 'report_id가 필요합니다.' };
  const ss = SpreadsheetApp.openById(MY_SHEET_ID);
  const sheet = ss.getSheetByName(MY_SHEET_CASES);
  const data = sheet.getDataRange().getValues();
  const headers = data[0];
  const col = my_colMap_(headers);
  for (let i = 1; i < data.length; i++) {
    const row = data[i];
    if (String(row[col.report_id]).trim() === reportId) {
      let checklist = [];
      try { checklist = JSON.parse(row[col.체크리스트] || '[]'); } catch (e) { checklist = []; }
      let status = {};
      try { status = JSON.parse(row[col.제출상태] || '{}'); } catch (e) { status = {}; }
      return {
        success: true,
        case: {
          name: row[col.고객명], case_name: row[col.사건명], report_id: row[col.report_id],
          issued: row[col.발급일], expiry: row[col.만료일],
          has_password: String(row[col.비밀번호해시]).trim().length > 0,
          checklist: checklist, submission_status: status
        }
      };
    }
  }
  return { success: false, message: '연결된 my.netax.kr 케이스를 찾을 수 없습니다(삭제되었을 수 있습니다).' };
}

function my_handleAdminAddChecklistItem(params) {
  if (!my_isValidAdminCode(params.admin_code || '')) {
    return { success: false, message: '관리자 코드가 올바르지 않습니다.' };
  }
  const reportId = String(params.report_id || '').trim();
  const newItem = String(params.item || '').trim();
  if (!reportId || !newItem) {
    return { success: false, message: 'report_id와 item이 필요합니다.' };
  }

  const lock = LockService.getScriptLock();
  try { lock.waitLock(10000); } catch (err) {
    return { success: false, message: '처리가 지연되고 있습니다. 잠시 후 다시 시도해주세요.' };
  }

  try {
    const ss = SpreadsheetApp.openById(MY_SHEET_ID);
    const sheet = ss.getSheetByName(MY_SHEET_CASES);
    const data = sheet.getDataRange().getValues();
    const headers = data[0];
    const col = my_colMap_(headers);

    let rowIndex = -1;
    let row = null;
    for (let i = 1; i < data.length; i++) {
      if (String(data[i][col.report_id]).trim() === reportId) { row = data[i]; rowIndex = i + 1; break; }
    }
    if (!row) return { success: false, message: '존재하지 않는 report_id입니다.' };

    let checklist = [];
    try { checklist = JSON.parse(row[col.체크리스트] || '[]'); } catch (e) { checklist = []; }

    if (checklist.indexOf(newItem) === -1) {
      checklist.push(newItem);
      sheet.getRange(rowIndex, col.체크리스트 + 1).setValue(JSON.stringify(checklist));
      SpreadsheetApp.flush();
    }

    return { success: true, checklist: checklist };
  } finally {
    lock.releaseLock();
  }
}

// [2026.09 버그수정] 요청자료 항목명을 나중에 고치거나(오타 수정 등) 지울 방법이 이 체크리스트
// 쪽엔 전혀 없었다 — docs.html에서 항목을 지워도 my.netax.kr의 체크리스트엔 지저분한 옛
// 항목이 그대로 남고, 라벨을 고치면(사실상 삭제+새로추가) 이미 고객이 제출한 파일의 제출상태
// (같은 문자열 키로 연결됨)와 연결이 끊겨서 "이미 제출함" 안내가 조용히 사라졌다. 이름을
// 바꿀 때 제출상태도 같이 옮겨주는 전용 액션을 추가한다.
function my_handleAdminRenameChecklistItem(params) {
  if (!my_isValidAdminCode(params.admin_code || '')) {
    return { success: false, message: '관리자 코드가 올바르지 않습니다.' };
  }
  const reportId = String(params.report_id || '').trim();
  const oldItem = String(params.old_item || '').trim();
  const newItem = String(params.new_item || '').trim();
  if (!reportId || !oldItem || !newItem) {
    return { success: false, message: 'report_id, old_item, new_item이 필요합니다.' };
  }
  const lock = LockService.getScriptLock();
  try { lock.waitLock(10000); } catch (err) {
    return { success: false, message: '처리가 지연되고 있습니다. 잠시 후 다시 시도해주세요.' };
  }
  try {
    const ss = SpreadsheetApp.openById(MY_SHEET_ID);
    const sheet = ss.getSheetByName(MY_SHEET_CASES);
    const data = sheet.getDataRange().getValues();
    const col = my_colMap_(data[0]);
    let rowIndex = -1, row = null;
    for (let i = 1; i < data.length; i++) {
      if (String(data[i][col.report_id]).trim() === reportId) { row = data[i]; rowIndex = i + 1; break; }
    }
    if (!row) return { success: false, message: '존재하지 않는 report_id입니다.' };

    let checklist = [];
    try { checklist = JSON.parse(row[col.체크리스트] || '[]'); } catch (e) { checklist = []; }
    const idx = checklist.indexOf(oldItem);
    if (idx !== -1) checklist[idx] = newItem;
    else if (checklist.indexOf(newItem) === -1) checklist.push(newItem);
    sheet.getRange(rowIndex, col.체크리스트 + 1).setValue(JSON.stringify(checklist));

    let status = {};
    try { status = JSON.parse(row[col.제출상태] || '{}'); } catch (e) { status = {}; }
    if (status[oldItem] !== undefined) {
      status[newItem] = status[oldItem];
      delete status[oldItem];
      sheet.getRange(rowIndex, col.제출상태 + 1).setValue(JSON.stringify(status));
    }
    SpreadsheetApp.flush();
    return { success: true, checklist: checklist, submission_status: status };
  } finally {
    lock.releaseLock();
  }
}

function my_handleAdminRemoveChecklistItem(params) {
  if (!my_isValidAdminCode(params.admin_code || '')) {
    return { success: false, message: '관리자 코드가 올바르지 않습니다.' };
  }
  const reportId = String(params.report_id || '').trim();
  const item = String(params.item || '').trim();
  if (!reportId || !item) return { success: false, message: 'report_id와 item이 필요합니다.' };
  const lock = LockService.getScriptLock();
  try { lock.waitLock(10000); } catch (err) {
    return { success: false, message: '처리가 지연되고 있습니다. 잠시 후 다시 시도해주세요.' };
  }
  try {
    const ss = SpreadsheetApp.openById(MY_SHEET_ID);
    const sheet = ss.getSheetByName(MY_SHEET_CASES);
    const data = sheet.getDataRange().getValues();
    const col = my_colMap_(data[0]);
    let rowIndex = -1, row = null;
    for (let i = 1; i < data.length; i++) {
      if (String(data[i][col.report_id]).trim() === reportId) { row = data[i]; rowIndex = i + 1; break; }
    }
    if (!row) return { success: false, message: '존재하지 않는 report_id입니다.' };

    let checklist = [];
    try { checklist = JSON.parse(row[col.체크리스트] || '[]'); } catch (e) { checklist = []; }
    checklist = checklist.filter(function (x) { return x !== item; });
    sheet.getRange(rowIndex, col.체크리스트 + 1).setValue(JSON.stringify(checklist));

    let status = {};
    try { status = JSON.parse(row[col.제출상태] || '{}'); } catch (e) { status = {}; }
    if (status[item] !== undefined) {
      delete status[item];
      sheet.getRange(rowIndex, col.제출상태 + 1).setValue(JSON.stringify(status));
    }
    SpreadsheetApp.flush();
    return { success: true, checklist: checklist, submission_status: status };
  } finally {
    lock.releaseLock();
  }
}

// [2026.09] 증빙확보(docs.html)에서 회계사가 요청자료를 "확보완료"로 표시하면 — 고객이
// my.netax.kr로 올린 게 아니라 회계사가 직접 구했더라도(등기부등본 발급 등) — 고객이
// 보는 체크리스트에도 완료로 반영해서, 이미 처리된 항목을 고객이 다시 챙겨 올리지 않게
// 한다. 반대로 "미확보로" 되돌리면 여기서도 되돌린다. 파일은 실제로 없으므로(회계사가
// 직접 구한 경우) fileName을 "(세무사 확인)"으로 표시해 고객 업로드와 구분한다.
function my_handleAdminSetChecklistStatus(params) {
  if (!my_isValidAdminCode(params.admin_code || '')) {
    return { success: false, message: '관리자 코드가 올바르지 않습니다.' };
  }
  const reportId = String(params.report_id || '').trim();
  const item = String(params.item || '').trim();
  if (!reportId || !item) return { success: false, message: 'report_id와 item이 필요합니다.' };

  const lock = LockService.getScriptLock();
  try { lock.waitLock(10000); } catch (err) {
    return { success: false, message: '처리가 지연되고 있습니다. 잠시 후 다시 시도해주세요.' };
  }
  try {
    const ss = SpreadsheetApp.openById(MY_SHEET_ID);
    const sheet = ss.getSheetByName(MY_SHEET_CASES);
    const data = sheet.getDataRange().getValues();
    const headers = data[0];
    const col = my_colMap_(headers);
    let rowIndex = -1, row = null;
    for (let i = 1; i < data.length; i++) {
      if (String(data[i][col.report_id]).trim() === reportId) { row = data[i]; rowIndex = i + 1; break; }
    }
    if (!row) return { success: false, message: '존재하지 않는 report_id입니다.' };

    let status = {};
    try { status = JSON.parse(row[col.제출상태] || '{}'); } catch (e) { status = {}; }
    if (params.submitted) {
      status[item] = { submitted: true, fileName: '(세무사 확인)', uploadedAt: new Date().toISOString() };
    } else {
      delete status[item];
    }
    sheet.getRange(rowIndex, col.제출상태 + 1).setValue(JSON.stringify(status));
    SpreadsheetApp.flush();
    return { success: true, submission_status: status };
  } finally {
    lock.releaseLock();
  }
}

function my_getOrCreateSubfolder_(parentFolder, name) {
  const found = parentFolder.getFoldersByName(name);
  if (found.hasNext()) return found.next();
  return parentFolder.createFolder(name);
}

function my_generateReportId_(sheet, col) {
  const data = sheet.getDataRange().getValues();
  const existingIds = new Set(data.slice(1).map(function (row) { return String(row[col.report_id]).trim(); }).filter(Boolean));

  function randomCode() {
    let code = '';
    for (let i = 0; i < MY_REPORT_ID_LENGTH; i++) {
      code += MY_REPORT_ID_CHARS[Math.floor(Math.random() * MY_REPORT_ID_CHARS.length)];
    }
    return code;
  }
  let newId;
  do { newId = randomCode(); } while (existingIds.has(newId));
  return newId;
}

function my_doPost(body) {
  switch (body.action) {
    case 'admin_create_case': return my_handleAdminCreateCase(body);
    case 'login': return custGuard_('my', body, my_handleLogin);
    case 'get_checklist_status': return custGuard_('my', body, function (b) { return my_withAuth_(b, my_handleGetChecklistStatus); });
    case 'upload_file': return custGuard_('my', body, function (b) { return my_withAuth_(b, my_handleUploadFile); });
    case 'get_report_list': return custGuard_('my', body, function (b) { return my_withAuth_(b, my_handleGetReportList); });
    case 'get_report_file': return custGuard_('my', body, function (b) { return my_withAuth_(b, my_handleGetReportFile); });
    case 'admin_add_checklist_item': return my_handleAdminAddChecklistItem(body);
    case 'admin_get_case': return my_handleAdminGetCase(body);
    case 'admin_set_checklist_status': return my_handleAdminSetChecklistStatus(body);
    case 'admin_rename_checklist_item': return my_handleAdminRenameChecklistItem(body);
    case 'admin_remove_checklist_item': return my_handleAdminRemoveChecklistItem(body);
    default: return { success: false, message: '알 수 없는 action: ' + body.action };
  }
}

// =========================================================
// client 모듈 — 고객관리(고객 명단 + 자문내역·수임료 기록) (2026.08 신규)
// 기존 고객관리.xlsx(자문일지 성격)에 없던 "고객 1명당 1행" 명단(Clients)을 새로 만들고,
// 실제 상담·자문 이력은 예전처럼 이벤트 하나당 1행(ConsultLog)으로 남기되 고객ID로 연결한다.
// work_ 모듈(작업관리)의 사건도 고객명을 적으면 자동으로 여기 명단과 연결/신규등록된다.
// =========================================================
const CLIENT_SHEET_ID = '1nHf4PK1F1-Ao5jZ-s43PB1A3eF85YVRcI7T1kK_ooBI';
const CLIENT_SHEET_CLIENTS = 'Clients';
const CLIENT_SHEET_LOG = 'ConsultLog';
const CLIENT_HEADERS = ['id', '성명', '전화번호', '구분', '사업자번호', '메모', '등록일', '수정일', '추가연락처', '주소', '주민등록번호암호화'];
// [2026.09.19 신규] "고객관리할 정보가 전화번호·납세번호가 끝인가?" → "납세번호는 주민등록번호를
// 염두에 둔 표현" → "개인정보보호가 고민" → "그렇게 하자"(암호화 저장 확정)까지 확인받고
// 추가한 주민등록번호 저장 체계. 구글시트는 셀 단위 암호화 기능이 없어 평문으로 두면 시트
// 접근 권한이나 스크립트가 뚫렸을 때 전체 고객의 주민번호가 그대로 노출된다 — 스크립트
// 속성에 대칭키를 하나 두고 XOR 스트림 암호(+SHA-256으로 키를 32바이트로 정규화)로
// 암호화한 뒤 Base64로 인코딩해 시트에는 그 암호문만 저장한다. 완벽한 강암호는 아니지만
// (같은 코드베이스에 복호화 로직이 있으므로 스크립트 자체가 털리면 무력화됨), "시트를 그냥
// 열어보면 그대로 보인다"는 가장 현실적인 위험은 막는다. 목록 조회(client_getClients)에서는
// 절대 값 자체를 안 내려주고(암호문조차) 등록 여부(불리언)만 알려주며, 실제 값은
// client_get_rrn을 명시적으로 호출했을 때만 그 자리에서 복호화해 1건만 내려준다.
function client_getRRNEncKey_() {
  const props = PropertiesService.getScriptProperties();
  let key = props.getProperty('CLIENT_RRN_ENC_KEY');
  if (!key) {
    key = Utilities.getUuid() + Utilities.getUuid(); // 최초 사용 시 자동 생성 — 사람이 따로 설정할 필요 없음
    props.setProperty('CLIENT_RRN_ENC_KEY', key);
  }
  return key;
}
function client_xorWithKey_(bytes, keyBytes) {
  return bytes.map(function (b, i) {
    const r = (b & 0xFF) ^ (keyBytes[i % keyBytes.length] & 0xFF);
    return r > 127 ? r - 256 : r; // Apps Script 바이트 배열은 부호 있는 -128~127 범위
  });
}
function client_encryptRRN_(plain) {
  const trimmed = String(plain || '').trim();
  if (!trimmed) return '';
  const keyBytes = Utilities.computeDigest(Utilities.DigestAlgorithm.SHA_256, client_getRRNEncKey_());
  const plainBytes = Utilities.newBlob(trimmed).getBytes();
  return Utilities.base64Encode(client_xorWithKey_(plainBytes, keyBytes));
}
function client_decryptRRN_(encoded) {
  const trimmed = String(encoded || '').trim();
  if (!trimmed) return '';
  try {
    const keyBytes = Utilities.computeDigest(Utilities.DigestAlgorithm.SHA_256, client_getRRNEncKey_());
    const cipherBytes = Utilities.base64Decode(trimmed);
    return Utilities.newBlob(client_xorWithKey_(cipherBytes, keyBytes)).getDataAsString();
  } catch (err) {
    return ''; // 복호화 실패(키 변경 등) — 빈 값으로 안전하게 처리
  }
}
// 특정 고객 1명의 주민등록번호만 그 자리에서 복호화해 내려준다 — 목록 조회에는 절대
// 포함하지 않는 값이라 화면에서 "보기" 버튼을 눌렀을 때만 이 액션을 호출한다.
function client_getRRN(params) {
  const sheets = client_getSheets_();
  const col = client_colMap_(sheets.clients.getDataRange().getValues()[0], CLIENT_HEADERS);
  const found = client_findRow_(sheets.clients, col, params.id);
  if (!found) return { success: false, message: '존재하지 않는 고객입니다.' };
  return { success: true, 주민등록번호: client_decryptRRN_(found.row[col.주민등록번호암호화]) };
}

// [2026.09.19 정비도구 재정비] "주민번호 이관" 도구(옛 "납세번호" 칸에 평문으로 섞여있던
// 주민등록번호를 암호화 필드로 옮기던 1회성 마이그레이션)는 세무사님이 이미 실행 완료했다고
// 확인해주셔서 삭제했다 — 다시 눌러도 영원히 "해당 없음"만 나오는 상태였다.

// [2026.09.19 신규, 같은 날 두 차례 수정] "고객사건 밑 사건폴더 안의 모든 파일을 전수조사해서
// 모든 고객을 일괄등록해달라" — 사건개요(구조화된 필드, work_linkPartyClientIds_)에는 없지만
// 실제 사건 폴더에 올라온 파일에만 등장하는 관계자를 찾으려는 목적.
// [수정 이력] 처음엔 파일 "이름"만 보고 등록도 이름만 했는데, "이름만 찾지 말고 상세정보도
// 수집하라고 했는데 왜 축소했냐"는 지적으로 파일 "내용"까지 열어 전화번호·주소·주민등록번호도
// 같이 찾도록 확장했다. 다만 파일마다 여는 건 비용·시간이 커서, 먼저 파일명만으로 사람이름·관계
// 후보를 싸게 골라낸 뒤(1차, 사건당 API 호출 1번), 후보로 뽑힌 이름이 들어간 파일 중 실제로 열어볼
// 수 있는 것(PDF·이미지)만 그 사람 몫으로 한 번 더 열어(2차, 후보당 API 호출 1번) 상세정보를 찾는다.
// 사건 수가 많으면 Apps Script 6분 실행 제한을 넘을 수 있어 진행상황을 캐시에 저장해두고
// done:true가 나올 때까지 반복 호출한다 — 실제로 시간이 걸리는 작업이라는 걸 화면에 그대로 보여준다.
// AI가 잘못 짚을 수 있으므로 곧바로 등록하지 않고, 사람이 검토화면에서 골라 체크한 것만 등록한다.
const CLIENT_NAME_SCAN_PROP_ = 'CLIENT_NAME_SCAN_PROGRESS';
const CLIENT_NAME_SCAN_TIME_BUDGET_MS_ = 4 * 60 * 1000;
const CLIENT_NAME_SCAN_MAX_FILES_PER_CASE_ = 300; // 파일이 극단적으로 많은 사건에 대비한 폭주 방지

// [2026.09.19 버그수정] "하위 폴더를 모두 봐야지" — 처음엔 "고객사건" 바로 밑 폴더만 사건으로
// 봤는데, 실제로는 연도별·유형별 등 몇 단계 더 들어가야 진짜 사건 폴더가 나오는 구조였다.
// 이제 트리 전체를 훑되, 이미 아는(시트에 폴더ID로 연결된) 사건 폴더를 만나면 거기서 멈추고
// (그 밑의 "증빙"·"계약서" 같은 하위폴더는 같은 사건의 일부일 뿐 별도 사건이 아니므로 더
// 들어가지 않는다) 그 사건 전체를 한 단위로 처리한다. 모르는 폴더는 그 폴더 자체를 하나의
// "고아 사건 후보" 단위로 등록하면서 계속 더 들어간다 — 그래야 몇 단계든 안 놓친다.
// [2026.09.19 버그수정] 재귀 함수 하나로 트리 전체를 한 번에 다 훑게 만들었더니, 폴더가 많은
// 실사용 환경에서 이 "찾는 단계" 자체가 Apps Script의 6분 실행 제한을 넘겨서 매 호출이 조용히
// 실패했다("돌다가 멈추고 아무일도 일어나지 않았다"). 재귀 대신 큐(queue) 기반으로 한 겹씩만
// 확장하도록 바꿔서, 스캔 단계와 똑같이 시간예산을 걸고 여러 번에 나눠 이어갈 수 있게 한다.
// 반환값 done=false면 queue에 아직 더 확장할 폴더가 남아있다는 뜻 — 호출한 쪽이 계속 불러야 한다.
function client_expandScanUnitsStep_(queue, units, knownFolderIds, startTime, timeBudgetMs) {
  while (queue.length) {
    if (Date.now() - startTime > timeBudgetMs) return { done: false };
    const fid = queue.shift();
    if (knownFolderIds[fid]) {
      units.push({ folderId: fid, known: true });
      continue; // 이미 아는 사건은 하위폴더를 더 들어가지 않는다
    }
    units.push({ folderId: fid, known: false });
    let folder;
    try { folder = DriveApp.getFolderById(fid); } catch (err) { continue; } // 삭제되었거나 접근 불가한 폴더는 건너뜀
    const subfolders = folder.getFolders();
    while (subfolders.hasNext()) { const sf = subfolders.next(); if (!caseIsFiledReturnFolder_(sf.getName())) queue.push(sf.getId()); }
  }
  return { done: true };
}

function client_listFilesRecursive_(folder, depth, maxFiles, out) {
  if (out.length >= maxFiles || depth > 4) return;
  const files = folder.getFiles();
  while (files.hasNext() && out.length < maxFiles) {
    const f = files.next();
    out.push({ id: f.getId(), name: f.getName(), mimeType: f.getMimeType() });
  }
  const subfolders = folder.getFolders();
  while (subfolders.hasNext() && out.length < maxFiles) {
    const sf = subfolders.next();
    if (caseIsFiledReturnFolder_(sf.getName()) || tcIsSubmitDir_(sf.getName())) continue; // 이미 낸 신고서 보관 폴더 — 읽지 않음(caseIsFiledReturnFolder_) · [2026.10.19] _신고제출 사본도(3번 판정)
    client_listFilesRecursive_(sf, depth + 1, maxFiles, out);
  }
}

// [2026.09.19] "부동산중개인·임차인 같은 순수 서비스 제공자도 후보에 넣을 거냐"는 질문에
// "잠재 고객이 될 관계만" 남기기로 확정 — 매수인·매도인·공동상속인·배우자처럼 나중에 직접
// 고객이 될 수 있는 거래당사자·가족만 뽑고, 중개인·법무사·세무사·임차인 등은 프롬프트에서
// 명시적으로 제외한다.
function client_extractNamesFromFilenames_(caseLabel, knownNames, fileObjs, apiKey) {
  if (!fileObjs.length) return [];
  const filenames = fileObjs.map(function (f) { return f.name; });
  const prompt = '아래는 세무사 사무실의 사건(' + caseLabel + ') 폴더 안에 있는 파일 이름 목록이다. ' +
    '이미 알려진 당사자(등록 대상 아님): ' + (knownNames.join(', ') || '없음') + '. ' +
    '이 파일 이름들 중에 사람 이름으로 보이면서, 앞으로 이 세무사 사무실의 잠재 고객이 될 수 있는 ' +
    '거래당사자·관계인(예: 양도인/양수인/매수인/매도인/증여인/수증인/공동상속인/배우자/가족/동업자 등)만 골라라. ' +
    '부동산중개인·법무사·세무사·은행담당자·임차인처럼 이 거래의 서비스 제공자이거나 잠재 고객이 될 ' +
    '가능성이 낮은 사람은 절대 포함하지 마라. 확실하지 않으면 포함하지 마라(파일 종류·번호 등은 이름이 아니다). ' +
    '다른 설명 없이 정확히 이 형식의 JSON만 답하라: ' +
    '{"items": [{"성명": "이름", "관계": "추정 관계(예: 공동상속인)"}]}. ' +
    '해당하는 사람이 없으면 {"items": []}로 답하라.\n\n파일 목록:\n' + filenames.join('\n');
  const response = UrlFetchApp.fetch('https://api.anthropic.com/v1/messages', {
    method: 'post',
    contentType: 'application/json',
    headers: { 'x-api-key': apiKey, 'anthropic-version': '2023-06-01' },
    payload: JSON.stringify({
      model: LIGHT_MODEL, max_tokens: 500,
      messages: [{ role: 'user', content: prompt }]
    }),
    muteHttpExceptions: true
  });
  const json = JSON.parse(response.getContentText());
  ai_logDirect_(json, LIGHT_MODEL, 'names', '고객관리 파일명 이름 찾기 — ' + String(caseLabel || '').slice(0, 30));
  if (json.error) throw new Error(json.error.message || 'AI 호출 실패');
  const text = (json.content && json.content[0] && json.content[0].text) || '';
  const match = text.match(/\{[\s\S]*\}/);
  if (!match) return [];
  try {
    const parsed = JSON.parse(match[0]);
    if (!Array.isArray(parsed.items)) return [];
    return parsed.items
      .filter(function (it) { return it && String(it.성명 || '').trim(); })
      .map(function (it) { return { 성명: String(it.성명).trim(), 관계: String(it.관계 || '').trim() }; });
  } catch (e) { return []; }
}


// 사건 폴더 이름 규칙("고객명[동명이인번호](납세자)_세목_업무유형", work_generateUniqueCaseName_
// 참고)을 그대로 파싱한다 — 작업관리 시트에 연결이 안 된(고아) 폴더라도 이 규칙만으로 고객명·
// 납세자(상속이면 곧 피상속인)를 최대한 복원해서, AI가 이미 아는 당사자로 제외할 수 있게 한다.
function client_parseCaseFolderName_(folderName) {
  const name = String(folderName || '');
  const match = name.match(/^([^(_]+?)\d*\(([^)]+)\)/);
  if (match) return { 고객명: match[1].trim(), 납세자: match[2].trim() };
  const simple = name.split('_')[0].replace(/\d+$/, '').trim();
  return { 고객명: simple, 납세자: '' };
}

// [2026.09.19 버그수정] 처음엔 작업관리 시트에 폴더ID로 이미 연결된 사건만 훑었는데, "몇 건
// 되지 않는다"는 지적으로 확인해보니 시트에 안 잡힌(또는 폴더ID 연결이 빠진) 사건 폴더가
// Drive에 더 있어서 애초에 조사 대상에서 빠지고 있었다. 시트를 신뢰하지 않고 "고객사건"
// 루트(getDefaultFolder()) 바로 밑의 실제 폴더 전부를 훑는 방식으로 바꾼다 — 이게 세무사님이
// 처음부터 말한 "고객사건아래 고객폴더"의 진짜 전수조사다. 시트에 그 폴더ID로 연결된 사건이
// 있으면 고객명·납세자를 "이미 아는 이름"으로 AI에 알려주고, 없으면(레거시 미연결 폴더)
// 폴더 이름 자체를 사건명으로 쓰고 이미 아는 이름 없이 AI에게 맡긴다.
function client_scanCaseFilesForNames(params) {
  const apiKey = PropertiesService.getScriptProperties().getProperty('ANTHROPIC_API_KEY');
  if (!apiKey) return { success: false, message: 'ANTHROPIC_API_KEY가 설정되어 있지 않습니다.' };

  // [2026.09.19] 진행상태(사건 전체 목록 포함)는 스크립트 속성이 아니라 캐시서비스에 둔다 —
  // 스크립트 속성은 값 하나에 9KB 한도가 있어 사건이 조금만 많아도 곧바로 넘치지만, 캐시는
  // 값 하나에 100KB까지 허용해 이 정도 규모의 임시 작업 상태를 두기에 더 맞다. 6시간 지나면
  // 자동으로 사라지므로 스캔을 마치지 않고 오래 방치해도 계속 남아있지 않는다.
  const cache = CacheService.getScriptCache();
  let progress = null;
  if (!params || !params.reset) {
    try { progress = JSON.parse(cache.get(CLIENT_NAME_SCAN_PROP_) || 'null'); } catch (e) { progress = null; }
  }

  // [2026.09.19] 진행상태에는 폴더ID만 담는다(사건명·고객명 등은 매 호출 때 시트에서 다시
  // 찾는다) — 사건 폴더가 수백~수천 개면 그 메타데이터까지 통째로 캐시에 넣었을 때 캐시서비스의
  // 값 하나당 100KB 한도도 넘을 수 있어, 가장 작은 단위(폴더ID+known 여부)만 들고 있는다.
  const sheet = work_getSheet_();
  const sheetData = sheet.getDataRange().getValues();
  const sheetCol = work_colMap_(sheetData[0]);
  const caseByFolderId = {};
  for (let i = 1; i < sheetData.length; i++) {
    const 폴더ID = String(sheetData[i][sheetCol.폴더ID] || '').trim();
    if (!폴더ID) continue;
    caseByFolderId[폴더ID] = {
      id: sheetData[i][sheetCol.id], 사건명: String(sheetData[i][sheetCol.사건명] || ''),
      고객명: String(sheetData[i][sheetCol.고객명] || ''), 납세자: String(sheetData[i][sheetCol.납세자] || '')
    };
  }

  if (!progress) {
    const rootFolder = getDefaultFolder();
    const queue = [];
    const subfolders = rootFolder.getFolders();
    while (subfolders.hasNext()) queue.push(subfolders.next().getId());
    progress = { phase: 'discover', queue: queue, units: [], nextIndex: 0, candidates: [], scannedCases: 0 };
  }

  const startTime = Date.now();

  // [2026.09.19 버그수정] "폴더 찾는 단계" 자체도 폴더가 많으면 시간이 걸려 6분 제한을 넘길 수
  // 있어, 스캔 단계와 똑같이 시간예산을 걸고 여러 번에 나눠 이어간다. 이 단계가 안 끝났으면
  // 아직 스캔을 시작하지도 못한 것이므로 화면에는 "폴더 확인 중"으로 보여준다.
  if (progress.phase === 'discover') {
    const expandResult = client_expandScanUnitsStep_(progress.queue, progress.units, caseByFolderId, startTime, CLIENT_NAME_SCAN_TIME_BUDGET_MS_);
    if (expandResult.done) {
      progress.phase = 'scan';
    } else {
      try {
        cache.put(CLIENT_NAME_SCAN_PROP_, JSON.stringify(progress), 21600);
      } catch (err) {
        return { success: false, message: '사건 폴더 구조가 너무 커서 조사를 이어갈 수 없습니다(캐시 용량 초과).' };
      }
      return {
        success: true, done: false, discovering: true,
        scannedCases: 0, totalCases: progress.units.length, candidateCountSoFar: 0
      };
    }
  }

  const units = progress.units;
  while (progress.nextIndex < units.length) {
    if (Date.now() - startTime > CLIENT_NAME_SCAN_TIME_BUDGET_MS_) break;
    const unit = units[progress.nextIndex];
    progress.nextIndex++;
    progress.scannedCases++;
    let folder;
    try { folder = DriveApp.getFolderById(unit.folderId); } catch (err) { continue; } // 삭제되었거나 접근 불가한 폴더는 건너뜀
    const matched = caseByFolderId[unit.folderId];
    // 시트에 연결 안 된(고아) 폴더는 폴더 이름 규칙을 파싱해서 고객명·납세자(상속이면 피상속인)를
    // 최대한 복원한다 — 그래야 이런 폴더에서도 이미 아는 당사자가 "새 이름"으로 잘못 뽑히지 않는다.
    const c = matched || Object.assign({ id: '', 사건명: folder.getName() }, client_parseCaseFolderName_(folder.getName()));
    const fileObjs = [];
    if (unit.known) {
      // 이미 아는 사건 폴더는 "증빙"·"계약서" 같은 하위폴더까지 전부 그 사건의 파일로 본다
      // (하위폴더는 client_expandScanUnitsStep_가 별도 단위로 만들지 않았으므로 여기서 재귀로 챙긴다).
      client_listFilesRecursive_(folder, 0, CLIENT_NAME_SCAN_MAX_FILES_PER_CASE_, fileObjs);
    } else {
      // 모르는 폴더는 그 폴더 "자신"의 파일만 본다 — 하위 폴더는 이미 별도 단위로 등록돼 있어
      // 여기서 재귀로 또 훑으면 같은 파일을 두 번 세게 된다.
      const files = folder.getFiles();
      while (files.hasNext() && fileObjs.length < CLIENT_NAME_SCAN_MAX_FILES_PER_CASE_) {
        const f = files.next();
        fileObjs.push({ id: f.getId(), name: f.getName(), mimeType: f.getMimeType() });
      }
    }
    if (!fileObjs.length) continue;
    const knownNames = [c.고객명, c.납세자].filter(function (n) { return n; });
    let items;
    try { items = client_extractNamesFromFilenames_(c.사건명, knownNames, fileObjs, apiKey); } catch (err) { continue; }
    items.forEach(function (item) {
      // 이름이 나온 파일 중 실제로 열어볼 수 있는 걸 그 사람 몫으로 한 번 더 열어 상세정보를
      // 찾는다 — 파일명에 그 이름이 들어간 첫 번째 파일만 시도한다(여러 개면 비용만 커짐).
      const matchingFile = fileObjs.filter(function (f) { return f.name.indexOf(item.성명) !== -1; })[0];
      let detail = {};
      if (matchingFile) {
        // [2026.10.09] Sonnet이 PDF 전체를 읽던 것을 구글 무료 OCR+규칙(parsePersonDetailText_)으로 — 비용 0원.
        // 실제 등기부·계약서·임대차내역 20건 시험에서 이름 바로 뒤 주민번호·주소·전화를 찾음.
        try { detail = client_extractPersonDetailOCR_(matchingFile.id, matchingFile.mimeType, item.성명); } catch (err) { /* 상세정보 못 찾아도 이름·관계는 남긴다 */ }
      }
      progress.candidates.push(Object.assign({ 사건ID: c.id, 사건명: c.사건명, 성명: item.성명, 관계: item.관계 }, detail));
    });
  }

  const done = progress.nextIndex >= units.length;
  if (done) {
    cache.remove(CLIENT_NAME_SCAN_PROP_);
  } else {
    try {
      cache.put(CLIENT_NAME_SCAN_PROP_, JSON.stringify(progress), 21600); // 최대 6시간
    } catch (err) {
      // 사건 폴더나 후보가 지나치게 많아 캐시 값 한도(100KB)를 넘으면, 지금까지 찾은 후보만
      // 결과로 돌려주고 이어서 진행은 포기한다 — 조용히 무한반복되는 것보다 낫다.
      return {
        success: true, done: true, truncated: true,
        scannedCases: progress.scannedCases, totalCases: units.length,
        candidates: progress.candidates, candidateCountSoFar: progress.candidates.length
      };
    }
  }

  return {
    success: true, done: done,
    scannedCases: progress.scannedCases, totalCases: units.length,
    candidates: done ? progress.candidates : undefined,
    candidateCountSoFar: progress.candidates.length
  };
}

// [2026.09.19] "고객을 찾아도 관련사건을 매치하지 못하는거 아니냐"는 지적으로 추가 —
// 메모에 사건명을 문구로만 남기던 것과 별개로, 사건ID가 있는(=작업관리 시트에 실제로 연결된)
// 경우는 그 사건의 사건개요 "고객추가ID목록"(work_linkPartyClientIds_/WORK_ALWAYS_PARTY_FIELDS_
// 와 같은 공동의뢰인 공용 칸)에 이 고객ID를 추가해, 고객관리 화면의 사건별 역할 배지
// (clientRolesInCase_)에도 실제로 "의뢰인"으로 잡히게 만든다. AI가 구체적으로 추정한 관계
// (예: "공동상속인")까지 세목별 전용 필드(상속인추가ID목록 등)에 정확히 넣지는 않는다 — 잘못
// 짚었을 때 엉뚱한 역할로 오염시키는 것보다, 일단 "이 사건과 관계있다"는 것만 공용 칸에
// 안전하게 남기고 구체적 관계는 메모의 문구로만 남긴다. 고아 폴더(사건ID 없음)는 애초에
// 연결할 사건 자체가 시트에 없어 이 연결을 만들 수 없다 — 그런 경우는 메모만 남는다.
function client_linkClientToCaseOverview_(caseId, clientId) {
  if (!caseId || !clientId) return;
  const sheet = work_getSheet_();
  const data = sheet.getDataRange().getValues();
  const col = work_colMap_(data[0]);
  for (let i = 1; i < data.length; i++) {
    if (String(data[i][col.id]) !== String(caseId)) continue;
    let overview;
    try { overview = JSON.parse(data[i][col.사건개요] || '{}'); } catch (e) { overview = {}; }
    if (!overview || typeof overview !== 'object' || Array.isArray(overview)) overview = {};
    const ids = Array.isArray(overview['고객추가ID목록']) ? overview['고객추가ID목록'] : [];
    if (ids.indexOf(clientId) === -1) {
      ids.push(clientId);
      overview['고객추가ID목록'] = ids;
      sheet.getRange(i + 1, col.사건개요 + 1).setValue(JSON.stringify(overview));
    }
    return;
  }
}

// [2026.09.19] "등록할 때 관계나 출처를 어떻게 기록할 거냐" → 메모에 사건·추정관계를 남기고,
// 이어서 "이름외의 정보는 아예 안 찾은 거냐"는 지적으로 파일 내용에서 찾은 전화번호·주소·
// 주민등록번호(있는 경우만)도 같이 저장하도록 확장했다. 상세정보는 전부 새로 만들어지는
// 고객에 한해서만 채운다(이미 있던 고객은 기존 값을 덮어쓰지 않음 — 잘못 읽었을 위험이 있는
// AI 추출값으로 기존의 신뢰할 수 있는 데이터를 손상시키지 않기 위함). 사건 연결(위 함수)은
// 새 고객이든 기존 고객이든 상관없이 항상 시도한다.
function client_applyScannedNames(params) {
  return withLock_(60000, function () {
    const items = (params && params.items) || [];
    let registered = 0;
    items.forEach(function (item) {
      const name = String(item.성명 || '').trim();
      if (!name) return;
      try {
        const result = client_findOrCreateByName_(name, item.전화번호);
        registered++;
        if (item.사건ID) client_linkClientToCaseOverview_(item.사건ID, result.id);
        if (result.isNew) {
          const note = '[AI 전수조사] 사건: ' + (item.사건명 || '(미상)') + (item.관계 ? ' · 추정관계: ' + item.관계 : '');
          const sheets = client_getSheets_();
          const col = client_colMap_(sheets.clients.getDataRange().getValues()[0], CLIENT_HEADERS);
          const found = client_findRow_(sheets.clients, col, result.id);
          if (found) {
            sheets.clients.getRange(found.rowIndex, col.메모 + 1).setValue(note);
            if (item.주소) sheets.clients.getRange(found.rowIndex, col.주소 + 1).setValue(String(item.주소));
            if (item.주민등록번호) {
              sheets.clients.getRange(found.rowIndex, col.주민등록번호암호화 + 1)
                .setNumberFormat('@').setValue(client_encryptRRN_(item.주민등록번호));
            }
          }
        }
      } catch (err) { /* 개별 실패는 건너뛰고 계속 진행 */ }
    });
    return { success: true, registered: registered };
  });
}

// [2026.09.19 신규, 1회성] "고객명단에서 실명이 아닌 숫자와 같은 이름은 삭제해달라" — 구글
// 시트가 "3733"처럼 숫자로만 된 값을 실제 숫자 타입으로 저장해버리는 옛 버그(client_readClient_
// 등에서 이미 String() 강제로 고쳤음) 때문에 생긴 것으로 보이는, 성명이 순수 숫자인 고객
// 레코드를 찾아 정리한다. 진행 중인 사건이 연결된 고객은 실수로 지우면 안 되므로 건너뛰고
// 별도로 세어 보여준다(다른 1회성 정비도구와 같은 미리보기 후 적용 원칙).
function client_findNumericNameClients_() {
  const sheets = client_getSheets_();
  const data = sheets.clients.getDataRange().getValues();
  const col = client_colMap_(data[0], CLIENT_HEADERS);
  const results = [];
  for (let i = 1; i < data.length; i++) {
    const name = String(data[i][col.성명] || '').trim();
    if (name && /^\d+$/.test(name)) {
      results.push({ rowIndex: i + 1, id: String(data[i][col.id]), 성명: name });
    }
  }
  return results;
}

function client_deleteNumericNameClients(params) {
  return withLock_(60000, function () {
    const matches = client_findNumericNameClients_();
    if (!params || !params.apply) return { success: true, dryRun: true, count: matches.length, items: matches };

    const workSheet = work_getSheet_();
    const workData = workSheet.getDataRange().getValues();
    const workCol = work_colMap_(workData[0]);
    const activeClientIds = {};
    for (let i = 1; i < workData.length; i++) {
      if (String(workData[i][workCol.상태] || '') !== '완료') activeClientIds[String(workData[i][workCol.고객ID])] = true;
    }

    const sheets = client_getSheets_();
    let deleted = 0, skipped = 0;
    // 뒤에서부터 지워야 앞쪽 남은 행들의 인덱스가 안 밀린다.
    matches.slice().reverse().forEach(function (m) {
      if (activeClientIds[m.id]) { skipped++; return; }
      sheets.clients.deleteRow(m.rowIndex);
      deleted++;
    });
    return { success: true, applied: deleted, skipped: skipped };
  });
}

const CONSULT_HEADERS = ['id', '고객ID', '고객명', '날짜', '담당자', '유형', '내용', '관계', '금액', '수취증빙', '리뷰', '생성일', '승인번호', '사건ID', '중복정리'];

function client_getSheets_() {
  const ss = SpreadsheetApp.openById(CLIENT_SHEET_ID);
  return { ss: ss, clients: client_ensureSheet_(ss, CLIENT_SHEET_CLIENTS, CLIENT_HEADERS), log: client_ensureSheet_(ss, CLIENT_SHEET_LOG, CONSULT_HEADERS) };
}

// work_getSheet_와 같은 자가치유 방식 — 시트가 없으면 헤더까지 만들고, 있는데 헤더가 모자라면
// (스키마가 나중에 늘어난 경우) 빠진 헤더만 뒤에 이어붙인다.
function client_ensureSheet_(ss, name, headers) {
  let sheet = ss.getSheetByName(name);
  if (!sheet) {
    sheet = ss.insertSheet(name);
    sheet.appendRow(headers);
    return sheet;
  }
  const lastCol = Math.max(sheet.getLastColumn(), 1);
  const existing = sheet.getRange(1, 1, 1, lastCol).getValues()[0];
  const missing = headers.filter(function (h) { return existing.indexOf(h) === -1; });
  if (missing.length > 0) {
    sheet.getRange(1, existing.length + 1, 1, missing.length).setValues([missing]);
  }
  return sheet;
}

function client_colMap_(headers, headerList) {
  const map = {};
  headerList.forEach(function (name) { map[name] = headers.indexOf(name); });
  return map;
}

function client_dateStr_(v) {
  if (!v) return '';
  if (v instanceof Date) return Utilities.formatDate(v, Session.getScriptTimeZone(), 'yyyy-MM-dd');
  return String(v).slice(0, 10);
}

function client_findRow_(sheet, col, id) {
  const data = sheet.getDataRange().getValues();
  for (let i = 1; i < data.length; i++) {
    if (String(data[i][col.id]).trim() === String(id).trim()) return { rowIndex: i + 1, row: data[i] };
  }
  return null;
}

// [2026.09.16] 추가연락처는 "전화번호만 있으면 누구 건지 모른다"는 지적에 따라 자유텍스트
// 문자열이 아니라 {이름, 전화번호} 목록(JSON)으로 저장한다. 이 기능이 배포된 지 얼마 안 돼
// 실제 데이터가 있을 가능성은 낮지만, 혹시 그 사이 입력된 옛 문자열 형식("010-1,010-2")도
// 이름 없이(전화번호만이라도) 안 잃어버리게 최대한 살려서 배열로 바꿔준다.
// 화면에서 배열([{이름,전화번호},...])로 보내오면 그대로 직렬화하고, 혹시 문자열이 오면
// (하위호환) 그대로 저장한다 — client_parseExtraContacts_가 읽을 때 다시 풀어준다.
function client_serializeExtraContacts_(input) {
  if (Array.isArray(input)) {
    return JSON.stringify(input.filter(function (c) { return c && String(c.전화번호 || '').trim(); })
      .map(function (c) { return { 이름: String(c.이름 || '').trim(), 전화번호: String(c.전화번호 || '').trim() }; }));
  }
  return String(input || '');
}

function client_parseExtraContacts_(raw) {
  if (!raw) return [];
  try {
    const parsed = JSON.parse(raw);
    if (Array.isArray(parsed)) return parsed.filter(function (p) { return p && p.전화번호; }).map(function (p) { return { 이름: String(p.이름 || ''), 전화번호: String(p.전화번호 || '') }; });
  } catch (e) { /* 아래 옛 형식(콤마구분 전화번호) 처리로 진행 */ }
  return client_splitPhoneNumbers_(raw).map(function (phone) { return { 이름: '', 전화번호: phone }; });
}

function client_readClient_(col, row) {
  // [2026.09.16 버그수정] 구글 시트는 "3733"처럼 숫자로만 된 값을 실제 숫자 타입으로 저장해버린다
  // — 이미 work_readRow_(WORK_CASES의 고객명/납세자)에서 같은 문제를 겪고 고쳤는데, 고객관리의
  // 성명에서도 똑같이 터졌다(화면에서 .localeCompare is not a function으로 확인). 문자열로
  // 강제하지 않으면 이 값을 문자열 메서드로 다루는 곳(정렬 등)에서 예외가 나서 고객관리 탭
  // 전체가 조용히 멈춘다.
  return {
    id: row[col.id], 성명: String(row[col.성명] || ''), 전화번호: String(row[col.전화번호] || ''), 구분: row[col.구분],
    사업자번호: String(row[col.사업자번호] || ''), 메모: row[col.메모],
    등록일: client_dateStr_(row[col.등록일]), 수정일: client_dateStr_(row[col.수정일]),
    추가연락처: client_parseExtraContacts_(row[col.추가연락처]),
    주소: String(row[col.주소] || ''),
    // [2026.09.19 신규] 주민등록번호는 암호문조차 목록 조회에 안 실어보낸다 — 등록 여부만
    // 알려주고, 실제 값은 client_getRRN을 따로 호출했을 때만(화면의 "보기" 버튼) 내려준다.
    주민번호등록됨: !!String(row[col.주민등록번호암호화] || '').trim()
  };
}

// "010-1234-5678, 010-9999-8888" 같은 자유 입력에서 번호별로 숫자만 남긴 목록을 뽑는다.
// 쉼표/줄바꿈으로만 번호를 나누고, 그 안의 하이픈·공백은 한 번호에 속한 것으로 보고 전부
// 붙여서 숫자만 남긴다 — 하이픈 기준으로 통째로 쪼개면 "010-1111-2222"의 가운데 토막
// "1111"이 마치 별도 번호의 뒷4자리인 것처럼 잘못 매칭될 수 있다.
function client_splitPhoneNumbers_(raw) {
  return String(raw || '').split(/[,\n]+/)
    .map(function (s) { return s.replace(/[^0-9]/g, ''); })
    .filter(function (s) { return s.length >= 4; });
}

function client_readLog_(col, row) {
  return {
    id: row[col.id], 고객ID: row[col.고객ID], 고객명: row[col.고객명],
    날짜: client_dateStr_(row[col.날짜]), 담당자: row[col.담당자], 유형: row[col.유형],
    내용: row[col.내용], 관계: row[col.관계], 금액: row[col.금액], 수취증빙: row[col.수취증빙], 리뷰: row[col.리뷰],
    생성일: row[col.생성일], 승인번호: row[col.승인번호], 사건ID: row[col.사건ID],
    중복정리: row[col.중복정리] || ''
  };
}

function client_getClients(params) {
  const sheets = client_getSheets_();
  const data = sheets.clients.getDataRange().getValues();
  const col = client_colMap_(data[0], CLIENT_HEADERS);
  const q = String((params && params.search) || '').trim();
  const clients = [];
  for (let i = 1; i < data.length; i++) {
    if (!data[i][col.id]) continue;
    if (q && String(data[i][col.성명] || '').indexOf(q) === -1) continue;
    clients.push(client_readClient_(col, data[i]));
  }
  return { success: true, clients: clients };
}

// [2026.09.16 신규] "한 고객이 2개 이상의 사건에 관여하면 고객관리를 합쳐야 하지 않나?" —
// 이미 설계상 새 사건은 이름(+전화번호)으로 기존 고객을 찾아 같은 고객ID를 재사용하지만
// (client_findOrCreateByName_), 이름이 오타·표기차이로 다르게 들어가면 매칭에 실패해 같은
// 사람이 고객 두 명으로 쪼개질 수 있다. 이름이 같거나(공백 제거 후 완전일치) 전화번호가
// 같은데 고객ID가 다른 경우를 찾아 묶어준다(연쇄적으로 겹치는 경우까지 한 그룹으로 묶기
// 위해 union-find 사용 — 예: A·B가 이름이 같고 B·C가 전화번호가 같으면 A·B·C를 한 그룹으로).
function client_auditDuplicates_() {
  const sheets = client_getSheets_();
  const data = sheets.clients.getDataRange().getValues();
  const col = client_colMap_(data[0], CLIENT_HEADERS);
  const workSheet = work_getSheet_();
  const wdata = workSheet.getDataRange().getValues();
  const wcol = work_colMap_(wdata[0]);
  const caseCountByClientId = {};
  for (let i = 1; i < wdata.length; i++) {
    const cid = String(wdata[i][wcol.고객ID] || '').trim();
    if (cid) caseCountByClientId[cid] = (caseCountByClientId[cid] || 0) + 1;
  }
  const rows = [];
  for (let i = 1; i < data.length; i++) {
    const id = String(data[i][col.id] || '').trim();
    if (!id) continue;
    rows.push({
      id: id,
      성명: String(data[i][col.성명] || '').trim(),
      전화번호: String(data[i][col.전화번호] || '').trim(),
      구분: data[i][col.구분] || '',
      등록일: work_dateStr_(data[i][col.등록일]),
      사건수: caseCountByClientId[id] || 0
    });
  }
  const parent = {};
  function find(x) { while (parent[x] && parent[x] !== x) x = parent[x]; return x; }
  function union(a, b) { const ra = find(a), rb = find(b); if (ra !== rb) parent[ra] = rb; }
  rows.forEach(function (r) { parent[r.id] = r.id; });
  const byName = {}, byPhone = {};
  rows.forEach(function (r) {
    if (r.성명) {
      const k = r.성명.replace(/\s+/g, '');
      if (byName[k]) union(r.id, byName[k]); else byName[k] = r.id;
    }
    if (r.전화번호) {
      const k = r.전화번호.replace(/[^0-9]/g, '');
      if (k) { if (byPhone[k]) union(r.id, byPhone[k]); else byPhone[k] = r.id; }
    }
  });
  const clusters = {};
  rows.forEach(function (r) { const root = find(r.id); (clusters[root] = clusters[root] || []).push(r); });
  const result = [];
  Object.keys(clusters).forEach(function (root) {
    const members = clusters[root];
    if (members.length < 2) return;
    result.push({ members: members });
  });
  result.sort(function (a, b) { return b.members.length - a.members.length; });
  return result;
}
function client_auditDuplicatesAction_(body) {
  const groups = client_auditDuplicates_();
  return { success: true, count: groups.length, groups: groups };
}
// [2026.09.19 버그수정] "남은 기능도 재검토하라"는 지적으로 발견 — 이 병합 도구는 Thread C
// (사건개요의 공동의뢰인·양도인·증여인·수증인·상속인·납세자·임직원 ID 배열, work_linkPartyClientIds_
// 참고)와 Thread D(주소·주민등록번호암호화·메모) 필드가 생기기 전에 만들어져서 그 둘을 전혀
// 모른다. 그대로 두면 (1) 합쳐져서 삭제되는 고객의 ID가 어느 사건의 사건개요 안에 공동
// 관계자로 박혀 있었다면, 그 참조는 삭제된 고객ID를 가리킨 채 고아로 남아 역할 배지가
// 조용히 사라지고 (2) 병합돼 사라지는 고객 쪽에만 주소·주민등록번호·메모가 채워져 있었다면
// 그 값이 통째로 유실된다. 사건개요 안의 모든 ID/ID배열 필드에서 합쳐지는 고객ID를 남는
// 고객ID로 바꿔주고, 남는 고객의 해당 칸이 비어있으면 병합되는 고객 쪽 값으로 채운 뒤에
// 삭제한다.
function client_remapPartyIdsInOverview_(overview, mergeIds, keepId) {
  if (!overview || typeof overview !== 'object' || Array.isArray(overview)) return false;
  let changed = false;
  const allFieldDefs = Object.keys(WORK_PARTY_NAME_TO_ID_FIELDS_)
    .reduce(function (acc, seMok) { return acc.concat(WORK_PARTY_NAME_TO_ID_FIELDS_[seMok]); }, [])
    .concat(WORK_ALWAYS_PARTY_FIELDS_);
  allFieldDefs.forEach(function (f) {
    if (f.idField) {
      if (mergeIds.indexOf(String(overview[f.idField] || '')) !== -1) {
        overview[f.idField] = keepId;
        changed = true;
      }
    } else if (f.idsField && Array.isArray(overview[f.idsField])) {
      const ids = overview[f.idsField].map(String);
      let touched = false;
      const remapped = ids.map(function (id) {
        if (mergeIds.indexOf(id) !== -1) { touched = true; return keepId; }
        return id;
      }).filter(function (id, idx, arr) { return arr.indexOf(id) === idx; }); // 중복 제거(병합 전에 이미 둘 다 있었을 경우)
      if (touched) {
        overview[f.idsField] = remapped;
        changed = true;
      }
    }
  });
  return changed;
}

// 세무사님이 고른 "유지할 고객" 하나로 "합칠 고객들"의 사건·자문내역을 전부 재연결하고,
// 관련된 my.netax.kr 표시용 고객명도 맞춘 뒤, 합쳐진 고객 레코드는 삭제한다.
// [2026.09.17 확장] "자문내역, MY페이지도 합쳐야지" — 처음엔 사건(WORK_CASES)만 옮겼는데,
// 확인해보니 자문내역(CONSULT_LOGS)도 WORK_CASES와 똑같이 고객ID 컬럼을 직접 갖고 있어서
// 그대로 두면 자문내역 조회 시 병합 전 고객ID로는 안 잡히는 내역이 남는다 — 사건과 동일하게
// 재배정한다. my.netax.kr(MY_SHEET_CASES)은 반대로 고객ID 자체가 없고 report_id 단위로
// 독립된 행마다 "고객명" 텍스트만 따로 들고 있어(고객ID로 병합할 대상이 없음) — 대신 이번에
// 옮겨진 사건들의 report_id를 찾아 그 표시용 고객명만 남긴 고객의 성명으로 맞춰준다.
function client_mergeClients(params) {
  return withLock_(15000, function () {
    const keepId = String(params.keepId || '').trim();
    const mergeIds = (Array.isArray(params.mergeIds) ? params.mergeIds : []).map(String).filter(function (x) { return x && x !== keepId; });
    if (!keepId || !mergeIds.length) return { success: false, message: 'keepId 또는 mergeIds가 없습니다.' };
    const sheets = client_getSheets_();
    const cdata = sheets.clients.getDataRange().getValues();
    const ccol = client_colMap_(cdata[0], CLIENT_HEADERS);
    let keepName = '';
    for (let i = 1; i < cdata.length; i++) { if (String(cdata[i][ccol.id]) === keepId) { keepName = String(cdata[i][ccol.성명] || '').trim(); break; } }
    if (!keepName) return { success: false, message: '유지할 고객을 찾을 수 없습니다.' };

    const workSheet = work_getSheet_();
    const wdata = workSheet.getDataRange().getValues();
    const wcol = work_colMap_(wdata[0]);
    let movedCases = 0;
    const movedReportIds = [];
    for (let i = 1; i < wdata.length; i++) {
      if (mergeIds.indexOf(String(wdata[i][wcol.고객ID] || '').trim()) !== -1) {
        workSheet.getRange(i + 1, wcol.고객ID + 1).setValue(keepId);
        movedCases++;
        const rid = String(wdata[i][wcol.my_report_id] || '').trim();
        if (rid) movedReportIds.push(rid);
      }
    }

    // [2026.09.19 버그수정] 위는 사건의 "주" 고객ID(의뢰인)만 옮긴다 — 합쳐지는 고객이 어느
    // 사건에 공동상속인·양도인 등 "관계자"로만 등장했다면(사건의 주 고객ID가 아닌 사건개요
    // 안의 참조), 그 사건은 위 루프에 안 걸린다. 사건개요를 가진 모든 사건을 훑어 그 안의
    // 모든 관계자 ID/ID배열에서도 병합되는 고객ID를 남는 고객ID로 바꿔준다.
    let movedPartyLinks = 0;
    for (let i = 1; i < wdata.length; i++) {
      const raw = wdata[i][wcol.사건개요];
      if (!raw) continue;
      let overview;
      try { overview = JSON.parse(raw); } catch (e) { continue; }
      if (client_remapPartyIdsInOverview_(overview, mergeIds, keepId)) {
        workSheet.getRange(i + 1, wcol.사건개요 + 1).setValue(JSON.stringify(overview));
        movedPartyLinks++;
      }
    }

    const logSheet = sheets.log;
    const ldata = logSheet.getDataRange().getValues();
    const lcol = client_colMap_(ldata[0], CONSULT_HEADERS);
    let movedLogs = 0;
    for (let i = 1; i < ldata.length; i++) {
      if (mergeIds.indexOf(String(ldata[i][lcol.고객ID] || '').trim()) !== -1) {
        logSheet.getRange(i + 1, lcol.고객ID + 1).setValue(keepId);
        movedLogs++;
      }
    }

    let movedMyPages = 0;
    if (movedReportIds.length) {
      try {
        const myCasesSheet = SpreadsheetApp.openById(MY_SHEET_ID).getSheetByName(MY_SHEET_CASES);
        if (myCasesSheet) {
          const mdata = myCasesSheet.getDataRange().getValues();
          const mcol = my_colMap_(mdata[0]);
          for (let i = 1; i < mdata.length; i++) {
            if (movedReportIds.indexOf(String(mdata[i][mcol.report_id] || '').trim()) !== -1) {
              myCasesSheet.getRange(i + 1, mcol.고객명 + 1).setValue(keepName);
              movedMyPages++;
            }
          }
        }
      } catch (err) {
        console.log('my.netax.kr 고객명 동기화 실패: ' + err.message);
      }
    }

    // [2026.09.19 버그수정] 남는 고객의 주소·주민등록번호(암호화된 값 그대로 복사 — 같은 키를
    // 쓰므로 복호화 없이 옮겨도 그대로 유효)·메모가 비어있는데 합쳐져서 사라지는 고객 쪽에
    // 값이 있으면, 지우기 전에 남는 고객 쪽으로 옮겨준다 — 안 그러면 "둘 중 하나만 입력해둔
    // 정보"가 병합 한 번에 영구히 사라진다.
    let keepRowIndex = -1;
    for (let i = 1; i < cdata.length; i++) { if (String(cdata[i][ccol.id]) === keepId) { keepRowIndex = i + 1; break; } }
    if (keepRowIndex !== -1) {
      const keepRow = cdata[keepRowIndex - 1];
      ['주소', '주민등록번호암호화', '메모'].forEach(function (field) {
        if (String(keepRow[ccol[field]] || '').trim()) return; // 남는 쪽에 이미 값이 있으면 안 건드림
        for (let i = 1; i < cdata.length; i++) {
          if (mergeIds.indexOf(String(cdata[i][ccol.id])) === -1) continue;
          const donorVal = cdata[i][ccol[field]];
          if (String(donorVal || '').trim()) {
            sheets.clients.getRange(keepRowIndex, ccol[field] + 1).setValue(donorVal);
            break;
          }
        }
      });
    }

    const rowsToDelete = [];
    for (let i = 1; i < cdata.length; i++) {
      if (mergeIds.indexOf(String(cdata[i][ccol.id])) !== -1) rowsToDelete.push(i + 1);
    }
    rowsToDelete.sort(function (a, b) { return b - a; }).forEach(function (rowNum) { sheets.clients.deleteRow(rowNum); });
    return { success: true, movedCases: movedCases, movedLogs: movedLogs, movedMyPages: movedMyPages, movedPartyLinks: movedPartyLinks, deletedClients: rowsToDelete.length };
  });
}

// 이름으로 고객을 찾고, 없으면 그 자리에서 새로 만든다. work_ 모듈(사건 등록)과 자문내역 등록
// 양쪽에서 "고객명만 입력해도 자동으로 고객관리 명단에 연결/등록"되게 하는 공용 함수.
function client_findOrCreateByName_(name, phone) {
  const trimmed = String(name || '').trim();
  const phoneTrimmed = String(phone || '').trim();
  return withLock_(8000, function () {
    const sheets = client_getSheets_();
    const data = sheets.clients.getDataRange().getValues();
    const col = client_colMap_(data[0], CLIENT_HEADERS);
    // [2026.09 버그수정] 동명이인 — 이름만 같으면 무조건 같은 고객으로 합쳐서, 실제로는 다른
    // 사람(전화번호가 서로 다름)인데 기존 고객 레코드에 새 사건이 잘못 연결되고, 나중에 그
    // 사건의 고객명을 고치면 엉뚱하게 기존 고객의 진짜 이름까지 바뀌어버리는 사고가 있었다.
    // 전화번호가 둘 다 있고 서로 다르면 같은 사람으로 보지 않고 새 고객으로 등록한다(전화번호가
    // 아예 없을 때는 예전처럼 이름만으로 매칭 — 하위호환 유지).
    let nameConflict = false;
    for (let i = 1; i < data.length; i++) {
      if (String(data[i][col.성명] || '').trim() !== trimmed) continue;
      const existingPhone = String(data[i][col.전화번호] || '').trim();
      if (phoneTrimmed && existingPhone && existingPhone !== phoneTrimmed) {
        nameConflict = true;
        continue;
      }
      const rowIndex = i + 1;
      // 기존 고객인데 전화번호가 비어있으면(과거엔 예약 정보가 전달 안 돼 빈 채로
      // 생성됐을 수 있음) 이번에 받은 번호로 채워준다 — 이미 값이 있으면 덮어쓰지 않음.
      if (phoneTrimmed && !existingPhone) {
        // [2026.09 버그수정] client_createClient/client_updateClient와 달리 여기는 텍스트
        // 서식(@) 없이 그냥 setValue만 해서, 대시 없는 순수 숫자 전화번호(예약에서 넘어온 값)의
        // 앞자리 0이 날아가는 문제가 있었다.
        sheets.clients.getRange(rowIndex, col.전화번호 + 1).setNumberFormat('@').setValue(phoneTrimmed);
      }
      return { id: data[i][col.id], isNew: false };
    }
    const id = Utilities.getUuid();
    const now = new Date();
    const newRow = [];
    newRow[col.id] = id;
    newRow[col.성명] = trimmed;
    newRow[col.전화번호] = phoneTrimmed;
    // [2026.09.16 버그수정] "전화번호가 있으면 고객분류가 표시되고 없으면 표시 안 된다"는
    // 지적 — 원인은 전화번호 유무가 아니라, 이 함수(사건 생성 등에서 이름만으로 고객을
    // 자동등록할 때 씀)가 구분(로얄/우수/보통/영세)을 아예 안 채워서였다. "+ 새 고객" 폼은
    // 항상 "보통"이 기본 선택이고(clientmanage.html CLIENT_TIER_OPTIONS_), 수정 화면도 구분이
    // 비어있으면 "보통"으로 간주하므로(`c.구분 || '보통'`), 자동등록 때도 같은 기본값을 명시적으로 써서 맞춘다.
    newRow[col.구분] = '보통';
    newRow[col.등록일] = now;
    newRow[col.수정일] = now;
    const newRowIndex = sheets.clients.getLastRow() + 1;
    // 위와 같은 이유로, 신규 고객 자동등록 시에도 쓰기 전에 전화번호 칸을 텍스트 서식으로 고정한다.
    sheets.clients.getRange(newRowIndex, col.전화번호 + 1).setNumberFormat('@');
    sheets.clients.getRange(newRowIndex, 1, 1, newRow.length).setValues([newRow]);
    SpreadsheetApp.flush();
    return { id: id, isNew: true, nameConflict: nameConflict };
  });
}

function client_createClient(params) {
  const 성명 = String(params.성명 || '').trim();
  if (!성명) return { success: false, message: '성명이 필요합니다.' };
  return withLock_(8000, function () {
    const sheets = client_getSheets_();
    const col = client_colMap_(sheets.clients.getDataRange().getValues()[0], CLIENT_HEADERS);
    const id = Utilities.getUuid();
    const now = new Date();
    const newRow = [];
    newRow[col.id] = id;
    newRow[col.성명] = 성명;
    newRow[col.전화번호] = String(params.전화번호 || '').trim();
    newRow[col.구분] = String(params.구분 || '').trim();
    newRow[col.사업자번호] = String(params.사업자번호 || '').trim();
    newRow[col.메모] = String(params.메모 || '').trim();
    newRow[col.등록일] = now;
    newRow[col.수정일] = now;
    newRow[col.추가연락처] = client_serializeExtraContacts_(params.추가연락처);
    newRow[col.주소] = String(params.주소 || '').trim();
    newRow[col.주민등록번호암호화] = client_encryptRRN_(params.주민등록번호);
    const rowIndex = sheets.clients.getLastRow() + 1;
    // [2026.08 버그수정] 전화번호·납세번호를 대시 없이 순수 숫자로 입력하면 구글시트가
    // 그 값을 숫자로 인식해 앞자리 0을 날려버리는 문제가 실제로 있었다(사용자가 직접 겪음)
    // — 쓰기 전에 그 두 칸을 강제로 텍스트 서식("@")으로 잡아두면 숫자로 오인되지 않는다.
    sheets.clients.getRange(rowIndex, col.전화번호 + 1).setNumberFormat('@');
    sheets.clients.getRange(rowIndex, col.사업자번호 + 1).setNumberFormat('@');
    sheets.clients.getRange(rowIndex, col.추가연락처 + 1).setNumberFormat('@');
    sheets.clients.getRange(rowIndex, col.주민등록번호암호화 + 1).setNumberFormat('@');
    sheets.clients.getRange(rowIndex, 1, 1, newRow.length).setValues([newRow]);
    SpreadsheetApp.flush();
    return { success: true, client: client_readClient_(col, newRow) };
  });
}

function client_updateClient(params) {
  return withLock_(8000, function () {
    const sheets = client_getSheets_();
    const col = client_colMap_(sheets.clients.getDataRange().getValues()[0], CLIENT_HEADERS);
    const found = client_findRow_(sheets.clients, col, params.id);
    if (!found) return { success: false, message: '존재하지 않는 고객입니다.' };
    const row = found.row;
    const oldName = String(row[col.성명] || '').trim();
    ['성명', '전화번호', '구분', '사업자번호', '메모', '주소'].forEach(function (key) {
      if (params[key] !== undefined) row[col[key]] = String(params[key]).trim();
    });
    // 추가연락처는 배열({이름,전화번호} 목록)로 오므로 다른 필드처럼 그냥 String()하면
    // "[object Object]"가 되어버린다 — 전용 직렬화 함수를 거친다.
    if (params.추가연락처 !== undefined) row[col.추가연락처] = client_serializeExtraContacts_(params.추가연락처);
    // [2026.09.19 신규] 주민등록번호는 화면이 "변경할 때만" 값을 채워 보낸다(평소엔 비워둠 —
    // 목록 조회에 값 자체를 안 내려주므로 "기존 값을 그대로 되돌려보내는" 방식 자체가
    // 불가능하기도 하다). 값이 왔을 때만 암호화해서 덮어쓰고, 안 왔으면 기존 암호문을 그대로 둔다.
    if (params.주민등록번호 !== undefined && String(params.주민등록번호).trim()) {
      row[col.주민등록번호암호화] = client_encryptRRN_(params.주민등록번호);
    }
    row[col.수정일] = new Date();
    // 전화번호·납세번호 칸은 저장할 때마다 텍스트 서식으로 다시 잡아둔다(create와 같은 이유).
    sheets.clients.getRange(found.rowIndex, col.전화번호 + 1).setNumberFormat('@');
    sheets.clients.getRange(found.rowIndex, col.사업자번호 + 1).setNumberFormat('@');
    sheets.clients.getRange(found.rowIndex, col.추가연락처 + 1).setNumberFormat('@');
    sheets.clients.getRange(found.rowIndex, col.주민등록번호암호화 + 1).setNumberFormat('@');
    sheets.clients.getRange(found.rowIndex, 1, 1, row.length).setValues([row]);
    SpreadsheetApp.flush();
    // [2026.09 버그수정] 사건 쪽에서 고객명을 고치면 연결된 고객 레코드 이름도 같이 바뀌도록
    // 이미 고쳐뒀는데(work_updateCase), 반대 방향(고객관리에서 직접 개명)은 안 챙겨져 있었다 —
    // 그대로 두면 고객관리엔 새 이름, 이미 등록된 사건·대시보드·Drive 폴더명엔 옛 이름이 남아
    // 계속 따로 논다. 이 고객에게 연결된 모든 사건의 고객명을 같이 갱신한다(사건명·Drive
    // 폴더명은 자동으로 안 바뀌는 기존 정책 그대로 유지 — 필요하면 사건별로 직접 재저장).
    const newName = String(row[col.성명] || '').trim();
    if (newName && newName !== oldName) {
      try {
        const workSheet = work_getSheet_();
        const workData = workSheet.getDataRange().getValues();
        const workCol = work_colMap_(workData[0]);
        for (let i = 1; i < workData.length; i++) {
          if (String(workData[i][workCol.고객ID] || '') === String(params.id)) {
            workSheet.getRange(i + 1, workCol.고객명 + 1).setValue(newName);
            // [2026.09 버그수정] 이름만 바꾸고 수정일을 안 올리면, 그 사건을 이미 열어둔 다른
            // 화면(작업관리 등)의 기대수정일 낙관적 잠금이 이 변경을 못 알아채 그대로 통과되고,
            // 그 화면이 저장될 때 방금 반영한 새 이름이 옛 이름으로 조용히 덮어써진다.
            workSheet.getRange(i + 1, workCol.수정일 + 1).setValue(new Date());
          }
        }
      } catch (err) {
        console.log('고객 개명을 연결된 사건에 반영 실패: ' + err.message);
      }
    }
    return { success: true, client: client_readClient_(col, row) };
  });
}

// [2026.09 버그수정] 진행 중인 사건이 있는 고객을 지우면, 그 사건의 고객ID 연결이 끊겨
// "👤 고객정보 빠른보기"가 에러를 냈다 — 경고 없이 지워지던 것을 막는다. 이미 끝난(완료)
// 사건만 있으면(기록 보존 목적이므로) 그대로 삭제를 허용한다.
function client_deleteClient(params) {
  return withLock_(8000, function () {
    const sheets = client_getSheets_();
    const col = client_colMap_(sheets.clients.getDataRange().getValues()[0], CLIENT_HEADERS);
    const found = client_findRow_(sheets.clients, col, params.id);
    if (!found) return { success: false, message: '존재하지 않는 고객입니다.' };

    if (!params.force) {
      const workSheet = work_getSheet_();
      const workData = workSheet.getDataRange().getValues();
      const workCol = work_colMap_(workData[0]);
      const activeCases = [];
      for (let i = 1; i < workData.length; i++) {
        if (workData[i][workCol.고객ID] === params.id && workData[i][workCol.상태] !== '완료') {
          activeCases.push(workData[i][workCol.사건명]);
        }
      }
      if (activeCases.length) {
        return {
          success: false,
          message: '진행 중인 사건이 있어 삭제할 수 없습니다: ' + activeCases.join(', ') + '. 그래도 삭제하려면 다시 시도해주세요.',
          hasActiveCases: true
        };
      }
    }

    sheets.clients.deleteRow(found.rowIndex);
    return { success: true };
  });
}

// [2026.09.18 신규] "현금영수증 파일을 보내줘야 하는데 보낼 방법이 없다" — 고객관리에서 그
// 고객에게 바로 문자를 보낼 수 있게 한다. work_sendMyPortalSms(포털 안내 문자)와 같은
// SOLAPI 발송(booking_sendSMS)을 그대로 재사용 — 파일 자체를 문자에 첨부할 방법은 없으므로
// (SOLAPI 문자는 텍스트만 지원), 파일을 보낼 땐 증빙관리에서 공유링크를 복사해 메시지에
// 붙여넣는 방식으로 안내한다(자유 텍스트라 링크든 뭐든 그대로 보낼 수 있음).
function client_sendSms(params) {
  const clientId = String(params.고객ID || '').trim();
  const message = String(params.message || '').trim();
  if (!clientId) return { success: false, message: '고객ID가 필요합니다.' };
  if (!message) return { success: false, message: '메시지를 입력해주세요.' };
  const sheets = client_getSheets_();
  const col = client_colMap_(sheets.clients.getDataRange().getValues()[0], CLIENT_HEADERS);
  const found = client_findRow_(sheets.clients, col, clientId);
  if (!found) return { success: false, message: '존재하지 않는 고객입니다.' };
  const phone = String(found.row[col.전화번호] || '').trim();
  if (!phone) return { success: false, message: '이 고객의 전화번호가 등록되어 있지 않습니다.' };
  const smsResult = booking_sendSMS(phone, message);
  if (!smsResult || smsResult.success === false) {
    return { success: false, message: '문자 발송에 실패했습니다' + (smsResult && smsResult.message ? ': ' + smsResult.message : '') + '.' };
  }
  return { success: true };
}

function client_getConsultLogs(params) {
  const sheets = client_getSheets_();
  const data = sheets.log.getDataRange().getValues();
  const col = client_colMap_(data[0], CONSULT_HEADERS);
  const clientId = String((params && params.고객ID) || '').trim();
  const caseId = String((params && params.사건ID) || '').trim();
  const q = String((params && params.search) || '').trim();
  // [2026.09.19 신규] 중복으로 자동 정리된 기록은 대시보드·고객관리·처리개요 등 이 함수를
  // 그대로 쓰는 다른 화면에서는 항상 안 보이는 게 맞다(집계에 안 잡혀야 함) — 수금관리
  // 화면만 "흐리게 표시"를 위해 명시적으로 includeMerged:true를 넘겨 같이 받아간다.
  const includeMerged = !!(params && params.includeMerged);
  const logs = [];
  for (let i = 1; i < data.length; i++) {
    if (!data[i][col.id]) continue;
    if (!includeMerged && String(data[i][col.중복정리] || '').trim()) continue;
    if (clientId && String(data[i][col.고객ID] || '').trim() !== clientId) continue;
    if (caseId && String(data[i][col.사건ID] || '').trim() !== caseId) continue;
    if (q && String(data[i][col.고객명] || '').indexOf(q) === -1) continue;
    logs.push(client_readLog_(col, data[i]));
  }
  logs.sort(function (a, b) { return String(b.날짜 || '').localeCompare(String(a.날짜 || '')); });
  return { success: true, logs: logs };
}

function client_addConsultLog(params) {
  const 고객명 = String(params.고객명 || '').trim();
  let 고객ID = String(params.고객ID || '').trim();
  if (!고객ID && !고객명) return { success: false, message: '고객명(또는 고객ID)이 필요합니다.' };
  if (!고객ID) 고객ID = client_findOrCreateByName_(고객명).id;

  return withLock_(8000, function () {
    const sheets = client_getSheets_();
    const col = client_colMap_(sheets.log.getDataRange().getValues()[0], CONSULT_HEADERS);
    const id = Utilities.getUuid();
    const now = new Date();
    const newRow = [];
    newRow[col.id] = id;
    newRow[col.고객ID] = 고객ID;
    newRow[col.고객명] = 고객명;
    newRow[col.날짜] = String(params.날짜 || '').trim() || Utilities.formatDate(now, Session.getScriptTimeZone(), 'yyyy-MM-dd');
    newRow[col.담당자] = String(params.담당자 || '').trim();
    newRow[col.유형] = String(params.유형 || '').trim();
    newRow[col.내용] = String(params.내용 || '').trim();
    newRow[col.관계] = String(params.관계 || '').trim();
    newRow[col.금액] = params.금액 !== undefined && params.금액 !== '' ? Number(params.금액) || 0 : '';
    newRow[col.수취증빙] = String(params.수취증빙 || '').trim();
    newRow[col.리뷰] = String(params.리뷰 || '').trim();
    newRow[col.생성일] = now;
    newRow[col.승인번호] = String(params.승인번호 || '').trim();
    newRow[col.사건ID] = String(params.사건ID || '').trim();
    sheets.log.appendRow(newRow);
    SpreadsheetApp.flush();
    // 새로 추가된 기록이 이미 같은 고객·같은 날짜·같은 금액의 현금영수증 기록과 겹치면
    // (사건폴더 파일스캔이 홈택스 가져오기와 같은 거래를 뒤늦게 또 기록하는 경우 등) 즉시
    // 걸러낸다 — [[client_dedupCashReceiptLogs_]] 참고.
    const dedupRemoved = 고객ID ? client_dedupCashReceiptLogs_(sheets.log, col, 고객ID) : 0;
    return { success: true, log: client_readLog_(col, newRow), dedupRemoved: dedupRemoved };
  });
}

// ============================================================
// [2026.09 신규] 현금영수증 자동 인식 — 사건 폴더 안에 파일명에 "현금영수증"이 들어간
// 파일이 있으면, AI가 그 안의 금액을 읽어서 자문내역(수금내역)에 자동으로 기록한다.
// 대시보드의 "최근 수금내역"/고객관리 카드는 자문내역을 그대로 읽어 보여주므로, 이렇게
// 자동 기록만 해두면 화면 쪽은 손댈 필요가 없다(기존 loadDashPayments/고객관리 화면 재사용).
// 이미 처리한 파일은 Drive appProperties에 표시를 남겨 다시 스캔해도 중복 기록/중복 AI
// 호출이 안 되게 한다.
// ============================================================

// 파일ID에서 부모 폴더를 최대 6단계까지 거슬러 올라가며, 사건관리 시트의 "폴더ID" 열과
// 일치하는 폴더를 찾는다 — 그 사건의 고객명을 알아내기 위함.
// [2026.09.18 신규, 2026.09.23 수정] 상담 사건은 개별 Drive 폴더가 없으므로("상담을 자문과
// 상담으로 세분"), 그 상담과 관련된 현금영수증은 사건 폴더 대신 공용 폴더 하나에
// "<고객명>_현금영수증"으로 모아둔다. [2026.09.23] 세무사님이 두 번 재지적 — 처음엔 "0_NX_0"
// (홈택스 매출내역 엑셀 임시보관함, RECEIPT_IMPORT_FOLDER_NAME_)과 아예 같은 폴더로 합쳤다가
// "파일만 섞이면 구분이 안 된다"는 지적으로 "0_NX_0/상담사건/"(그 안의 하위폴더)으로 옮겼는데,
// 다시 "0_NX_0과 상담사건은 서로 무관한 별개 용도인데 굳이 하나를 다른 하나 안에 넣을 필요
// 없다"는 지적으로 최종 확정 — "고객사건" 바로 밑에 0_NX_0과 나란한 형제 폴더로 두되,
// 이름 앞에 "1 "을 붙여(0_NX_0의 "0_"과 같은 원리) 진짜 사건 폴더들(고객명으로 시작)보다
// 위쪽에 정렬되게 한다.
const WORK_CONSULT_SHARED_FOLDER_NAME_ = '1 상담사건';
// [2026.10.09] 고객사건 폴더 바로 밑의 특수폴더(사건이 아님) — 사건 흡수·미연결/미등록 폴더 점검이 사건으로 잘못 잡지 않게 한곳에서 관리.
// 예전엔 0_NX_0만 이름으로 빼고 있어 '1 상담사건'이 정비 버튼에 사건으로 잡힐 수 있었다. 새 특수폴더를 고객사건 밑에 만들면 여기에 추가할 것.
// (후속확인 과제 목록은 고객사건이 아니라 상위 '0 NETAX/_확인조치사항.md'에 둔다 — 세무사님 지정 2026-10-10)
const WORK_SPECIAL_ROOT_FOLDERS_ = ['0_NX_0', '1 상담사건'];
function work_isSpecialRootFolder_(name) { return WORK_SPECIAL_ROOT_FOLDERS_.indexOf(String(name || '').trim()) !== -1; }
function getConsultSharedFolder_() {
  const root = getDefaultFolder();
  if (!root) return null;
  return getOrCreateSubfolder_(root, WORK_CONSULT_SHARED_FOLDER_NAME_);
}
// "<고객명>_현금영수증.ext" 파일명에서 고객명을 뽑아, 그 이름과 정확히 같은 고객명을 가진
// 상담(업무유형) 사건 중 가장 최근(의뢰일, 없으면 생성일) 것 하나를 찾는다 — 같은 고객이
// 상담 사건을 여러 번 가진 경우 어느 것인지 사람이 매번 고르게 하기보다(세무사님 확인),
// 자동으로 최근 것 하나에 붙인다. 못 찾으면 null.
function findConsultCaseByFileName_(fileName, data, col) {
  const m = String(fileName || '').match(/^(.+?)_현금영수증/);
  if (!m) return null;
  const name = m[1].trim();
  let best = null;
  for (let i = 1; i < data.length; i++) {
    if (String(data[i][col.고객명] || '').trim() !== name) continue;
    if (data[i][col.업무유형] !== '상담') continue;
    const sortKey = String(data[i][col.의뢰일] || '') || work_dateStr_(data[i][col.생성일]);
    if (!best || sortKey > best.sortKey) {
      best = { 고객명: data[i][col.고객명], 고객ID: data[i][col.고객ID], caseId: data[i][col.id], sortKey: sortKey };
    }
  }
  return best;
}
function findCaseForFile_(fileId) {
  const sheet = work_getSheet_();
  const data = sheet.getDataRange().getValues();
  const col = work_colMap_(data[0]);
  const caseByFolderId = {};
  for (let i = 1; i < data.length; i++) {
    const fid = data[i][col.폴더ID];
    if (fid) caseByFolderId[fid] = { 고객명: data[i][col.고객명], 고객ID: data[i][col.고객ID], caseId: data[i][col.id] };
  }
  let consultFolderId = '';
  try { const cf = getConsultSharedFolder_(); if (cf) consultFolderId = cf.getId(); } catch (err) { /* 조회 실패해도 폴더 기준 매칭은 계속 시도 */ }
  try {
    const file = DriveApp.getFileById(fileId);
    let parents = file.getParents();
    let depth = 0;
    while (depth < 6) {
      if (!parents.hasNext()) return null;
      const parent = parents.next();
      const pid = parent.getId();
      if (caseByFolderId[pid]) return caseByFolderId[pid];
      if (consultFolderId && pid === consultFolderId) return findConsultCaseByFileName_(file.getName(), data, col);
      parents = parent.getParents();
      depth++;
    }
  } catch (err) { /* 폴더 조회 실패 시 그냥 못 찾은 것으로 처리 */ }
  return null;
}


// 실제 스캔 본체 — 대시보드의 "지금 확인" 버튼(handleScanCashReceipts)과 야간 자동작업
// (runNightlyChiefManager) 양쪽에서 그대로 호출한다.
// [2026.10.09] AI(Sonnet) 대신 구글 드라이브 무료 OCR + 규칙 판독(parseReceiptText_)으로 바꿨다 — 비용 0원.
// 실제 영수증 64장 시험: 56장 검산 일치로 확정, Sonnet이 읽었던 18장과 전부 같음(Haiku가 틀린 32,354,500원도 맞춤),
// 확정 못한 5장은 금액을 비우고 "금액 확인 필요"로 기록(틀린 숫자를 넣지 않음). 세무사님 원칙: 시스템 루틴은 토큰 0.
function runCashReceiptScan_() {
  const result = { scanned: 0, added: 0, skipped: 0, needCheck: 0, errors: [] };

  let files;
  try {
    const res = Drive.Files.list({
      q: "name contains '현금영수증' and trashed = false",
      fields: 'files(id,name,mimeType,modifiedTime,appProperties)',
      pageSize: 200
    });
    files = res.files || [];
  } catch (err) {
    result.errors.push('드라이브 검색 실패: ' + err.message);
    return result;
  }
  result.scanned = files.length;

  // [2026.09 버그수정] 같은 영수증이 jpg/pdf 등 여러 형식으로 같이 저장된 경우(예:
  // "현금영수증_고객BC.jpg"와 "현금영수증_고객BC.pdf") 예전엔 파일마다 각각 수금내역을
  // 만들어 같은 거래가 두 번 기록됐다 — 같은 사건 안에서 확장자를 뺀 파일명이 같으면
  // 하나의 거래로 보고 한 번만 기록한다.
  const groups = {};
  files.forEach(function (f) {
    if (f.appProperties && f.appProperties.netax_receipt_logged === 'true') { result.skipped++; return; }
    const caseInfo = findCaseForFile_(f.id);
    if (!caseInfo) { result.skipped++; return; } // 사건 폴더 밖의 파일이면 건너뜀
    const baseName = f.name.replace(/\.[^.]+$/, '');
    const key = caseInfo.caseId + '::' + baseName;
    if (!groups[key]) groups[key] = [];
    groups[key].push({ file: f, caseInfo: caseInfo });
  });

  Object.keys(groups).forEach(function (key) {
    const group = groups[key];
    const primary = group[0];
    let succeeded = false;
    try {
      // 드라이브 복사(OCR) 호출이 짧은 시간에 몰리면 "User rate limit exceeded"가 난다 — 파일 사이 간격을 둔다.
      Utilities.sleep(1500);
      const extracted = extractReceiptAmountViaOCR_(primary.file.id);
      if (!extracted.confident) result.needCheck++;
      // [2026.09.17 버그수정] "현금영수증이 고객에만 연결되다니 말이 안 된다 — 사건에 먼저
      // 연결되고 나서 고객에 연결되어야 한다" — findCaseForFile_가 파일의 부모 폴더를 거슬러
      // 올라가 정확히 어느 사건 폴더 안에 있는지 이미 알아내고 있었는데(caseInfo.caseId), 이
      // 호출부가 그 값을 안 쓰고 고객명만 넘겨서 결국 이름 기반으로만 고객과 연결되고
      // 있었다 — 이미 알고 있는 사건ID·고객ID를 그대로 넘긴다.
      client_addConsultLog({
        고객ID: primary.caseInfo.고객ID,
        고객명: primary.caseInfo.고객명,
        사건ID: primary.caseInfo.caseId,
        날짜: extracted.date || Utilities.formatDate(new Date(primary.file.modifiedTime), 'Asia/Seoul', 'yyyy-MM-dd'),
        유형: '수금',
        내용: '현금영수증 파일 자동 인식(' + primary.file.name + ')' + (extracted.confident ? '' : ' ⚠ 금액 확인 필요(자동 판독 못함)'),
        금액: extracted.confident ? extracted.amount : '',
        수취증빙: '현금영수증'
      });
      result.added++;
      succeeded = true;
    } catch (err) {
      result.errors.push(primary.file.name + ': ' + err.message);
    }
    if (succeeded) {
      group.forEach(function (item) {
        try { Drive.Files.update({ appProperties: { netax_receipt_logged: 'true' } }, item.file.id); } catch (err) { /* 표시 실패해도 치명적이지 않음 */ }
      });
    }
  });

  return result;
}

// [2026.09 신규] 대시보드의 "지금 확인" 버튼에서 호출 — 스캔을 즉시 실행하고 결과를 그대로
// 돌려줘서(몇 건 새로 인식했는지) 화면에 토스트로 보여줄 수 있게 한다.
function handleScanCashReceipts(body) {
  return runCashReceiptScan_();
}

// ============================================================
// [2026.09.15 신규] 홈택스 "현금영수증 발행내역(매출내역)" 엑셀 가져오기 — 위 스캔(개별
// 사건폴더에 저장된 현금영수증 사진/PDF를 AI로 읽는 방식)과는 완전히 다른 원천이다. 세무사님이
// 홈택스에서 분기별로 직접 다운로드해 "고객사건/0_NX_0"(사건별로 안 나뉜 공용 임시보관함)에
// 넣어두는 매출내역 엑셀(.xls, 옛 바이너리 형식) 5개가 "지금까지의 전체 현금영수증 발행내역"
// 원장이므로, 그 파일들을 통째로 읽어 수금관리(자문내역) 데이터로 흡수한다. 앞으로도 계속
// 다운로드해서 검증할 것이라고 하셨으므로 재실행해도 안전해야 한다 — 승인번호(홈택스가 매기는
// 전역 고유값)를 기준으로 이미 들여온 건은 건너뛰고, 새 분기 파일이나 갱신된 파일에서 처음
// 보이는 건만 새로 추가한다(파일 단위가 아니라 승인번호 단위 dedup — 진행 중인 분기 파일은
// 다운받을 때마다 행이 계속 늘어나기 때문).
//
// 자동 연결: 파일에 있는 정보는 "신분확인뒷4자리"(발급에 쓴 전화번호 등의 뒤 4자리)뿐이라,
// 고객관리의 전화번호 뒤 4자리와 정확히 1명만 일치하면 그 고객으로 자동 연결하고, 0명이거나
// 2명 이상 겹치면(오match 위험) 고객명을 비워두고 유형에 "(미연결)"을 남겨 수금관리 화면에서
// 사람이 직접 골라 연결하게 한다(추측으로 잘못 연결하지 않는다).
// ============================================================
const RECEIPT_IMPORT_FOLDER_NAME_ = '0_NX_0';
const RECEIPT_IMPORT_FILE_PREFIX_ = '매출내역';

function receipt_findHometaxExportFiles_() {
  const root = getDefaultFolder();
  const subFolders = root.getFoldersByName(RECEIPT_IMPORT_FOLDER_NAME_);
  if (!subFolders.hasNext()) return [];
  const folder = subFolders.next();
  const files = [];
  const it = folder.getFiles();
  while (it.hasNext()) {
    const f = it.next();
    if (f.getName().indexOf(RECEIPT_IMPORT_FILE_PREFIX_) === 0) files.push(f);
  }
  return files;
}

// 옛 바이너리 .xls(신규 .xlsx도 같은 mimeType 매핑으로 처리됨)를 구글 시트로 임시 변환해서
// 읽는다 — convertAndExtractOfficeFile과 같은 검증된 방식(Drive.Files.copy로 mimeType만
// 스프레드시트로 바꿔 복사하면 드라이브가 알아서 내용을 변환해준다).
function receipt_readExcelRows_(file) {
  const targetMime = OFFICE_MIME_TO_GOOGLE[file.getMimeType()] || 'application/vnd.google-apps.spreadsheet';
  let tempFileId = null;
  try {
    const copied = Drive.Files.copy(tcTmpMeta_({ mimeType: targetMime, name: 'nx_temp_receipt_' + Date.now() }), file.getId());
    tempFileId = copied.id;
    const ss = SpreadsheetApp.openById(tempFileId);
    return ss.getSheets()[0].getDataRange().getValues();
  } finally {
    if (tempFileId) { try { DriveApp.getFileById(tempFileId).setTrashed(true); } catch (e) { } }
  }
}

// 요약행("총 사용금액 : ...")이 몇 번째 줄에 있든 상관없이 "승인번호" 헤더가 있는 실제 헤더행을
// 찾아서 그 아래부터 데이터로 읽는다 — 홈택스가 조회 조건에 따라 앞줄 구성을 바꿀 수 있어서다.
function receipt_parseHometaxRows_(rows) {
  let headerIdx = -1;
  for (let i = 0; i < rows.length; i++) {
    if (rows[i].indexOf('승인번호') !== -1) { headerIdx = i; break; }
  }
  if (headerIdx === -1) return { records: [], error: '헤더행("승인번호")을 찾지 못했습니다.' };
  const headers = rows[headerIdx];
  const idx = {};
  headers.forEach(function (h, i) { idx[String(h).trim()] = i; });
  const required = ['매출일시', '총금액', '승인번호', '신분확인뒷4자리', '거래구분'];
  const missing = required.filter(function (h) { return idx[h] === undefined; });
  if (missing.length) return { records: [], error: '필요한 열이 없습니다: ' + missing.join(', ') };
  const records = [];
  for (let i = headerIdx + 1; i < rows.length; i++) {
    const r = rows[i];
    const 승인번호 = String(r[idx['승인번호']] || '').trim();
    if (!승인번호) continue; // 빈 행(합계행 등) 건너뜀
    const rawDate = r[idx['매출일시']];
    const dateStr = rawDate instanceof Date
      ? Utilities.formatDate(rawDate, 'Asia/Seoul', 'yyyy-MM-dd')
      : String(rawDate || '').slice(0, 10);
    records.push({
      승인번호: 승인번호,
      날짜: dateStr,
      금액: Number(r[idx['총금액']]) || 0,
      신분확인뒷4자리: String(r[idx['신분확인뒷4자리']] || '').trim(),
      거래구분: String(r[idx['거래구분']] || '').trim(),
      용도구분: idx['용도구분'] !== undefined ? String(r[idx['용도구분']] || '').trim() : '',
      isCancelled: /취소/.test(String(r[idx['거래구분']] || ''))
    });
  }
  return { records: records, error: null };
}

// [2026.09.15 개선, 2026.09.16 수정] 세무사님 설명 — "신분확인뒷4자리와 고객 전화번호 뒷4자리가
// 원칙상 같아야 하지만, 복수의뢰인(공동상속인·부부 등) 사건에서 대표 의뢰인이 아닌 사람 명의로
// 현금영수증이 발행되는 경우가 있다." 그래서 고객관리의 "추가연락처"(이름+전화번호 목록, JSON —
// 전화번호만 있으면 누구 건지 알 수 없다는 지적에 따라 이름을 같이 받게 바뀌었다)도 대표
// 전화번호와 동등하게 매칭 대상에 포함한다 — 대표번호든 추가연락처든 어느 번호로 일치하든 그
// 고객으로 본다(단, 그렇게 해서도 일치하는 고객이 2명 이상이면 오match 위험이 있으니 여전히
// 미연결로 남겨 사람이 확인하게 한다).
function receipt_matchClientByPhoneLast4_(last4, clientRows, ccol) {
  if (!last4 || last4.length !== 4) return null;
  const matches = clientRows.filter(function (row) {
    const extraNumbers = client_parseExtraContacts_(row[ccol.추가연락처]).map(function (c) { return c.전화번호; });
    const numbers = client_splitPhoneNumbers_(row[ccol.전화번호]).concat(client_splitPhoneNumbers_(extraNumbers.join(',')));
    return numbers.some(function (digits) { return digits.slice(-4) === last4; });
  });
  return matches.length === 1 ? matches[0] : null;
}

// 대시보드(수동 "지금 확인")와 야간 자동작업(runNightlyChiefManager) 양쪽에서 호출하는 본체.
function receipt_importHometaxExports_() {
  const result = { filesScanned: 0, rowsSeen: 0, imported: 0, autoLinked: 0, unlinked: 0, cancelledRemoved: 0, alreadyImported: 0, errors: [] };
  let files;
  try {
    files = receipt_findHometaxExportFiles_();
  } catch (err) {
    result.errors.push('"' + RECEIPT_IMPORT_FOLDER_NAME_ + '" 폴더 조회 실패: ' + err.message);
    return result;
  }
  result.filesScanned = files.length;
  if (!files.length) return result;

  return withLock_(30000, function () {
    const clientSheets = client_getSheets_();
    const clientData = clientSheets.clients.getDataRange().getValues();
    const ccol = client_colMap_(clientData[0], CLIENT_HEADERS);
    const clientRows = clientData.slice(1);

    const logSheet = clientSheets.log;
    const logData = logSheet.getDataRange().getValues();
    const lcol = client_colMap_(logData[0], CONSULT_HEADERS);
    const existingByApproval = {}; // 승인번호 → 시트상 행번호(1-based)
    for (let i = 1; i < logData.length; i++) {
      const 승인번호 = String(logData[i][lcol.승인번호] || '').trim();
      if (승인번호) existingByApproval[승인번호] = i + 1;
    }

    const cancelledApprovals = {};
    const newRecords = [];
    files.forEach(function (file) {
      let rows;
      try { rows = receipt_readExcelRows_(file); } catch (err) {
        result.errors.push(file.getName() + ' 변환/읽기 실패: ' + err.message);
        return;
      }
      const parsed = receipt_parseHometaxRows_(rows);
      if (parsed.error) { result.errors.push(file.getName() + ': ' + parsed.error); return; }
      result.rowsSeen += parsed.records.length;
      parsed.records.forEach(function (rec) {
        if (rec.isCancelled) { cancelledApprovals[rec.승인번호] = true; return; }
        if (existingByApproval[rec.승인번호]) { result.alreadyImported++; return; }
        newRecords.push(rec);
      });
    });

    // 취소된 승인번호가 이미 예전에 정상 건으로 들어와 있었으면 그 행을 지운다(뒤에서부터
    // 지워야 앞 행 번호가 안 밀린다).
    const rowsToDelete = Object.keys(cancelledApprovals)
      .map(function (a) { return existingByApproval[a]; })
      .filter(function (r) { return !!r; })
      .sort(function (a, b) { return b - a; });
    rowsToDelete.forEach(function (rowNum) { logSheet.deleteRow(rowNum); result.cancelledRemoved++; });

    // [2026.09.16 버그수정, 2026.09.19 재수정] 예전엔 여기서 승인번호 없는 기존 행을 찾아
    // 새 행을 만드는 대신 그 행에 승인번호만 조용히 채워 넣었다("백필") — 같은 거래가 두 번
    // 쌓이는 걸 막으려는 의도였지만, 그 결과 "다운자료"라는 독립된 행 자체가 아예 생기지
    // 않고 기존 발행자료 행에 흡수돼버려, 나중에 사건에 연결해도 흐리게 처리할 대상(다운자료
    // 자신의 행)이 애초에 존재하지 않는 문제가 생겼다("다운자료를 독립적으로 사건에 연결하고
    // 흐리게 처리하라"는 요구와 정면으로 충돌). 이제는 항상 새 독립된 다운자료 행을 만들고,
    // 같은 거래인지 판단은 아래 client_dedupCashReceiptLogs_(날짜·금액 정확히 일치)에게
    // 전적으로 맡긴다 — 중복이면 소프트 삭제(흐리게+되돌리기)로 처리되므로 데이터가 두 번
    // 쌓이는 것 자체는 문제가 아니다.
    const now = new Date();
    const rowsToAppend = [];
    newRecords
      .filter(function (rec) { return !cancelledApprovals[rec.승인번호]; }) // 같은 파일 안에서 승인 후 바로 취소된 건 제외
      .forEach(function (rec) {
        const client = receipt_matchClientByPhoneLast4_(rec.신분확인뒷4자리, clientRows, ccol);
        if (client) result.autoLinked++; else result.unlinked++;
        const newRow = new Array(CONSULT_HEADERS.length).fill('');
        newRow[lcol.id] = Utilities.getUuid();
        newRow[lcol.고객ID] = client ? client[ccol.id] : '';
        newRow[lcol.고객명] = client ? client[ccol.성명] : '';
        newRow[lcol.날짜] = rec.날짜;
        newRow[lcol.유형] = client ? '수금' : '수금(미연결)';
        newRow[lcol.내용] = '홈택스 현금영수증 자동수입 · 신분확인 ' + rec.신분확인뒷4자리 + (rec.용도구분 ? ' · ' + rec.용도구분 : '');
        newRow[lcol.금액] = rec.금액;
        newRow[lcol.수취증빙] = '현금영수증';
        newRow[lcol.생성일] = now;
        newRow[lcol.승인번호] = rec.승인번호;
        rowsToAppend.push(newRow);
      });
    if (rowsToAppend.length) {
      logSheet.getRange(logSheet.getLastRow() + 1, 1, rowsToAppend.length, CONSULT_HEADERS.length).setValues(rowsToAppend);
    }
    SpreadsheetApp.flush();
    result.imported = rowsToAppend.length;

    // [2026.09.15 신규] 예전에 미연결로 남았던 건도 이번에 다시 시도한다 — 세무사님이 고객관리에
    // "추가연락처"(가족·공동의뢰인 번호)를 새로 등록해두면, 다음 가져오기 버튼 클릭만으로 그
    // 미연결 건들이 자동으로 연결되게 하기 위함(신분확인뒷4자리는 저장 당시 내용란에 남겨뒀다).
    result.reMatched = 0;
    const freshLogData = logSheet.getDataRange().getValues();
    for (let i = 1; i < freshLogData.length; i++) {
      if (freshLogData[i][lcol.고객ID]) continue; // 이미 연결됨
      const m = String(freshLogData[i][lcol.내용] || '').match(/신분확인\s*(\d{4})/);
      if (!m) continue; // 홈택스 수입 건이 아니거나 형식이 다름
      const client = receipt_matchClientByPhoneLast4_(m[1], clientRows, ccol);
      if (!client) continue;
      logSheet.getRange(i + 1, lcol.고객ID + 1).setValue(client[ccol.id]);
      logSheet.getRange(i + 1, lcol.고객명 + 1).setValue(client[ccol.성명]);
      logSheet.getRange(i + 1, lcol.유형 + 1).setValue('수금');
      result.reMatched++;
    }
    if (result.reMatched) SpreadsheetApp.flush();

    // [2026.09.19 신규] 이번 가져오기로 새로 고객ID가 채워진 건(신규 반영·재매칭)이 이미
    // 있던 다른 경로(사건폴더 파일스캔·수동입력) 기록과 같은 거래로 겹칠 수 있다 — 전체
    // 고객을 대상으로 한 번에 정리한다. [[client_dedupCashReceiptLogs_]] 참고.
    result.dedupRemoved = client_dedupCashReceiptLogs_(logSheet, lcol);

    const reportText = '스캔한 파일: ' + result.filesScanned + '건\n' + files.map(function (f) { return '- ' + f.getName(); }).join('\n') + '\n\n' +
      '전체 데이터행: ' + result.rowsSeen + '건\n' +
      '신규 반영: ' + result.imported + '건(자동연결 ' + result.autoLinked + '건 / 미연결 ' + result.unlinked + '건)\n' +
      '이미 반영되어 건너뜀: ' + result.alreadyImported + '건\n' +
      '취소 확인되어 삭제: ' + result.cancelledRemoved + '건\n' +
      '기존 미연결 중 새로 연결됨: ' + result.reMatched + '건\n' +
      '다른 경로 기록과 겹쳐 자동 정리됨: ' + result.dedupRemoved + '건\n' +
      (result.errors.length ? '\n오류:\n' + result.errors.join('\n') : '');
    try {
      const chiefFolder = getChiefManagerFolder_();
      if (chiefFolder) {
        const auditFolder = getOrCreateSubfolder_(chiefFolder, '_사건폴더감사');
        writeFileOverwrite_(auditFolder, '홈택스수금가져오기_' + Utilities.formatDate(now, 'Asia/Seoul', 'yyyy-MM-dd_HHmm') + '.md', reportText, MimeType.PLAIN_TEXT);
      }
    } catch (err) { /* 리포트 저장 실패해도 반환값으로 확인 가능 */ }

    return result;
  });
}

// [2026.09.16 임시, 1회성] 오늘 홈택스 가져오기 이전에 이미 수동으로(또는 예전 파일스캔으로)
// 기록된 현금영수증과, 오늘 새로 들어온 홈택스 행이 중복된 것들을 정리한다(위
// receipt_importHometaxExports_의 백필 로직이 앞으로는 막아주지만, 오늘 이미 만들어진
// 중복은 남아있으므로 한 번은 직접 청소해야 한다). 같은 (고객명·날짜·금액) 조합에 승인번호
// 있는 행과 없는 행이 섞여 있으면 승인번호 없는 쪽을 지운다(승인번호 있는 쪽이 더 정확한
// 출처 정보를 갖고 있으므로).
function cleanupHometaxDuplicates_() {
  return withLock_(30000, function () {
    const sheets = client_getSheets_();
    const logSheet = sheets.log;
    const data = logSheet.getDataRange().getValues();
    const col = client_colMap_(data[0], CONSULT_HEADERS);
    const groups = {};
    for (let i = 1; i < data.length; i++) {
      if (!data[i][col.id]) continue;
      if (String(data[i][col.수취증빙] || '') !== '현금영수증') continue;
      const key = [String(data[i][col.고객명] || '').trim(), client_dateStr_(data[i][col.날짜]), String(data[i][col.금액] || '')].join('::');
      (groups[key] = groups[key] || []).push(i);
    }
    const rowsToDelete = [];
    const log = [];
    Object.keys(groups).forEach(function (key) {
      const idxs = groups[key];
      if (idxs.length < 2) return;
      const withApproval = idxs.filter(function (i) { return String(data[i][col.승인번호] || '').trim(); });
      const withoutApproval = idxs.filter(function (i) { return !String(data[i][col.승인번호] || '').trim(); });
      if (!withApproval.length || !withoutApproval.length) return; // 섞여있을 때만 처리(둘 다 승인번호 있으면 진짜 별개 거래일 수 있어 손대지 않음)
      withoutApproval.forEach(function (i) {
        rowsToDelete.push(i);
        log.push(key + ' — 승인번호 없는 중복행 삭제(원본은 승인번호 ' + String(data[withApproval[0]][col.승인번호]) + ')');
      });
    });
    rowsToDelete.sort(function (a, b) { return b - a; }).forEach(function (i) { logSheet.deleteRow(i + 1); });
    const reportText = '삭제된 중복행: ' + rowsToDelete.length + '건\n' + log.join('\n');
    let fileUrl = '';
    try {
      const chiefFolder = getChiefManagerFolder_();
      if (chiefFolder) {
        const auditFolder = getOrCreateSubfolder_(chiefFolder, '_사건폴더감사');
        const file = writeFileOverwrite_(auditFolder, '홈택스중복정리_' + Utilities.formatDate(new Date(), 'Asia/Seoul', 'yyyy-MM-dd_HHmm') + '.md', reportText, MimeType.PLAIN_TEXT);
        fileUrl = file.getUrl();
      }
    } catch (err) { /* 무시 */ }
    return { deleted: rowsToDelete.length, log: log, fileUrl: fileUrl };
  });
}

// [2026.09.16 임시, 읽기전용] 세무사님 지시 — "중복이 있는지 모두 점검을 다시 해봐." 홈택스
// 가져오기-수동입력 간 중복(수취증빙=현금영수증, 승인번호 유무로 구분)만 고쳤으니, 이번엔
// 원인을 가리지 않고 전체 수금 내역(자문내역) 전체를 대상으로 넓게 다시 훑는다 — 아무것도
// 지우지 않고 의심되는 건만 목록으로 남긴다(같은 날짜·금액이 우연히 겹치는 정상 케이스도
// 있을 수 있어 자동삭제는 위험하다고 판단, 사람이 보고 결정).
function auditAllConsultLogDuplicates_() {
  const sheets = client_getSheets_();
  const data = sheets.log.getDataRange().getValues();
  const col = client_colMap_(data[0], CONSULT_HEADERS);
  const rows = [];
  for (let i = 1; i < data.length; i++) {
    if (!data[i][col.id]) continue;
    rows.push({
      idx: i, id: data[i][col.id], 고객명: String(data[i][col.고객명] || '').trim(),
      날짜: client_dateStr_(data[i][col.날짜]), 금액: String(data[i][col.금액] || ''),
      수취증빙: String(data[i][col.수취증빙] || ''), 유형: String(data[i][col.유형] || ''),
      내용: String(data[i][col.내용] || ''), 승인번호: String(data[i][col.승인번호] || ''),
      생성일: data[i][col.생성일]
    });
  }
  // ① 완전일치 중복(고객명·날짜·금액·수취증빙·내용까지 전부 같음) — 가장 확실한 진짜 중복.
  const exactGroups = {};
  rows.forEach(function (r) { const k = [r.고객명, r.날짜, r.금액, r.수취증빙, r.내용].join('::'); (exactGroups[k] = exactGroups[k] || []).push(r); });
  const exactDupes = Object.keys(exactGroups).filter(function (k) { return exactGroups[k].length > 1; }).map(function (k) { return exactGroups[k]; });
  // ② 고객명·날짜·금액만 같음(수취증빙/내용은 다를 수 있음) — 진짜 중복일 수도, 우연의 일치일
  // 수도 있어 사람이 봐야 한다.
  const looseGroups = {};
  rows.forEach(function (r) { const k = [r.고객명, r.날짜, r.금액].join('::'); (looseGroups[k] = looseGroups[k] || []).push(r); });
  const looseDupes = Object.keys(looseGroups).filter(function (k) { return looseGroups[k].length > 1; }).map(function (k) { return looseGroups[k]; });
  // ③ 승인번호가 2건 이상에 붙어있음(있으면 안 되는 상태 — 로직 버그 신호).
  const approvalGroups = {};
  rows.forEach(function (r) { if (r.승인번호) (approvalGroups[r.승인번호] = approvalGroups[r.승인번호] || []).push(r); });
  const approvalDupes = Object.keys(approvalGroups).filter(function (k) { return approvalGroups[k].length > 1; }).map(function (k) { return approvalGroups[k]; });

  const fmt = function (groups, label) {
    return label + '(' + groups.length + '건)\n' + groups.map(function (g) {
      return '- ' + g.map(function (r) { return r.고객명 + '/' + r.날짜 + '/' + r.금액 + '원/' + r.수취증빙 + '/유형:' + r.유형 + '/승인번호:' + (r.승인번호 || '없음') + '/내용:' + (r.내용 || '(없음)'); }).join('  |  ');
    }).join('\n');
  };
  const reportText = fmt(exactDupes, '① 완전일치 중복') + '\n\n' + fmt(looseDupes, '② 고객명·날짜·금액만 같음(수취증빙/내용 다를 수 있음)') + '\n\n' + fmt(approvalDupes, '③ 승인번호 중복(로직버그 신호, 있으면 안 됨)');
  let fileUrl = '';
  try {
    const chiefFolder = getChiefManagerFolder_();
    if (chiefFolder) {
      const auditFolder = getOrCreateSubfolder_(chiefFolder, '_사건폴더감사');
      const file = writeFileOverwrite_(auditFolder, '전체수금중복점검_' + Utilities.formatDate(new Date(), 'Asia/Seoul', 'yyyy-MM-dd_HHmm') + '.md', reportText, MimeType.PLAIN_TEXT);
      fileUrl = file.getUrl();
    }
  } catch (err) { /* 무시 */ }
  return { exactCount: exactDupes.length, looseCount: looseDupes.length, approvalDupeCount: approvalDupes.length, fileUrl: fileUrl };
}

function handleImportHometaxReceipts(body) {
  return receipt_importHometaxExports_();
}

// [2026.09.15 임시, 1회성] "수금내역은 고객과 사건 모두에 연결되어야 한다"는 지시에 따라
// 사건ID 필드를 새로 만들었는데, 그 전에 이미 쌓여있던 수금 내역은 전부 사건 연결이 비어있다.
// 고객은 이미 연결돼 있으므로(고객ID), 그 고객 이름으로 등록된 사건이 정확히 1건뿐이면
// 애매할 게 없으니 자동으로 그 사건에 연결한다. 사건이 2건 이상인 고객은 어느 수금이 어느
// 사건 건인지 알 방법이 없어(날짜만으로 추측하면 틀릴 위험이 크다) 추측하지 않고 명단만
// 보고해서 세무사님이 직접 고르시게 한다.
function linkPastPaymentsToCases_() {
  return withLock_(30000, function () {
    const clientSheets = client_getSheets_();
    const logSheet = clientSheets.log;
    const logData = logSheet.getDataRange().getValues();
    const lcol = client_colMap_(logData[0], CONSULT_HEADERS);

    const workSheet = work_getSheet_();
    const workData = workSheet.getDataRange().getValues();
    const wcol = work_colMap_(workData[0]);
    const casesByClientId = {};
    for (let i = 1; i < workData.length; i++) {
      const cid = String(workData[i][wcol.고객ID] || '').trim();
      if (!cid) continue;
      (casesByClientId[cid] = casesByClientId[cid] || []).push({ id: workData[i][wcol.id], 사건명: workData[i][wcol.사건명] });
    }

    let linked = 0, noCases = 0, alreadyLinked = 0, noClient = 0;
    const ambiguous = {}; // 고객명 → {count, 사건명목록}
    for (let i = 1; i < logData.length; i++) {
      if (!logData[i][lcol.id]) continue;
      if (String(logData[i][lcol.사건ID] || '').trim()) { alreadyLinked++; continue; }
      const clientId = String(logData[i][lcol.고객ID] || '').trim();
      if (!clientId) { noClient++; continue; } // 고객 자체가 미연결이면 사건도 알 수 없음
      const cases = casesByClientId[clientId] || [];
      if (!cases.length) { noCases++; continue; }
      if (cases.length === 1) {
        logSheet.getRange(i + 1, lcol.사건ID + 1).setValue(cases[0].id);
        linked++;
        continue;
      }
      const 고객명 = String(logData[i][lcol.고객명] || '');
      if (!ambiguous[고객명]) ambiguous[고객명] = { count: 0, 사건들: cases.map(function (c) { return c.사건명; }) };
      ambiguous[고객명].count++;
    }
    if (linked) SpreadsheetApp.flush();

    const ambiguousLines = Object.keys(ambiguous).map(function (name) {
      return name + ' — 수금 ' + ambiguous[name].count + '건, 후보 사건: ' + ambiguous[name].사건들.join(' / ');
    });
    const reportText = '자동 연결(사건 1건뿐인 고객): ' + linked + '건\n' +
      '이미 연결되어 건너뜀: ' + alreadyLinked + '건\n' +
      '고객 자체가 미연결이라 건너뜀: ' + noClient + '건\n' +
      '그 고객 명의의 사건이 없어 건너뜀: ' + noCases + '건\n' +
      '사건이 여러 건이라 사람이 골라야 함(' + ambiguousLines.length + '명):\n' + ambiguousLines.join('\n');
    let fileUrl = '';
    try {
      const chiefFolder = getChiefManagerFolder_();
      if (chiefFolder) {
        const auditFolder = getOrCreateSubfolder_(chiefFolder, '_사건폴더감사');
        const file = writeFileOverwrite_(auditFolder, '과거수금사건연결_' + Utilities.formatDate(new Date(), 'Asia/Seoul', 'yyyy-MM-dd_HHmm') + '.md', reportText, MimeType.PLAIN_TEXT);
        fileUrl = file.getUrl();
      }
    } catch (err) { /* 리포트 저장 실패해도 반환값으로 확인 가능 */ }
    return { linked: linked, alreadyLinked: alreadyLinked, noClient: noClient, noCases: noCases, ambiguousClients: Object.keys(ambiguous).length, ambiguousLines: ambiguousLines, fileUrl: fileUrl };
  });
}

// [2026.09.15 임시, 읽기전용] 세무사님이 지적한 5명(고객U·고객AL·고객AT·고객AM·고객T)의
// 중복/명명규칙 불일치 사건을 실제로 병합·재명명하기 전에, 각 사건의 실제 내용(작업일지·
// 증빙목록·폴더ID 등)을 먼저 확인해야 한다 — 어느 쪽이 "진짜" 데이터가 쌓인 사건인지 추측하지
// 않기 위함(병합은 한쪽을 지우는 되돌리기 어려운 작업).
function dumpDuplicateCaseCandidates_() {
  const names = ['고객U', '고객AL', '고객AT', '고객AM', '고객T'];
  const sheet = work_getSheet_();
  const data = sheet.getDataRange().getValues();
  const col = work_colMap_(data[0]);
  const matches = [];
  for (let i = 1; i < data.length; i++) {
    if (names.indexOf(String(data[i][col.고객명] || '').trim()) !== -1) {
      matches.push(work_readRow_(col, data[i]));
    }
  }
  let fileUrl = '';
  try {
    const chiefFolder = getChiefManagerFolder_();
    if (chiefFolder) {
      const auditFolder = getOrCreateSubfolder_(chiefFolder, '_사건폴더감사');
      const file = writeFileOverwrite_(auditFolder, '중복사건조사_' + Utilities.formatDate(new Date(), 'Asia/Seoul', 'yyyy-MM-dd_HHmm') + '.json', JSON.stringify(matches, null, 2), MimeType.PLAIN_TEXT);
      fileUrl = file.getUrl();
    }
  } catch (err) { /* 무시 — 반환값으로도 확인 가능 */ }
  return { count: matches.length, fileUrl: fileUrl, cases: matches };
}

// [2026.09.15 임시, 1회성] 세무사님이 직접 확인해준 5명(고객U·고객AL·고객AT·고객AM·고객T)
// 사건 정리 — dumpDuplicateCaseCandidates_로 실제 데이터를 확인한 결과, 고객U·고객AL·고객AT·
// 고객AM 4명은 "_상담"/"_신고" 업무유형이 붙고 폴더가 아예 없는 사건(caseA, 예전에 개별적으로
// 등록됐던 것)과, 나중에 미등록 폴더 흡수 때 폴더까지 갖춰져 새로 만들어진 사건(caseB, 이미
// 명명규칙에 맞음)이 같은 고객 밑에 중복으로 남아있던 것 — caseA는 작업일지·증빙목록이 전부
// 비어있어 잃을 데이터가 없으므로 caseB로 통합(caseA 삭제)한다. 고객T은 진짜로 서로 다른
// 사건 2건(과세자료/증여)이 맞고, 그중 과세자료 사건만 이름이 규칙(고객명(납세자)_세목_업무유형,
// 괄호가 고객명 바로 뒤)에 어긋나 있어(사건명 끝에 괄호) 이름만 바로잡는다. 이 사건들에 연결
// 못 하고 남아있던 수금 내역도 같이 이어준다.
function fixDuplicateCasesAndRelinkPayments_() {
  return withLock_(30000, function () {
    const log = [];
    const MERGES = [
      { name: '고객U', caseAId: '23895017-d746-498d-97a2-1e74bac9a385', caseBId: 'c44379cc-7cda-46e4-bc7c-afbffdce3ed8' },
      { name: '고객AL', caseAId: 'ae2c23e5-c287-4632-9a72-732344d2186d', caseBId: '3ab4ba9b-b47d-4f8a-aac1-fcc977400585' },
      { name: '고객AT', caseAId: 'b708600e-0208-483d-86f1-0fea81c64072', caseBId: '8464652a-014a-4085-9091-5332d96ee2c1' },
      { name: '고객AM', caseAId: 'faf47b97-16bb-4de9-96ca-813372b1bc8d', caseBId: '789fc2dc-fbd1-47db-a8b7-053a82e9432b' }
    ];

    const clientSheets = client_getSheets_();
    const logSheet = clientSheets.log;
    const lcol = client_colMap_(logSheet.getDataRange().getValues()[0], CONSULT_HEADERS);

    MERGES.forEach(function (m) {
      // 1) 이 사건(caseA/caseB 어느 쪽으로도 연결 안 됐던, 고객명만 일치해 보류됐던 수금)을
      // 전부 caseB로 연결한다.
      const logData = logSheet.getDataRange().getValues();
      let relinked = 0;
      for (let i = 1; i < logData.length; i++) {
        if (String(logData[i][lcol.고객명] || '').trim() !== m.name) continue;
        if (String(logData[i][lcol.사건ID] || '').trim()) continue; // 이미 연결된 건 건드리지 않음
        logSheet.getRange(i + 1, lcol.사건ID + 1).setValue(m.caseBId);
        relinked++;
      }
      // 2) 빈 사건(caseA) 삭제 — work_deleteCase를 그대로 부르면 그 함수 내부의 withLock_이
      // 지금 이미 잡고 있는 락을 도중에 풀어버리므로(같은 락 객체), 여기서는 그 함수의 핵심
      // 동작(행 삭제+캘린더 정리+예약 연결 해제)만 락 재진입 없이 직접 수행한다.
      const workSheet = work_getSheet_();
      const workCol = work_colMap_(workSheet.getDataRange().getValues()[0]);
      const found = work_findCaseRow_(workSheet, workCol, m.caseAId);
      let deleted = false;
      if (found) {
        workSheet.deleteRow(found.rowIndex);
        try { work_deleteCaseCalendarEvents_(m.caseAId); } catch (err) { log.push(m.name + ' 캘린더 정리 실패: ' + err.message); }
        try { booking_clearCaseLink_(m.caseAId); } catch (err) { /* 무시 */ }
        deleted = true;
      }
      log.push(m.name + ': 수금 ' + relinked + '건 → 사건 재연결, 중복 사건 삭제 ' + (deleted ? '성공' : '실패(못 찾음)'));
    });

    // 고객T — 병합이 아니라 이름만 규칙에 맞게 수정(괄호를 고객명 바로 뒤로) + 수금 1건 연결.
    const songId = '3956bbe4-2ac8-4a69-805d-9635758a0272';
    const songNewName = '고객T(고객U)_과세자료';
    const sheet = work_getSheet_();
    const data = sheet.getDataRange().getValues();
    const col = work_colMap_(data[0]);
    const songRow = work_findCaseRow_(sheet, col, songId);
    if (songRow) {
      const oldName = songRow.row[col.사건명];
      sheet.getRange(songRow.rowIndex, col.사건명 + 1).setValue(songNewName);
      const fid = String(songRow.row[col.폴더ID] || '').trim();
      let folderRenamed = false;
      if (fid) { try { DriveApp.getFolderById(fid).setName(songNewName); folderRenamed = true; } catch (err) { log.push('고객T 폴더명변경 실패: ' + err.message); } }
      log.push('고객T: 사건명 "' + oldName + '" → "' + songNewName + '"' + (folderRenamed ? ' (폴더명도 변경)' : ''));
    } else {
      log.push('고객T: 과세자료 사건(' + songId + ')을 찾지 못함');
    }
    const songLogData = logSheet.getDataRange().getValues();
    let songRelinked = 0;
    for (let i = 1; i < songLogData.length; i++) {
      if (String(songLogData[i][lcol.고객명] || '').trim() !== '고객T') continue;
      if (String(songLogData[i][lcol.사건ID] || '').trim()) continue;
      logSheet.getRange(i + 1, lcol.사건ID + 1).setValue(songId);
      songRelinked++;
    }
    log.push('고객T: 수금 ' + songRelinked + '건 → 과세자료 사건에 연결');

    SpreadsheetApp.flush();
    const reportText = log.join('\n');
    let fileUrl = '';
    try {
      const chiefFolder = getChiefManagerFolder_();
      if (chiefFolder) {
        const auditFolder = getOrCreateSubfolder_(chiefFolder, '_사건폴더감사');
        const file = writeFileOverwrite_(auditFolder, '중복사건정리_' + Utilities.formatDate(new Date(), 'Asia/Seoul', 'yyyy-MM-dd_HHmm') + '.md', reportText, MimeType.PLAIN_TEXT);
        fileUrl = file.getUrl();
      }
    } catch (err) { /* 무시 */ }
    return { log: log, fileUrl: fileUrl };
  });
}

// ============================================================
// [2026.09 신규] "보고서 모음" 화면 — 모아보기 / 템플릿다듬기 / 글감만들기
// ============================================================

// [2026.09.16 재설계] 실사용 지적 — "왜 일부 문서만 보이나, PDF는 왜 보이나, 사건폴더 내
// 모든 파일이 다 조회돼야 하는 거 아닌가." 원래는 딱 두 하위폴더 이름("내부보고서"/"보고서")
// 바로 안만 보고, 그 안에 있는 파일이면 확장자 상관없이 다 보여줬다 — 그래서 그 두 폴더 밖에
// 저장된 진짜 보고서는 안 보이고, 반대로 그 폴더 안에 실수로 들어간 PDF 등은 보였다. 이제는
// 위치가 아니라 "파일 형식"으로 판단한다 — 사건 폴더 전체(하위폴더 전부 재귀 탐색)에서
// 실제로 보고서 형식인 파일(.md/.html·구글문서, .ppt·구글슬라이드)만 골라낸다.
const RH_REPORT_EXT_RE_ = /\.(md|markdown|html?|pptx?)$/i;
const RH_REPORT_MIME_ALLOW_ = {
  'application/vnd.google-apps.presentation': true // 구글 슬라이드(확장자 없음) = PPT 취급
};
// [2026.09.17 신규] "의뢰내용류 파일은 보고서 모음에 띄우지 말라" — 사건 생성 시 의뢰서템플릿
// 폴더에서 그대로 복사돼 들어오는 "OOO_의뢰내용.md" 같은 파일은 실제 보고서가 아니라 상담
// 접수 당시 원문(사건의뢰서)이라, 확장자만으로는 걸러지던 기존 규칙에서 명시적으로 제외한다.
const RW_INTAKE_FILENAME_PATTERN_ = /의뢰내용/;
const RW_INTAKE_CANONICAL_NAME_ = '사건의뢰서';
// [2026.09.18 버그수정] 세무사님 지적 — "의뢰서정비를 했는데도 왜 파일명에 증여신고·상속신고
// 같은 이름이 계속 보이나?" 실제 원인: work_seedCaseTemplateIfAny_(새 사건 생성 시 의뢰서템플릿
// 자동복사)는 위의 "OOO_의뢰내용.md" 패턴이 아니라 템플릿 파일명을 그대로("증여신고.md" 등)
// 복사해 넣는다 — 이건 이 관리 앱 전용의 더 최근 메커니즘이라 위 정규식이 애초에 이 경우를
// 고려하지 못했다. "의뢰서템플릿" 폴더에 실제로 있는(또는 접두어 도입 전 있었던) 파일명과
// 정확히 같은 이름의 사건 폴더 파일은 전부 의뢰서 원문으로 간주해 같은 방식으로 제외한다.
let rh_intakeTemplateBaseNamesCache_ = null;
function rh_getIntakeTemplateBaseNames_() {
  if (rh_intakeTemplateBaseNamesCache_) return rh_intakeTemplateBaseNamesCache_;
  const names = {};
  try {
    const folder = getCaseTemplateFolder_();
    if (folder) {
      const iter = folder.getFiles();
      while (iter.hasNext()) {
        const raw = iter.next().getName();
        const base = raw.replace(/\.[a-zA-Z0-9]+$/, '');
        names[base] = true;
        // "의뢰서_증여신고" 템플릿이 있으면, 접두어 도입 전에 이미 사건 폴더에 복사돼 있던
        // 옛 이름("증여신고") 사본도 같은 것으로 인식해야 한다.
        if (base.indexOf(CASE_TEMPLATE_NAME_PREFIX_) === 0) names[base.slice(CASE_TEMPLATE_NAME_PREFIX_.length)] = true;
      }
    }
  } catch (err) {
    // 템플릿 폴더 조회가 실패해도 나머지 판정(의뢰내용 패턴 등)은 그대로 동작해야 한다.
  }
  rh_intakeTemplateBaseNamesCache_ = names;
  return names;
}
function rh_isIntakeLikeFile_(name) {
  const n = String(name || '');
  if (RW_INTAKE_FILENAME_PATTERN_.test(n)) return true;
  const base = n.replace(/\.[a-zA-Z0-9]+$/, '');
  if (base === RW_INTAKE_CANONICAL_NAME_) return true;
  return !!rh_getIntakeTemplateBaseNames_()[base];
}
function rh_isReportFile_(name, mimeType) {
  if (rh_isIntakeLikeFile_(name)) return false;
  if (RH_REPORT_MIME_ALLOW_[mimeType]) return true;
  return RH_REPORT_EXT_RE_.test(name);
}
// 사건 폴더 하나를 하위폴더까지 전부 재귀적으로 훑어 보고서 형식 파일만 모은다. 폴더 깊이가
// 무한정 깊어질 일은 없는 구조(사건 폴더 안엔 몇 단계 하위폴더뿐)라 별도 깊이제한은 안 둔다.
// [2026.09.16 버그수정] kind에 folder.getName()을 그대로 넣고 화면(reporthub.html)에서
// "kind === '보고서'"로 발행 여부를 판단했는데, 그 사이 실제 폴더명이 '보고서'→'보고서_외부'로
// 바뀌면서(MY_SUBFOLDER_REPORT) 문자열이 어긋나 발행된 보고서도 전부 "초안"으로 잘못 표시되고
// 있었다 — 지금 시점의 실제 상수와 직접 비교한 published를 별도로 내려준다.
function rh_collectReportFilesInFolder_(folder, out, caseId, 고객명, 사건명) {
  const fIter = folder.getFiles();
  const folderName = folder.getName();
  while (fIter.hasNext()) {
    const f = fIter.next();
    if (!rh_isReportFile_(f.getName(), f.getMimeType())) continue;
    out.push({
      id: f.getId(), name: f.getName(), mimeType: f.getMimeType(),
      modifiedDate: f.getLastUpdated().getTime(), caseId: caseId, 고객명: 고객명, 사건명: 사건명,
      kind: folderName, published: (folderName === MY_SUBFOLDER_REPORT)
    });
  }
  const subIter = folder.getFolders();
  while (subIter.hasNext()) {
    const sf = subIter.next();
    if (caseIsFiledReturnFolder_(sf.getName())) continue; // 이미 낸 신고서 보관 폴더(보고서 아님)
    rh_collectReportFilesInFolder_(sf, out, caseId, 고객명, 사건명);
  }
}

// [2026.09.17 신규] "보고서 모음 대정비" — (1) 의뢰내용류 파일은 <사건의뢰서>로 통일(위
// rh_isReportFile_에서 이미 보고서 모음 노출 자체는 제외해뒀음), (2) 나머지 보고서 파일명에서
// 사건명을 떼고 시스템 고유 명칭(검토서/자문보고서/.../번역서)만 남긴다. 세무사님 지시 —
// "같은 사건에 같은 유형 보고서가 여러 개일 리 없다, 그런 경우가 보이면 진짜 같은 것인지
// 반드시 확인해야 하고 내용이 다르면 사람이 직접 세부명칭을 정해야 한다": 자동으로 번호를
// 붙이거나 추측하지 않고, 같은 사건 안에서 같은 새 이름으로 겹치는 경우는 "충돌"로만 보고하고
// 건드리지 않는다. rh_isReportFile_로는 의뢰내용류가 걸러지므로, 이 스캔은 그 필터를 타지
// 않는 별도의 재귀 탐색을 쓴다(의뢰내용류도 봐야 이름을 바꿔줄 수 있음).
function rh_collectAllCandidateFilesInFolder_(folder, out) {
  const fIter = folder.getFiles();
  while (fIter.hasNext()) {
    const f = fIter.next();
    const name = f.getName();
    const mimeType = f.getMimeType();
    if (!rh_isIntakeLikeFile_(name) && !(RH_REPORT_MIME_ALLOW_[mimeType] || RH_REPORT_EXT_RE_.test(name))) continue;
    out.push({ id: f.getId(), name: name, mimeType: mimeType });
  }
  const subIter = folder.getFolders();
  while (subIter.hasNext()) {
    const sf = subIter.next();
    if (caseIsFiledReturnFolder_(sf.getName())) continue; // 이미 낸 신고서 보관 폴더 — 이름 바꾸기 대상 아님
    rh_collectAllCandidateFilesInFolder_(sf, out);
  }
}
function rh_guessReportTypeLabelFromName_(base) {
  let found = null;
  Object.keys(RW_DOCTYPE_FILENAME_LABELS_BY_CODE_).forEach(function (code) {
    const label = RW_DOCTYPE_FILENAME_LABELS_BY_CODE_[code];
    if (found) return;
    if (base === label || base.slice(-(label.length + 1)) === ('_' + label)) found = label;
  });
  return found;
}
function work_planReportFilenameCleanup_() {
  const sheet = work_getSheet_();
  const data = sheet.getDataRange().getValues();
  const col = work_colMap_(data[0]);
  const renamePlan = [], collisions = [], unclear = [];

  for (let i = 1; i < data.length; i++) {
    const caseId = data[i][col.id];
    const folderId = data[i][col.폴더ID];
    if (!caseId || !folderId) continue;
    let caseFolder;
    try { caseFolder = DriveApp.getFolderById(folderId); } catch (err) { continue; }
    const 사건명 = String(data[i][col.사건명] || '').trim();
    const 고객명 = String(data[i][col.고객명] || '').trim();
    const files = [];
    rh_collectAllCandidateFilesInFolder_(caseFolder, files);

    const proposalsByName = {};
    files.forEach(function (f) {
      const extMatch = f.name.match(/\.[a-zA-Z0-9]+$/);
      const ext = extMatch ? extMatch[0] : '';
      const base = ext ? f.name.slice(0, -ext.length) : f.name;

      if (rh_isIntakeLikeFile_(f.name)) {
        const newName = RW_INTAKE_CANONICAL_NAME_ + ext;
        if (f.name === newName) return;
        if (!proposalsByName[newName]) proposalsByName[newName] = [];
        proposalsByName[newName].push({ fileId: f.id, oldName: f.name });
        return;
      }
      // [2026.09.17 신규] 이미 <종합검토서> 또는 <개별검토서_세부명칭> 규칙을 따르는 파일은
      // 자동추정 맵에 없어 "판단불가"로 잘못 걸릴 뻔했다 — 이미 규칙에 맞으면 건드리지 않는다.
      if (base === '종합검토서' || /^개별검토서_.+/.test(base)) return;
      let label = rh_guessReportTypeLabelFromName_(base);
      if (!label) {
        try {
          const content = DriveApp.getFileById(f.id).getBlob().getDataAsString('UTF-8');
          const guessed = rw_guessDocTypeFromContent_(content);
          if (guessed) label = RW_DOCTYPE_FILENAME_LABELS_BY_CODE_[guessed];
        } catch (err) { /* 읽기 실패 — 아래에서 판단불가로 처리 */ }
      }
      if (!label) {
        unclear.push({ caseId: caseId, 고객명: 고객명, 사건명: 사건명, fileId: f.id, oldName: f.name });
        return;
      }
      const newName2 = label + ext;
      if (f.name === newName2) return;
      if (!proposalsByName[newName2]) proposalsByName[newName2] = [];
      proposalsByName[newName2].push({ fileId: f.id, oldName: f.name });
    });

    Object.keys(proposalsByName).forEach(function (newName3) {
      const arr = proposalsByName[newName3];
      if (arr.length === 1) {
        renamePlan.push({ caseId: caseId, 고객명: 고객명, 사건명: 사건명, fileId: arr[0].fileId, oldName: arr[0].oldName, newName: newName3 });
      } else {
        collisions.push({ caseId: caseId, 고객명: 고객명, 사건명: 사건명, proposedName: newName3, files: arr });
      }
    });
  }
  return { renamePlan: renamePlan, collisions: collisions, unclear: unclear };
}
function work_reportFilenameCleanupAction_(body) {
  const plan = work_planReportFilenameCleanup_();
  return { success: true, dryRun: true, renamePlan: plan.renamePlan, collisions: plan.collisions, unclear: plan.unclear };
}
function work_applyReportFilenameCleanup(params) {
  return withLock_(60000, function () {
    const plan = work_planReportFilenameCleanup_();
    const fileIds = Array.isArray(params.fileIds) ? params.fileIds : null;
    let applied = 0, failed = 0;
    plan.renamePlan.forEach(function (item) {
      if (fileIds && fileIds.indexOf(item.fileId) === -1) return;
      try { DriveApp.getFileById(item.fileId).setName(item.newName); applied++; } catch (err) { failed++; }
    });
    return { success: true, applied: applied, failed: failed };
  });
}

// [2026.09.16 재설계] 모아보기를 열 때마다 사건 전체를 실시간으로 재스캔해(사건마다 드라이브
// 폴더를 하위폴더까지 재귀 탐색) 사건이 쌓일수록 매번 점점 느려지던 문제 — "_보고서인덱스"
// 폴더(총괄관리자 폴더 하위)에 미리 만들어둔 index.json을 읽기만 하는 방식으로 바꾼다.
// 인덱스 자체는 (1) 문서를 저장/발행할 때 그 건만 즉시 갱신되고(handleUploadFile의
// reportMeta 처리 참고), (2) 혹시 놓친 변경(수동 삭제 등)이 있어도 매일 밤(runNightlyChiefManager)
// 전체 재구성으로 스스로 바로잡는다. 총괄관리자 폴더가 아예 설정 안 돼 있거나 인덱스 파일이
// 아직 한 번도 안 만들어졌으면(최초 1회) 예전처럼 전체 스캔으로 채운다 — 그 결과가 그대로
// 인덱스로도 저장되므로 다음 호출부터는 빨라진다.
function rh_indexFolder_() {
  const chief = getChiefManagerFolder_();
  if (!chief) return null;
  return getOrCreateSubfolder_(chief, '_보고서인덱스');
}
function rh_loadReportIndex_() {
  const folder = rh_indexFolder_();
  if (!folder) return null;
  const raw = readFileIfExists_(folder, 'index.json');
  if (raw === null) return null;
  try { return JSON.parse(raw); } catch (err) { return null; }
}
function rh_saveReportIndex_(list) {
  const folder = rh_indexFolder_();
  if (!folder) return;
  writeFileOverwrite_(folder, 'index.json', JSON.stringify(list), 'application/json');
}
function rh_rebuildReportIndexFull_() {
  const sheet = work_getSheet_();
  const data = sheet.getDataRange().getValues();
  const col = work_colMap_(data[0]);
  const files = [];
  for (let i = 1; i < data.length; i++) {
    const caseId = data[i][col.id];
    const folderId = data[i][col.폴더ID];
    if (!caseId || !folderId) continue;
    let caseFolder;
    try { caseFolder = DriveApp.getFolderById(folderId); } catch (err) { continue; }
    rh_collectReportFilesInFolder_(caseFolder, files, caseId, data[i][col.고객명], data[i][col.사건명]);
  }
  rh_saveReportIndex_(files);
  return files;
}
// 문서 저장/발행 시점에 그 파일 하나만 인덱스에 즉시 반영 — 실패해도(락 경합 등) 조용히
// 넘어간다(다음 야간 재구성이 바로잡아줌). 실제 저장/발행 자체는 이 함수와 무관하게 항상 그대로
// 성공한다(handleUploadFile에서 try/catch로 감싸 호출).
function rh_upsertReportIndexEntry_(entry) {
  if (!rh_indexFolder_()) return;
  withLock_(5000, function () {
    let list = rh_loadReportIndex_();
    if (!list) list = [];
    const idx = list.findIndex(function (x) { return x.id === entry.id; });
    if (idx >= 0) list[idx] = entry; else list.push(entry);
    rh_saveReportIndex_(list);
    return null;
  });
}
function handleListAllReports(body) {
  // [2026.09.18] body.forceRebuild가 true면 캐시를 그냥 읽지 않고 사건 폴더 전체를 다시 훑는다 —
  // rh_isReportFile_/rh_isIntakeLikeFile_ 판정 로직 자체가 바뀐 직후처럼, 기존에 이미 캐시에
  // 잘못 들어간 항목(예: 의뢰서 원문인데 보고서로 잘못 분류된 옛 항목)을 다음 야간 재구성까지
  // 기다리지 않고 바로 걷어내야 할 때 쓴다.
  let files = (body && body.forceRebuild) ? null : rh_loadReportIndex_();
  if (files === null) files = rh_rebuildReportIndexFull_();
  files.sort(function (a, b) { return b.modifiedDate - a.modifiedDate; });
  return { files: files };
}

// [2026.09.17 신규] 자동 일괄정비(work_apply_report_filename_cleanup)가 판단을 잘못 내리거나
// 목록이 너무 많아 화면에서 검토하기 어렵다는 지적에 따라, 세무사님이 "보고서 모음" 목록에서
// 파일 하나씩 직접 이름을 바꿀 수 있게 하는 별도 경로. 실제 이름변경은 handleRenameItem과
// 동일하게 DriveApp으로 하되, 그 결과를 인덱스 캐시(_보고서인덱스/index.json)에도 바로
// 반영해야 "모아보기" 목록에 새 이름이 즉시 보인다(인덱스는 실시간 스캔이 아니므로).
function handleRenameReportFile(body) {
  const fileId = String(body.fileId || '').trim();
  const newName = String(body.newName || '').trim();
  if (!fileId || !newName) return { success: false, message: '파일 또는 새 이름이 없습니다.' };
  return withLock_(8000, function () {
    try {
      DriveApp.getFileById(fileId).setName(newName);
    } catch (err) {
      return { success: false, message: '이름 변경 중 오류: ' + err.message };
    }
    try {
      let list = rh_loadReportIndex_();
      if (list) {
        const idx = list.findIndex(function (x) { return x.id === fileId; });
        if (idx >= 0) {
          list[idx] = Object.assign({}, list[idx], { name: newName, modifiedDate: Date.now() });
          rh_saveReportIndex_(list);
        }
      }
    } catch (err) {
      // 인덱스 갱신 실패해도 실제 파일명 변경은 이미 끝났다 — 다음 야간 재구성이 바로잡아준다.
    }
    return { success: true, name: newName };
  });
}

// [2026.09.17 신규] 이름수정과 같은 이유(자동 일괄정비만으로는 부족, 파일 하나씩 직접 처리해야
// 하는 경우가 많음) — "보고서 모음" 목록에서 파일을 직접 지울 수 있게 한다. 완전삭제가 아니라
// 휴지통행(handleDeleteItem과 동일한 setTrashed(true))이라 잘못 지워도 휴지통 화면에서 복원할
// 수 있다. 이름수정과 마찬가지로 인덱스 캐시에서도 그 항목을 바로 빼야 목록에서 즉시 사라진다.
function handleDeleteReportFile(body) {
  const fileId = String(body.fileId || '').trim();
  if (!fileId) return { success: false, message: '파일이 없습니다.' };
  return withLock_(8000, function () {
    try {
      DriveApp.getFileById(fileId).setTrashed(true);
    } catch (err) {
      return { success: false, message: '삭제 중 오류: ' + err.message };
    }
    try {
      let list = rh_loadReportIndex_();
      if (list) {
        const next = list.filter(function (x) { return x.id !== fileId; });
        if (next.length !== list.length) rh_saveReportIndex_(next);
      }
    } catch (err) {
      // 인덱스 갱신 실패해도 실제 삭제(휴지통 이동)는 이미 끝났다 — 다음 야간 재구성이 바로잡아준다.
    }
    return { success: true };
  });
}

// [2026.09.16 임시, 1회성] "내부보고서"/"보고서" 폴더를 "보고서_내부"/"보고서_외부"로 개명하고,
// 그 안의 옛 보고서 파일("사건명.md"/"사건명.html"만 있고 문서유형이 파일명에 없던 것들)을
// "사건명_문서유형" 규칙으로 맞춘다. 문서유형은 파일명만으로는 알 수 없으므로(그게 바로
// 이번에 고친 문제) 파일 내용 앞부분에서 유형을 나타내는 단어를 찾아 추정한다 — 확신이 서는
// 경우만 이름을 바꾸고, 못 찾으면 그대로 두고 목록에 남겨 직접 확인하시게 한다(추측으로
// 잘못된 유형 이름을 붙이지 않기 위함).
// [2026.09.17 버그수정] "검토서"를 <종합검토서>(사건 전반)/<개별검토서_세부명칭>(특정 쟁점
// 국한)로 나누기로 하면서, 파일명이나 내용에 "검토서"라는 단어가 있다는 것만으로는 둘 중
// 어느 쪽인지 기계가 판단할 수 없게 됐다 — review는 이 자동추정 맵에서 아예 빼서, 해당하는
// 옛 파일은 전부 "판단불가"(사람이 직접 종합/개별 중 골라 이름을 정해야 함)로 넘어가게 한다.
const RW_DOCTYPE_FILENAME_LABELS_BY_CODE_ = {
  advisory: '자문보고서', filing: '신고보고서', reference: '참고보고서',
  progress: '진행보고서', appeal_petition: '불복청구서', summary: '요약보고서', translation: '번역서'
};
function rw_guessDocTypeFromContent_(content) {
  const head = String(content || '').slice(0, 800);
  if (head.indexOf('불복') !== -1 || head.indexOf('이의신청') !== -1 || head.indexOf('심사청구') !== -1 || head.indexOf('심판청구') !== -1) return 'appeal_petition';
  if (head.indexOf('번역') !== -1) return 'translation';
  if (head.indexOf('신고') !== -1 && head.indexOf('보고서') !== -1) return 'filing';
  if (head.indexOf('참고') !== -1 && head.indexOf('보고서') !== -1) return 'reference';
  if (head.indexOf('진행') !== -1 && head.indexOf('보고서') !== -1) return 'progress';
  if (head.indexOf('요약') !== -1 && head.indexOf('보고서') !== -1) return 'summary';
  if (head.indexOf('자문') !== -1) return 'advisory';
  return null;
}
function migrateReportFoldersAndFilenames_() {
  const sheet = work_getSheet_();
  const data = sheet.getDataRange().getValues();
  const col = work_colMap_(data[0]);
  const log = [];
  let foldersRenamed = 0, filesRenamed = 0, filesUnclear = 0;
  const RENAME_PAIRS = [['내부보고서', WORK_SUBFOLDER_INTERNAL_REPORT], ['보고서', MY_SUBFOLDER_REPORT]];
  for (let i = 1; i < data.length; i++) {
    const caseId = data[i][col.id];
    const folderId = data[i][col.폴더ID];
    if (!caseId || !folderId) continue;
    let caseFolder;
    try { caseFolder = DriveApp.getFolderById(folderId); } catch (err) { continue; }
    const 사건명 = String(data[i][col.사건명] || '').trim();
    RENAME_PAIRS.forEach(function (pair) {
      const oldName = pair[0], newName = pair[1];
      const it = caseFolder.getFoldersByName(oldName);
      while (it.hasNext()) {
        const sub = it.next();
        if (sub.getName() !== newName) {
          sub.setName(newName);
          foldersRenamed++;
          log.push(사건명 + ': 폴더 "' + oldName + '" → "' + newName + '"');
        }
        const fIter = sub.getFiles();
        while (fIter.hasNext()) {
          const f = fIter.next();
          const m = f.getName().match(/\.(md|html?|htm)$/i);
          if (!m) continue;
          const ext = m[0];
          const base = f.getName().slice(0, -ext.length);
          if (base !== 사건명) continue; // 이미 규칙대로 바뀌었거나 사람이 따로 지은 이름 — 손대지 않음
          let content = '';
          try { content = f.getBlob().getDataAsString('UTF-8'); } catch (err) { /* 읽기 실패해도 계속 진행 */ }
          const guessedType = rw_guessDocTypeFromContent_(content);
          const label = guessedType && RW_DOCTYPE_FILENAME_LABELS_BY_CODE_[guessedType];
          if (label) {
            const newFileName = base + '_' + label + ext;
            f.setName(newFileName);
            filesRenamed++;
            log.push('  · "' + f.getName() + '" ← 파일명 변경(추정 유형: ' + label + ')');
          } else {
            filesUnclear++;
            log.push('  · "' + f.getName() + '" — 문서유형을 못 알아내 이름 그대로 둠(직접 확인 필요)');
          }
        }
      }
    });
  }
  const reportText = '폴더 개명: ' + foldersRenamed + '건\n파일명 변경: ' + filesRenamed + '건\n유형 추정 실패(수동 확인 필요): ' + filesUnclear + '건\n\n' + log.join('\n');
  let fileUrl = '';
  try {
    const chiefFolder = getChiefManagerFolder_();
    if (chiefFolder) {
      const auditFolder = getOrCreateSubfolder_(chiefFolder, '_사건폴더감사');
      const file = writeFileOverwrite_(auditFolder, '보고서폴더파일개명_' + Utilities.formatDate(new Date(), 'Asia/Seoul', 'yyyy-MM-dd_HHmm') + '.md', reportText, MimeType.PLAIN_TEXT);
      fileUrl = file.getUrl();
    }
  } catch (err) { /* 무시 */ }
  return { foldersRenamed: foldersRenamed, filesRenamed: filesRenamed, filesUnclear: filesUnclear, fileUrl: fileUrl };
}

// 템플릿다듬기: 이미 매일 밤 도는 runTemplateReview_()의 결과 파일을 그대로 읽어 보여준다
// (새 점검 로직을 또 만들지 않고 기존 야간작업을 재사용) + "지금 다시 점검" 버튼용 즉시실행.
// [2026.10.13] 템플릿다듬기 화면 — 먼저 야간 규칙 통계(토큰 0, 개선후보 보고서 templates)를 보여 주고, 예전 AI 점검 결과가 있으면 그 아래에.
function tplStatsMarkdown_(tp) {
  if (!tp || tp.error) return '## 📚 템플릿 사용 통계(야간·토큰 0)\n\n아직 통계가 없습니다' + (tp && tp.error ? ' — ' + tp.error : '') + '.\n';
  var L = ['## 📚 템플릿 사용 통계(야간 자동·AI 미사용) — ' + tp.기간 + ' 사본 ' + tp.사본수 + '건', ''];
  (tp.템플릿별 || []).forEach(function (x) {
    if (!(x.공통추가제목 || []).length && !(x.늘빈칸 || []).length) return;
    L.push('### ' + x.종류 + ' · ' + x.템플릿 + ' (사본 ' + x.사본수 + '건)');
    if ((x.공통추가제목 || []).length) L.push('- 여러 사본에 공통으로 새로 생긴 제목(템플릿에 넣을 후보): ' + x.공통추가제목.join(', '));
    if ((x.늘빈칸 || []).length) L.push('- 거의 늘 비어 있는 칸(뺄 후보): ' + x.늘빈칸.join(', '));
    L.push('');
  });
  if ((tp.새문단후보 || []).length) L.push('### 새 쟁점 문단 후보(자주 나오는데 문단 라이브러리에 없음)', tp.새문단후보.map(function (x) { return x.낱말 + '(' + x.사본 + '건)'; }).join(', '), '');
  if ((tp.문단사용 || []).length) L.push('### 쟁점 문단 사용 횟수', tp.문단사용.map(function (x) { return x.문단.replace(/\.md$/, '') + ' ' + x.사용 + '회'; }).join(', '), '');
  L.push('_매주 웹 Claude Code 루틴이 이 통계로 템플릿 수정안(PR)을 올립니다 → 깃허브에서 승인(Merge) → 설정 🐞 카드 📥 반영 시 드라이브 템플릿 갱신(드라이브에서 직접 고친 파일은 덮지 않음)._');
  return L.join('\n');
}
function handleGetLatestTemplateReview(body) {
  var statsMd = '';
  try { var rep = getImprovementReport_().report; statsMd = tplStatsMarkdown_(rep && rep.templates) + (rep && rep.generatedAt ? '\n\n_통계 생성: ' + rep.generatedAt + '_' : ''); } catch (e) {}
  const chiefFolder = getChiefManagerFolder_();
  if (!chiefFolder) return { date: null, content: statsMd || '총괄관리자 폴더가 설정되어 있지 않습니다.' };
  const folder = getOrCreateSubfolder_(chiefFolder, '_템플릿점검');
  const todayStr = Utilities.formatDate(new Date(), 'Asia/Seoul', 'yyyy-MM-dd');
  for (let back = 0; back < 35; back++) {
    const d = new Date(Date.now() - back * 86400000);
    const dateStr = Utilities.formatDate(d, 'Asia/Seoul', 'yyyy-MM-dd');
    const content = readFileIfExists_(folder, '템플릿점검_' + dateStr + '.md');
    if (content) return { date: dateStr, content: (statsMd ? statsMd + '\n\n---\n\n## 예전 AI 점검 결과(유료, 버튼으로만 실행)\n\n' : '') + content };
  }
  return { date: null, content: statsMd || '아직 점검 결과가 없습니다 — "지금 다시 점검하기"를 눌러 새로 만들 수 있습니다.' };
}
function handleRunTemplateReviewNow(body) {
  try { runTemplateReview_(); } catch (err) { return { error: '점검 실패: ' + err.message }; }
  return handleGetLatestTemplateReview(body);
}

// 글감만들기: 골라둔 보고서 파일 하나를 읽어, AI로 블로그/소식글용 글감(초안)으로 다시 쓴다.
