// 사건개요서 항목 정의(라벨·입력형식)는 casehandling.html의 CH_CASE_OVERVIEW_FIELDS_에
// 있다(순수 화면 렌더링용 메타데이터라 서버는 어떤 필드가 있는지 몰라도 되고, 사건개요는
// 그냥 {필드key: 값} 객체를 그대로 저장·반환하기만 한다).

// 사건개요(사건개요서 양식)를 처음 저장할 때 증빙목록 초기값을 만든다 — "사건개요가 먼저
// 정리돼야 필요증빙도 제대로 나온다"는 지적에 따라, 예전처럼 사건 "생성" 시점이 아니라
// 사건개요를 처음 저장하는 시점(work_updateCase)에 적용한다. 업무유형이 '신고'(상담은
// 아직 본격적인 증빙 확보 단계가 아니므로 제외)일 때만 채우고, 그 외엔 기존과 동일하게
// 빈 배열로 둔다. caseClassification(사건개요의 "사건분류" 값)이 있으면 공통 목록에
// 그 분류 전용 항목을 더한다 — 없거나 매칭 안 되면 공통 목록만 쓴다. 항목 형태는
// casehandling.html의 chAddRequestedItem_이 만드는 것과 동일(source:'requested', status:'미확보').
function work_buildEvidenceFromTemplate_(seMok, upType, caseClassification, assetList, acqBundleAll, transferBundleAll) {
  const template = WORK_EVIDENCE_TEMPLATES_[seMok];
  const classificationOnlyLabels = (upType === '신고' && template && caseClassification && template.사건분류) ? (template.사건분류[caseClassification] || []) : [];
  const labels = (upType === '신고' && template) ? (template.공통 || []).concat(classificationOnlyLabels) : [];
  // [2026.09 버그수정] 사건분류를 나중에 바꿔도(예: "미등기양도"→"일반과세" 정정) 예전 분류
  // 전용 항목이 증빙목록에 영원히 남아있던 문제 — 어느 라벨이 "이 사건분류 때문에" 생겼는지
  // classificationOnlyLabels로 표시해두고, 아래 work_updateCase가 사건분류가 실제로 바뀌었을
  // 때 그 표시가 붙은 항목 중 아직 미확보인 것만 자동으로 정리한다(이미 확보한 서류는 분류가
  // 바뀌어도 실제로 받은 자료이므로 절대 건드리지 않는다).
  const classificationLabelSet = {};
  classificationOnlyLabels.forEach(function (l) { classificationLabelSet[l] = true; });
  // [2026.09 버그수정] 물건이 여러 건이면 서류를 세 가지 기준 중 하나로 나눠 요청한다 —
  // 등기부등본은 물건(필지)별로, 취득 관련 서류는 취득계약 구분별로, 양도계약서는 양도계약
  // 구분별로(구분값을 안 적었으면 물건마다 별도 계약으로 간주 — 예전과 동일하게 동작).
  const perAssetLabels = WORK_EVIDENCE_PER_ASSET_LABELS_[seMok] || [];
  const perAcqGroupLabels = WORK_EVIDENCE_PER_ACQUISITION_GROUP_LABELS_[seMok] || [];
  const perTransferGroupLabels = WORK_EVIDENCE_PER_TRANSFER_GROUP_LABELS_[seMok] || [];
  const assets = Array.isArray(assetList) ? assetList : [];
  // [2026.09 버그수정] 물건별/계약그룹별 라벨에 소재지 문자열을 그대로 넣다 보니(예: "등기부
  // 등본(서울시 강남구...)"), 그 소재지를 나중에 사건개요서에서 정정하면 예전 라벨과 문자열이
  // 완전히 달라져 새 항목이 또 생기고 옛 라벨의 항목은 영원히 미확보 상태로 고아처럼 남는
  // 문제가 있었다(실사용 감사 지적) — 물건 인덱스·그룹 번호처럼 안 바뀌는 slotKey를 따로
  // 붙여서, 아래 work_updateCase가 라벨 문자열이 아니라 slotKey로 같은 슬롯을 알아보고
  // 라벨만 최신으로 갱신하게 한다.
  let expandedLabels = labels.map(function (label) { return { label: label, slotKey: label, fromClassification: classificationLabelSet[label] ? caseClassification : null }; });
  if (assets.length > 1 && (perAssetLabels.length || perAcqGroupLabels.length || perTransferGroupLabels.length)) {
    const acqGroups = work_groupAssetsForEvidence_(assets, '취득계약구분', !!acqBundleAll);
    const transferGroups = work_groupAssetsForEvidence_(assets, '양도계약구분', !!transferBundleAll);
    expandedLabels = [];
    labels.forEach(function (label) {
      const fc = classificationLabelSet[label] ? caseClassification : null;
      if (perAssetLabels.indexOf(label) !== -1) {
        assets.forEach(function (asset, idx) {
          const tag = (asset && asset.assetLocation) ? asset.assetLocation : ('물건' + (idx + 1));
          expandedLabels.push({ label: label + '(' + tag + ')', slotKey: label + '#asset' + idx, fromClassification: fc });
        });
        return;
      }
      if (perAcqGroupLabels.indexOf(label) !== -1) {
        acqGroups.forEach(function (group, gi) { expandedLabels.push({ label: label + '(' + work_evidenceGroupTag_(group, gi) + ')', slotKey: label + '#acqgroup' + gi, fromClassification: fc }); });
        return;
      }
      if (perTransferGroupLabels.indexOf(label) !== -1) {
        transferGroups.forEach(function (group, gi) { expandedLabels.push({ label: label + '(' + work_evidenceGroupTag_(group, gi) + ')', slotKey: label + '#trgroup' + gi, fromClassification: fc }); });
        return;
      }
      expandedLabels.push({ label: label, slotKey: label, fromClassification: fc });
    });
  }
  const today = Utilities.formatDate(new Date(), Session.getScriptTimeZone(), 'yyyy-MM-dd');
  return expandedLabels.map(function (entry, i) {
    return { id: 'ev_' + Date.now() + '_' + i, source: 'requested', label: entry.label, slotKey: entry.slotKey, fromClassification: entry.fromClassification, note: '', status: '미확보', 요청일: today };
  });
}

// 시트를 열고, 처음 만드는 거면 헤더까지 써준다. 이미 있는 시트인데 WORK_HEADERS에 새 컬럼이
// 추가된 상태(예: 고객ID 신규 도입)면, 기존 데이터는 그대로 두고 빠진 헤더만 뒤에 이어붙인다
// — work_colMap_이 이름으로 컬럼을 찾으므로 위치가 중간이 아니어도 문제없다.
function work_getSheet_() {
  const ss = SpreadsheetApp.openById(WORK_SHEET_ID);
  let sheet = ss.getSheetByName(WORK_SHEET_CASES);
  if (!sheet) {
    sheet = ss.insertSheet(WORK_SHEET_CASES);
    sheet.appendRow(WORK_HEADERS);
    return sheet;
  }
  const lastCol = Math.max(sheet.getLastColumn(), 1);
  const existingHeaders = sheet.getRange(1, 1, 1, lastCol).getValues()[0];
  const missing = WORK_HEADERS.filter(function (h) { return existingHeaders.indexOf(h) === -1; });
  if (missing.length > 0) {
    sheet.getRange(1, existingHeaders.length + 1, 1, missing.length).setValues([missing]);
  }
  return sheet;
}

function work_colMap_(headers) {
  const map = {};
  WORK_HEADERS.forEach(function (name) { map[name] = headers.indexOf(name); });
  return map;
}

// [2026.09 신규] 사건폴더 흡수 조사 — 이 시스템으로 사건등록하지 않고 예전부터 있었거나
// 수동으로 만든 "고객사건" 폴더는 WORK_CASES 시트에 폴더ID가 없어서, 현금영수증 자동인식
// (runCashReceiptScan_→findCaseForFile_)이나 보고서 모음(handleListAllReports)이 전혀
// 찾지 못한다. 읽기 전용 — 아무것도 쓰지 않고 "고객사건" 바로 아래 폴더 중 시트에 없는
// 것만 뽑아 보여준다(실제 흡수/등록은 이 결과를 보고 방식을 정한 뒤 별도로 진행).
function auditUnregisteredCaseFolders_() {
  const root = getDefaultFolder();
  const sheet = work_getSheet_();
  const data = sheet.getDataRange().getValues();
  const col = work_colMap_(data[0]);
  const registered = {};
  for (let i = 1; i < data.length; i++) {
    const fid = String(data[i][col.폴더ID] || '').trim();
    if (fid) registered[fid] = true;
  }
  const iter = root.getFolders();
  let total = 0;
  const unregistered = [];
  while (iter.hasNext()) {
    const f = iter.next();
    total++;
    if (registered[f.getId()]) continue;
    if (work_isSpecialRootFolder_(f.getName())) continue;
    let hasReportStructure = false;
    try {
      hasReportStructure = f.getFoldersByName(WORK_SUBFOLDER_INTERNAL_REPORT).hasNext() || f.getFoldersByName(MY_SUBFOLDER_REPORT).hasNext();
    } catch (err) { /* 하위폴더 조회 실패해도 조사 자체는 계속 */ }
    unregistered.push({
      id: f.getId(),
      name: f.getName(),
      createdDate: Utilities.formatDate(f.getDateCreated(), 'Asia/Seoul', 'yyyy-MM-dd'),
      hasReportStructure: hasReportStructure
    });
  }
  let reportText = '# 사건폴더 흡수 조사 결과 (' + Utilities.formatDate(new Date(), 'Asia/Seoul', 'yyyy-MM-dd HH:mm') + ')\n\n';
  reportText += '- 고객사건 폴더 바로 아래 전체: ' + total + '개\n';
  reportText += '- 시트(WORK_CASES)에 등록된 폴더: ' + (total - unregistered.length) + '개\n';
  reportText += '- **미등록 폴더: ' + unregistered.length + '개**\n\n';
  reportText += '| 폴더명 | 생성일 | 보고서구조있음 | 폴더ID |\n|---|---|---|---|\n';
  unregistered.forEach(function (u) {
    reportText += '| ' + u.name + ' | ' + u.createdDate + ' | ' + (u.hasReportStructure ? 'O' : '-') + ' | ' + u.id + ' |\n';
  });
  let fileUrl = '';
  try {
    const chiefFolder = getChiefManagerFolder_();
    if (chiefFolder) {
      const auditFolder = getOrCreateSubfolder_(chiefFolder, '_사건폴더감사');
      const fileName = '사건폴더감사_' + Utilities.formatDate(new Date(), 'Asia/Seoul', 'yyyy-MM-dd_HHmm') + '.md';
      const file = writeFileOverwrite_(auditFolder, fileName, reportText, MimeType.PLAIN_TEXT);
      fileUrl = file.getUrl();
    }
  } catch (err) { /* 파일 저장 실패해도 아래 Logger.log로는 확인 가능 */ }
  const summary = {
    총폴더수: total,
    등록된폴더수: total - unregistered.length,
    미등록폴더수: unregistered.length,
    결과파일: fileUrl,
    미등록목록: unregistered
  };
  Logger.log(JSON.stringify(summary, null, 2));
  return summary;
}

// [2026.09 신규] 위 조사에서 찾은 미등록 사건폴더를 실제로 WORK_CASES 시트에 등록해
// "흡수"한다 — 세무사님 확인: 목록 중 "고객F..."만 실제 데이터고 나머지 테스트로 보이는
// 몇 개는 흡수 뒤에 직접 삭제/수정하겠다고 하여, 필터링 없이 미등록 폴더 전부를 등록한다.
// 폴더명에서 고객명(첫 단어)·세목(양도/증여/상속/불복 키워드)을 최대한 추정하되, 못 맞추면
// 빈 값으로 두고 나중에 workmanage.html에서 직접 고치면 된다(자동 생성 폴더가 아니라 이미
// 있는 실제 폴더를 연결만 하는 것이므로 work_getOrCreateCaseFolder_처럼 새 폴더를 만들지
// 않고 기존 폴더ID를 그대로 쓴다).
function absorbLegacyCaseFolders_() {
  return withLock_(20000, function () {
    const root = getDefaultFolder();
    const sheet = work_getSheet_();
    const data = sheet.getDataRange().getValues();
    const col = work_colMap_(data[0]);
    const registered = {};
    for (let i = 1; i < data.length; i++) {
      const fid = String(data[i][col.폴더ID] || '').trim();
      if (fid) registered[fid] = true;
    }
    const SEMOK_KEYWORDS_ = [
      { kw: '양도', semok: 'transfer' },
      { kw: '증여', semok: 'gift' },
      { kw: '상속', semok: 'inheritance' },
      { kw: '불복', semok: 'objection' }
    ];
    function guessSemok_(name) {
      for (let i = 0; i < SEMOK_KEYWORDS_.length; i++) {
        if (name.indexOf(SEMOK_KEYWORDS_[i].kw) !== -1) return SEMOK_KEYWORDS_[i].semok;
      }
      return '';
    }
    function guessCustomerName_(name) {
      const m = String(name || '').trim().match(/^([^\s]+)/);
      return m ? m[1] : name;
    }
    const iter = root.getFolders();
    const now = new Date();
    const rowsToAppend = [];
    const resultList = [];
    while (iter.hasNext()) {
      const f = iter.next();
      const fid = f.getId();
      if (registered[fid]) continue;
      const folderName = f.getName();
      if (work_isSpecialRootFolder_(folderName)) continue; // 사건이 아닌 특수폴더(0_NX_0 현금영수증 보관함·1 상담사건·1 확인조치사항)
      const 고객명 = guessCustomerName_(folderName);
      const 세목 = guessSemok_(folderName);
      const clientMatch = client_findOrCreateByName_(고객명, '');
      const row = new Array(WORK_HEADERS.length).fill('');
      row[col.id] = Utilities.getUuid();
      row[col.고객ID] = clientMatch.id;
      row[col.고객명] = 고객명;
      row[col.사건명] = folderName;
      row[col.세목] = 세목;
      row[col.납세자] = 고객명;
      row[col.상태] = '완료';
      row[col.하위업무] = '[]';
      row[col.작업일지] = '[]';
      row[col.법령예규판례] = '[]';
      row[col.증빙목록] = '[]';
      row[col.세액계산결과] = '[]';
      row[col.사건개요] = '{}';
      row[col.폴더ID] = fid;
      row[col.생성일] = now;
      row[col.수정일] = now;
      rowsToAppend.push(row);
      resultList.push(folderName + (세목 ? ' (' + WORK_SEMOK_LABELS_[세목] + ')' : ' (세목 미확인 — 직접 지정 필요)'));
    }
    if (rowsToAppend.length) {
      sheet.getRange(sheet.getLastRow() + 1, 1, rowsToAppend.length, WORK_HEADERS.length).setValues(rowsToAppend);
    }
    const msg = '흡수 완료: ' + rowsToAppend.length + '건 등록\n' + resultList.join('\n');
    Logger.log(msg);
    return { added: rowsToAppend.length, list: resultList };
  });
}

// [2026.09 임시, 1회성] 흡수된 사건들의 사건명/폴더명을 시스템 명명규칙(work_generateUniqueCaseName_)
// 그대로 재작성하고 Drive 폴더명도 동기화한다. 먼저 "고객명(납세자)"가 흡수 당시 통째로
// 고객명 하나로 잘못 들어간 것들(고객J(고객J 납세자)과 같은 패턴)을 고객명/납세자로 분리한 뒤,
// 세목이 있는 모든 사건의 사건명을 규칙대로 다시 만든다. 세목이 아직 없는 사건은 규칙을
// 적용할 수 없어 건너뛰고 목록만 남긴다.
function normalizeAllCaseNamesAndClients_() {
  return withLock_(30000, function () {
    const sheet = work_getSheet_();
    const log = [];
    let data = sheet.getDataRange().getValues();
    const col = work_colMap_(data[0]);

    // 1단계: 고객명 필드에 "이름(다른이름)"이 통째로 들어간 것 분리
    const parenPattern = /^(.+?)\(([^()]+)\)$/;
    for (let i = 1; i < data.length; i++) {
      const rawName = String(data[i][col.고객명] || '').trim();
      const m = rawName.match(parenPattern);
      if (!m) continue;
      const currentTaxpayer = String(data[i][col.납세자] || '').trim();
      if (currentTaxpayer && currentTaxpayer !== rawName) continue; // 이미 제대로 분리되어 있으면 건너뜀
      const realCust = m[1].trim();
      const taxpayer = m[2].trim();
      const rowNum = i + 1;
      const newClientMatch = client_findOrCreateByName_(realCust, '');
      sheet.getRange(rowNum, col.고객ID + 1).setValue(newClientMatch.id);
      sheet.getRange(rowNum, col.고객명 + 1).setValue(realCust);
      sheet.getRange(rowNum, col.납세자 + 1).setValue(taxpayer);
      log.push('고객명 분리: "' + rawName + '" → 고객명=' + realCust + ', 납세자=' + taxpayer);
      try {
        const sheets = client_getSheets_();
        const cdata = sheets.clients.getDataRange().getValues();
        const ccol = client_colMap_(cdata[0], CLIENT_HEADERS);
        for (let k = cdata.length - 1; k >= 1; k--) {
          if (String(cdata[k][ccol.성명] || '').trim() === rawName) {
            sheets.clients.deleteRow(k + 1);
            log.push('잘못된 고객레코드 삭제: ' + rawName);
          }
        }
      } catch (err) { log.push('고객레코드 정리 실패(' + rawName + '): ' + err.message); }
    }

    data = sheet.getDataRange().getValues();

    // 2단계: 세목이 있는 모든 사건의 사건명을 규칙대로 재작성 + 폴더명 동기화
    for (let i = 1; i < data.length; i++) {
      const rowNum = i + 1;
      const seMok = String(data[i][col.세목] || '').trim();
      const 고객명 = String(data[i][col.고객명] || '').trim();
      if (!고객명 || !seMok) continue;
      const 고객ID = data[i][col.고객ID];
      const upType = String(data[i][col.업무유형] || '').trim();
      const 납세자 = String(data[i][col.납세자] || '').trim() || 고객명;
      const oldName = String(data[i][col.사건명] || '').trim();
      sheet.getRange(rowNum, col.사건명 + 1).setValue(''); // 자기 자신과 충돌 방지
      const newName = work_generateUniqueCaseName_(sheet, col, 고객ID, 고객명, seMok, upType, 납세자);
      sheet.getRange(rowNum, col.사건명 + 1).setValue(newName);
      if (newName !== oldName) {
        const fid = String(data[i][col.폴더ID] || '').trim();
        if (fid) {
          try { DriveApp.getFolderById(fid).setName(newName); } catch (err) { log.push('폴더명변경 실패(' + oldName + '): ' + err.message); }
        }
        log.push(oldName + ' → ' + newName);
      }
    }

    data = sheet.getDataRange().getValues();
    const noSemok = [];
    for (let i = 1; i < data.length; i++) {
      if (!String(data[i][col.세목] || '').trim()) {
        noSemok.push(String(data[i][col.사건명] || '') + ' (고객명:' + data[i][col.고객명] + ')');
      }
    }

    const reportText = '=== 이름변경 (' + log.length + '건) ===\n' + log.join('\n') + '\n\n=== 세목 없어 규칙 적용 못한 것 (' + noSemok.length + '건) ===\n' + noSemok.join('\n');
    let fileUrl = '';
    try {
      const chiefFolder = getChiefManagerFolder_();
      if (chiefFolder) {
        const auditFolder = getOrCreateSubfolder_(chiefFolder, '_사건폴더감사');
        const file = writeFileOverwrite_(auditFolder, '이름규칙정리_' + Utilities.formatDate(new Date(), 'Asia/Seoul', 'yyyy-MM-dd_HHmm') + '.md', reportText, MimeType.PLAIN_TEXT);
        fileUrl = file.getUrl();
      }
    } catch (err) { /* 파일 저장 실패해도 Logger.log로 일부는 확인 가능 */ }
    Logger.log('결과파일: ' + fileUrl + '\n\n' + reportText);
    return { fileUrl: fileUrl, renameLog: log, noSemokList: noSemok };
  });
}

// [2026.09.15 임시, 1회성] 상속세 사건의 "납세자" 동기화 대상을 대표 상속인(상속인성명)에서
// 피상속인(ihDeceasedName)으로 바꾼 규칙 변경 — 앞으로 저장되는 사건은 자동으로 맞춰지지만,
// 이미 등록된 지난 상속세 사건들은 납세자란에 옛 값(대표 상속인 이름, 또는 아예 고객명과
// 동일)이 남아있다. 그 사건들을 찾아 사건개요.ihDeceasedName으로 납세자를 맞추고,
// normalizeAllCaseNamesAndClients_를 이어 실행해 사건명/폴더명까지 새 납세자 기준으로
// 재생성한다(고객명(납세자)_세목_업무유형 규칙).
function syncInheritanceTaxpayerToDecedent_() {
  return withLock_(30000, function () {
    const sheet = work_getSheet_();
    const data = sheet.getDataRange().getValues();
    const col = work_colMap_(data[0]);
    const log = [];
    const skippedNoDecedent = []; // 피상속인 성명이 아직 입력 안 된 상속세 사건(수동으로 채워야 함)
    let inheritanceCount = 0;
    for (let i = 1; i < data.length; i++) {
      const seMok = String(data[i][col.세목] || '').trim();
      if (seMok !== 'inheritance') continue;
      inheritanceCount++;
      let overview = {};
      try { overview = JSON.parse(data[i][col.사건개요] || '{}'); } catch (e) { overview = {}; }
      const decedent = String((overview && overview.ihDeceasedName) || '').trim();
      if (!decedent) { skippedNoDecedent.push(String(data[i][col.사건명] || '(사건명 없음)')); continue; }
      const currentTaxpayer = String(data[i][col.납세자] || '').trim();
      if (currentTaxpayer === decedent) continue;
      const rowNum = i + 1;
      sheet.getRange(rowNum, col.납세자 + 1).setValue(decedent);
      log.push((data[i][col.사건명] || '(사건명 없음)') + ' — 납세자: "' + currentTaxpayer + '" → "' + decedent + '"');
    }
    let renameResult = null;
    if (log.length) {
      SpreadsheetApp.flush();
      renameResult = normalizeAllCaseNamesAndClients_();
    }
    const reportText = '전체 상속세 사건: ' + inheritanceCount + '건\n' +
      '납세자 변경: ' + log.length + '건\n' + log.join('\n') + '\n\n' +
      '피상속인 성명 미입력(건너뜀): ' + skippedNoDecedent.length + '건\n' + skippedNoDecedent.join('\n') + '\n\n' +
      '사건명/폴더명 재생성 로그:\n' + (renameResult ? JSON.stringify(renameResult.renameLog || [], null, 2) : '(대상 없어 실행 안 함)');
    let fileUrl = '';
    try {
      const chiefFolder = getChiefManagerFolder_();
      if (chiefFolder) {
        const auditFolder = getOrCreateSubfolder_(chiefFolder, '_사건폴더감사');
        const file = writeFileOverwrite_(auditFolder, '상속납세자동기화_' + Utilities.formatDate(new Date(), 'Asia/Seoul', 'yyyy-MM-dd_HHmm') + '.md', reportText, MimeType.PLAIN_TEXT);
        fileUrl = file.getUrl();
      }
    } catch (err) { /* 파일 저장 실패해도 반환값으로는 확인 가능 */ }
    return { inheritanceCount: inheritanceCount, updated: log.length, log: log, skippedNoDecedent: skippedNoDecedent, renameResult: renameResult, fileUrl: fileUrl };
  });
}

// [2026.09 임시, 1회성] runCashReceiptScan_이 jpg/pdf 중복 처리 버그로 이미 만들어버린
// 중복 수금내역(고객명/날짜/금액/내용/수취증빙이 완전히 같은 행)을 찾아 하나만 남기고 지운다.
function removeDuplicateConsultLogs_() {
  return withLock_(15000, function () {
    const sheets = client_getSheets_();
    const data = sheets.log.getDataRange().getValues();
    const col = client_colMap_(data[0], CONSULT_HEADERS);
    const seen = {};
    const rowsToDelete = [];
    const log = [];
    for (let i = 1; i < data.length; i++) {
      const content = String(data[i][col.내용] || '');
      const 수취증빙 = String(data[i][col.수취증빙] || '');
      // 현금영수증 항목은 (1) 파일명만 다른 자동인식 중복("...고객BC.jpg" vs "...고객BC.pdf")과
      // (2) 세무사님이 이미 수동으로 입력해둔 것을 자동스캔이 또 기록한 경우(내용이 비어있는
      // 수동입력 vs "현금영수증 파일 자동 인식(...)") 두 가지 다 있어서, 이 유형은 내용을 아예
      // 안 보고 고객명/날짜/금액만으로 비교한다. 그 밖의 상담유형은 예전처럼 내용까지 완전일치
      // 해야만 중복으로 본다(서로 다른 실제 상담을 잘못 지우지 않기 위함).
      const contentKey = 수취증빙 === '현금영수증' ? '' : content;
      const key = [
        data[i][col.고객명], data[i][col.날짜], data[i][col.금액], contentKey, 수취증빙
      ].join('||');
      if (seen[key]) {
        rowsToDelete.push(i);
        log.push('중복 삭제: ' + data[i][col.고객명] + ' / ' + data[i][col.날짜] + ' / ' + data[i][col.금액]);
      } else {
        seen[key] = true;
      }
    }
    rowsToDelete.sort(function (a, b) { return b - a; }).forEach(function (idx) {
      sheets.log.deleteRow(idx + 1);
    });
    Logger.log(log.join('\n'));
    return { removed: rowsToDelete.length, log: log };
  });
}

// [2026.09 임시] 예약관리 점검 — (1) 이름에 깨진문자(스팸성)가 있는 신청을 찾고,
// (2) 오늘 삭제한 테스트사건("임직권 상생임대")에 연결된 예약이 있는지 확인한다. 읽기전용.
function inspectBookingIssues_() {
  const ss = SpreadsheetApp.openById(BOOKING_SHEET_ID);
  const sheet = ss.getSheetByName('Applications');
  const data = sheet.getDataRange().getValues();
  const workSheet = work_getSheet_();
  const wdata = workSheet.getDataRange().getValues();
  const wcol = work_colMap_(wdata[0]);
  const validCaseIds = {};
  for (let i = 1; i < wdata.length; i++) { if (wdata[i][wcol.id]) validCaseIds[wdata[i][wcol.id]] = true; }

  const garbled = [];
  const orphanCase = [];
  for (let i = 1; i < data.length; i++) {
    const name = String(data[i][1] || '');
    const rowNum = i + 1;
    if (/[�]/.test(name) || /^\[.*\]/.test(name)) {
      garbled.push({ rowNum: rowNum, name: name, phone: data[i][2], type: data[i][3] });
    }
    const caseId = data[i][12];
    if (caseId && !validCaseIds[caseId]) {
      orphanCase.push({ rowNum: rowNum, name: name, caseId: caseId });
    }
  }
  Logger.log('깨진문자 의심: ' + JSON.stringify(garbled, null, 2) + '\n\n연결된 사건이 없어진 예약: ' + JSON.stringify(orphanCase, null, 2));
  return { garbled: garbled, orphanCase: orphanCase };
}

// [2026.09 임시, 1회성] 예약관리의 테스트/스팸성 예약 3건(2026-09-23 임직권, 2026-10-15,
// 2026-10-16 깨진문자 스팸) 삭제 — 연결된 구글캘린더 일정이 있으면 그것도 같이 지운다.
function removeTestBookings_() {
  const ss = SpreadsheetApp.openById(BOOKING_SHEET_ID);
  const sheet = ss.getSheetByName('Applications');
  const data = sheet.getDataRange().getValues();
  const targetDates = ['2026-09-23', '2026-10-15', '2026-10-16'];
  const log = [];
  const rowsToDelete = [];
  for (let i = 1; i < data.length; i++) {
    const reservedDate = data[i][6] ? Utilities.formatDate(new Date(data[i][6]), 'Asia/Seoul', 'yyyy-MM-dd') : '';
    if (targetDates.indexOf(reservedDate) === -1) continue;
    const eventId = data[i][11];
    if (eventId) {
      try {
        const ev = CalendarApp.getEventById(eventId);
        if (ev) { ev.deleteEvent(); log.push('캘린더 일정 삭제: ' + eventId); }
      } catch (err) { log.push('캘린더 일정 삭제 실패(' + eventId + '): ' + err.message); }
    }
    rowsToDelete.push(i);
    log.push('예약 삭제: ' + reservedDate + ' / ' + data[i][1]);
  }
  rowsToDelete.sort(function (a, b) { return b - a; }).forEach(function (idx) { sheet.deleteRow(idx + 1); });
  Logger.log(log.join('\n'));
  return { removed: rowsToDelete.length, log: log };
}

// [2026.09 임시] 세무사님이 "고객관리~사건처리 연결이 다 끊어졌다"고 지적 — 오늘 작업 중
// 고객ID를 많이 바꿔서 그런지 확인한다. 모든 사건의 고객ID가 실제 고객관리 명단에 있는지,
// 고객ID 자체가 비어있는 사건은 없는지 점검한다. 읽기전용.
function inspectClientCaseLinkIntegrity_() {
  const sheet = work_getSheet_();
  const data = sheet.getDataRange().getValues();
  const col = work_colMap_(data[0]);
  const sheets = client_getSheets_();
  const cdata = sheets.clients.getDataRange().getValues();
  const ccol = client_colMap_(cdata[0], CLIENT_HEADERS);
  const validClientIds = {};
  for (let i = 1; i < cdata.length; i++) { if (cdata[i][ccol.id]) validClientIds[cdata[i][ccol.id]] = true; }

  const missingClientId = [];
  const brokenClientId = [];
  for (let i = 1; i < data.length; i++) {
    const cid = data[i][col.고객ID];
    const caseName = data[i][col.사건명];
    if (!cid) { missingClientId.push(caseName); continue; }
    if (!validClientIds[cid]) { brokenClientId.push({ 사건명: caseName, 고객ID: cid }); }
  }
  const result = {
    총사건수: data.length - 1,
    총고객수: cdata.length - 1,
    고객ID없는사건: missingClientId,
    고객ID가유효하지않은사건: brokenClientId
  };
  Logger.log(JSON.stringify(result, null, 2));
  return result;
}

// [2026.09 임시] 실제 사건 행의 원본 값을 그대로 덤프 — work_get_cases가 클라이언트에 보내는
// 것과 같은 가공(work_readRow_) 전/후를 모두 확인해서, 화면에서 클릭해도 안 뜨는 원인을 찾는다.
function inspectCaseRawData_(caseNameContains) {
  const sheet = work_getSheet_();
  const data = sheet.getDataRange().getValues();
  const col = work_colMap_(data[0]);
  const matches = [];
  for (let i = 1; i < data.length; i++) {
    if (String(data[i][col.사건명] || '').indexOf(caseNameContains) !== -1) {
      const raw = {};
      WORK_HEADERS.forEach(function (h) { raw[h] = data[i][col[h]]; });
      let parsed = null;
      let parseError = null;
      try { parsed = work_readRow_(col, data[i]); } catch (err) { parseError = err.message; }
      matches.push({ rowNum: i + 1, raw: raw, parsedOk: !parseError, parseError: parseError, parsed: parsed });
    }
  }
  Logger.log(JSON.stringify(matches, null, 2));
  return matches;
}

// [2026.09 임시] work_get_cases의 실제 전체 응답을 그대로 파일로 저장 — 화면(하네스)에 그대로
// 넣어서 재현해보기 위함. 91건이라 로그창에 다 안 보일 수 있어 파일로 남긴다.
function dumpAllCasesToFile_() {
  const result = work_getCases({});
  let fileUrl = '';
  try {
    const chiefFolder = getChiefManagerFolder_();
    if (chiefFolder) {
      const auditFolder = getOrCreateSubfolder_(chiefFolder, '_사건폴더감사');
      const file = writeFileOverwrite_(auditFolder, '전체사건덤프_' + Utilities.formatDate(new Date(), 'Asia/Seoul', 'yyyy-MM-dd_HHmm') + '.json', JSON.stringify(result), MimeType.PLAIN_TEXT);
      fileUrl = file.getUrl();
    }
  } catch (err) { /* 무시 */ }
  Logger.log('결과파일: ' + fileUrl);
  return { fileUrl: fileUrl, caseCount: (result.cases || []).length };
}

// [2026.09 임시, 근본원인 수정] "3733"/"6958"/"1520"처럼 숫자로만 된 고객명·납세자가 구글
// 시트에 진짜 숫자로 저장되어 있었다 — 클라이언트 코드가 문자열 메서드(.replace 등)를
// 호출하면 예외가 나서 작업관리 사건 목록을 다시 그릴 때마다(=클릭할 때마다) 그 지점에서
// 멈춰 사건 상세보기가 아예 실행되지 않는 심각한 문제로 이어졌다. 셀 서식을 텍스트로
// 바꾸고 문자열로 다시 써서 앞으로도 숫자로 재해석되지 않게 한다.
function fixNumericCustomerNames_() {
  const sheet = work_getSheet_();
  const data = sheet.getDataRange().getValues();
  const col = work_colMap_(data[0]);
  const log = [];
  for (let i = 1; i < data.length; i++) {
    const rowNum = i + 1;
    ['고객명', '납세자'].forEach(function (field) {
      const v = data[i][col[field]];
      if (typeof v === 'number') {
        const range = sheet.getRange(rowNum, col[field] + 1);
        range.setNumberFormat('@').setValue(String(v));
        log.push('행 ' + rowNum + ' ' + field + ': ' + v + ' → 텍스트로 변환');
      }
    });
  }
  Logger.log(log.join('\n') || '숫자로 저장된 고객명/납세자 없음');
  return { fixedCount: log.length, log: log };
}

// [2026.09.16 임시, 1회성] 위와 같은 버그가 고객관리(Clients 시트)의 성명에서도 발생 —
// "3733"처럼 숫자로만 된 성명이 구글시트에 실제 숫자로 저장되어, 화면의 정렬
// ((a.성명||'').localeCompare)이 예외를 내며 고객관리 탭 전체가 멈췄다. 같은 방식으로
// 성명·전화번호·사업자번호·추가연락처(전부 숫자로만 될 수 있는 필드)를 텍스트로 되돌린다.
function fixNumericClientFields_() {
  const sheets = client_getSheets_();
  const data = sheets.clients.getDataRange().getValues();
  const col = client_colMap_(data[0], CLIENT_HEADERS);
  const log = [];
  for (let i = 1; i < data.length; i++) {
    const rowNum = i + 1;
    ['성명', '전화번호', '사업자번호', '추가연락처'].forEach(function (field) {
      const v = data[i][col[field]];
      if (typeof v === 'number') {
        sheets.clients.getRange(rowNum, col[field] + 1).setNumberFormat('@').setValue(String(v));
        log.push('행 ' + rowNum + ' ' + field + ': ' + v + ' → 텍스트로 변환');
      }
    });
  }
  Logger.log(log.join('\n') || '숫자로 저장된 고객 필드 없음');
  return { fixedCount: log.length, log: log };
}

// dateFns.addMonths와 동일하게 동작: 같은 일(day)을 유지하되, 그 달에 없는 날짜면 그 달의
// 말일로 맞춘다(롤오버시키지 않음). explorer.js 기한계산 팝업과 계산 결과를 일치시키기 위함.
function work_addMonthsClamped_(date, months) {
  const targetIndex = date.getMonth() + months;
  const targetYear = date.getFullYear() + Math.floor(targetIndex / 12);
  const targetMonth = ((targetIndex % 12) + 12) % 12;
  const lastDayOfTargetMonth = new Date(targetYear, targetMonth + 1, 0).getDate();
  const day = Math.min(date.getDate(), lastDayOfTargetMonth);
  return new Date(targetYear, targetMonth, day);
}

function work_calcDeadline_(seMok, upType, baseDateStr) {
  const hasDaysRule = WORK_DEADLINE_DAYS_[upType] !== undefined;
  const hasYearsRule = WORK_DEADLINE_YEARS_[upType] !== undefined;
  const hasMonthsRule = WORK_DEADLINE_MONTHS_[seMok] !== undefined;
  if (!hasDaysRule && !hasYearsRule && !hasMonthsRule) return '';

  // [2026.09] 기준일(양도일·증여일·사망일 등)을 아직 안 입력한 상태 — 계산할 원시데이터가
  // 없을 뿐, 이 세목/업무유형엔 분명히 기한 규칙이 있으므로 빈 값으로 두지 않는다. 상담처럼
  // "우선 오늘부터 1주일"을 임시 기본값으로 잡아, 사건이 목록·대시보드 마감임박 집계에서
  // 조용히 누락되지 않게 한다. 기준일을 입력하면(사건개요서 저장 시 recalc) 그 즉시 이
  // 임시값이 진짜 기한으로 다시 계산된다.
  if (!baseDateStr) {
    const d = new Date();
    d.setDate(d.getDate() + 7);
    return Utilities.formatDate(d, Session.getScriptTimeZone(), 'yyyy-MM-dd');
  }
  const base = new Date(baseDateStr + 'T00:00:00');
  if (isNaN(base.getTime())) return '';

  // 불복 세부유형(이의신청/심사청구/심판청구/행정소송/과세적부) — 기준일(기산일)로부터 며칠
  // 이내인지가 정해져 있으므로, 말일 정렬 없이 그 일수만큼 그대로 더한다.
  if (hasDaysRule) {
    const d = new Date(base);
    d.setDate(d.getDate() + WORK_DEADLINE_DAYS_[upType]);
    return Utilities.formatDate(d, Session.getScriptTimeZone(), 'yyyy-MM-dd');
  }
  // 경정청구 — 법정신고기한(기준일)으로부터 N년이 되는 날(같은 월/일).
  if (hasYearsRule) {
    const d = new Date(base.getFullYear() + WORK_DEADLINE_YEARS_[upType], base.getMonth(), base.getDate());
    return Utilities.formatDate(d, Session.getScriptTimeZone(), 'yyyy-MM-dd');
  }
  const months = WORK_DEADLINE_MONTHS_[seMok];
  const monthEnd = new Date(base.getFullYear(), base.getMonth() + 1, 0); // 기준일이 속한 달의 말일
  const rough = work_addMonthsClamped_(monthEnd, months);
  // [2026.08 버그수정] work_addMonthsClamped_는 day-of-month를 그대로 유지하며 개월수만 더하는
  // 방식이라(예: 6/30 + 6개월 → 12/30), 도착한 달이 원래 달보다 길면 진짜 말일(12/31)이 아닌
  // 어중간한 날짜가 나오는 문제가 있었다. 실사용으로 확인된 규칙("발생일의 말일로부터 각각
  // N개월이 되는 달의 말일")대로, 도착한 달의 말일로 한 번 더 강제로 맞춘다.
  const deadline = new Date(rough.getFullYear(), rough.getMonth() + 1, 0);
  return Utilities.formatDate(deadline, Session.getScriptTimeZone(), 'yyyy-MM-dd');
}

// [2026.10.14 버그수정] 사건 시트에 행을 통째로 다시 쓸 때 날짜 칸이 7시간씩 앞당겨지던 문제 — 사건 시트의 시간대가 스크립트(서울)와
// 달라, 읽은 Date를 그대로 다시 쓰면 7시간 이른 시각으로 저장된다(수정일을 다시 읽으면 7시간 어긋나던 것과 같은 원인). 날짜만 있는 칸
// (의뢰일·기준일·법정일)은 몇 번 저장되면 하루씩 당겨졌다(실측: 같은 사건 법정일 10-31→10-29→10-28→10-27, 기준일 07-11→07-10 —
// 사건처리 점검이 작업일지를 자주 저장하면서 드러남). 쓰기 전에 Date를 서울 시각 글자로 바꾸면 시트가 같은 날짜·시각으로 읽어 들여 그대로 유지된다.
const WORK_DATE_ONLY_COLS_ = ['의뢰일', '기준일', '법정일', '완료전법정일'];
function work_rowForWrite_(col, row, sheet) {
  const tz = Session.getScriptTimeZone();
  // 날짜+시각 칸(생성일·수정일)은 UTC 시각 글자로 써야 같은 시각으로 읽힌다 — 2026-10-14 실측: 서울 시각 글자는 9시간 늦게, 시트 시간대 글자·Date는
  // 7시간 이르게 읽혔다(이 시트는 글자 시각을 UTC로 받아들임). 날짜만 있는 칸은 서울 날짜 글자로 쓰면 같은 날짜로 읽힌다(확인함).
  const sheetTz = 'Etc/UTC';
  const dateOnly = {};
  WORK_DATE_ONLY_COLS_.forEach(function (k) { if (col[k] !== undefined) dateOnly[col[k]] = true; });
  return row.map(function (v, i) {
    if (!(v instanceof Date) || isNaN(v.getTime())) return v;
    return dateOnly[i] ? Utilities.formatDate(v, tz, 'yyyy-MM-dd') : Utilities.formatDate(v, sheetTz, 'yyyy-MM-dd HH:mm:ss');
  });
}
function work_dateStr_(v) {
  if (!v) return '';
  if (v instanceof Date) return Utilities.formatDate(v, Session.getScriptTimeZone(), 'yyyy-MM-dd');
  return String(v).slice(0, 10);
}

// [2026.09.23 신규] work_readRow_와 work_computeCanonicalCaseFolderNames_(폴더명 점검 도구)가
// 똑같이 필요로 하던 "납세자↔사건개요 중 비어있는 쪽을 채운다" 로직을 한 곳으로 뽑았다 —
// 두 곳에 따로 복사해두면 한쪽만 고치고 잊어버리는 사고가 재발하기 쉽다(이번에 실제로 그런
// 사고가 날 뻔해서 여기로 합침). caseOverview는 그 자리에서 직접 고쳐 쓰고(mutate), 반환값은
// 화면에 보여줄 최종 납세자 문자열이다.
function work_resolveTaxpayer_(seMok, rawTaxpayer, caseOverview) {
  const taxpayerField = WORK_TAXPAYER_FIELD_BY_SEMOK_[seMok];
  let taxpayer = String(rawTaxpayer || '').trim();
  if (taxpayerField && caseOverview && typeof caseOverview === 'object') {
    const overviewVal = String(caseOverview[taxpayerField] || '').trim();
    if (!overviewVal && taxpayer) caseOverview[taxpayerField] = taxpayer;
    else if (overviewVal && !taxpayer) taxpayer = overviewVal;
  }
  return taxpayer;
}
function work_readRow_(col, rowValues) {
  let subtasks = [];
  try { subtasks = JSON.parse(rowValues[col.하위업무] || '[]'); } catch (e) { subtasks = []; }
  if (!Array.isArray(subtasks)) subtasks = [];
  let workLog = [];
  try { workLog = JSON.parse(rowValues[col.작업일지] || '[]'); } catch (e) { workLog = []; }
  if (!Array.isArray(workLog)) workLog = [];
  let precedents = [];
  try { precedents = JSON.parse(rowValues[col.법령예규판례] || '[]'); } catch (e) { precedents = []; }
  if (!Array.isArray(precedents)) precedents = [];
  let evidenceList = [];
  try { evidenceList = JSON.parse(rowValues[col.증빙목록] || '[]'); } catch (e) { evidenceList = []; }
  if (!Array.isArray(evidenceList)) evidenceList = [];
  let taxCalcResults = [];
  try { taxCalcResults = JSON.parse(rowValues[col.세액계산결과] || '[]'); } catch (e) { taxCalcResults = []; }
  if (!Array.isArray(taxCalcResults)) taxCalcResults = [];
  let caseOverview = {};
  try { caseOverview = JSON.parse(rowValues[col.사건개요] || '{}'); } catch (e) { caseOverview = {}; }
  if (!caseOverview || typeof caseOverview !== 'object' || Array.isArray(caseOverview)) caseOverview = {};
  // [2026.09.23 버그수정] 세무사님 지적 — 작업관리에 이미 입력된 납세자가 처리개요(사건개요)의
  // 납세의무자 이름 필드에 반영 안 되는 사건들이 있었다. 기존 동기화(work_updateCase 저장
  // 시점에 클라이언트가 양쪽을 맞춤)는 "그 이후에 다시 저장"해야만 걸리는 저장-트리거 방식이라,
  // 이미 등록된 사건은 재저장 전까지 계속 빈칸으로 남는다(게다가 '사업' 세목은 매핑 자체가
  // 최근까지 빠져 있어 저장해도 안 걸렸다 — 위 WORK_TAXPAYER_FIELD_BY_SEMOK_ 수정 참고).
  // 이 함수는 모든 화면(작업관리·처리개요·메모·세액계산·AI도구)이 사건을 읽을 때 항상 거치므로,
  // 여기서 한 번만 "둘 중 비어있는 쪽을 채워서 돌려준다"를 적용하면 과거 사건도 재저장 없이
  // 즉시 반영된다(시트 자체를 고쳐쓰지는 않음 — 다음 실제 저장 때 정식 반영).
  // [2026.09.23 추가] "전수조사" 지시로 재점검 — 처음엔 사건개요→납세자 방향만 채웠는데,
  // 반대(사건개요는 비어있고 납세자에만 값이 있는 경우)도 똑같이 안 채워지는 건 대칭이 아니다.
  // 상속처럼 "의뢰인=상속인, 납세자=피상속인"이 원래 다른 게 정상인 세목도 있으므로(workmanage.html
  // 주석 참고), 둘 다 값이 있는데 서로 다르면 절대 손대지 않는다 — 오직 한쪽이 완전히 빈 경우만 채운다.
  // [2026.09.23 재수정] 이 자기치유 로직을 work_computeCanonicalCaseFolderNames_(폴더명 점검
  // 도구)가 그대로 베껴 쓰지 않고 시트 원본만 읽고 있어서, 그 도구가 제안하는 사건명이 다른
  // 화면들이 보여주는 납세자와 어긋날 뻔했다 — work_resolveTaxpayer_로 뽑아내 두 곳이 항상
  // 같은 로직을 쓰게 한다(따로 복사해두면 또 갈라질 위험이 있으므로).
  const taxpayerForRead_ = work_resolveTaxpayer_(rowValues[col.세목], rowValues[col.납세자], caseOverview);
  return {
    id: rowValues[col.id],
    고객ID: rowValues[col.고객ID],
    // [2026.09 버그수정] "3733"처럼 숫자로만 된 고객명/납세자는 구글시트가 진짜 숫자로 저장
    // 해버릴 수 있다 — 문자열로 강제하지 않으면 화면 쪽에서 .replace() 등 문자열 메서드를
    // 호출할 때 예외가 나서, 그 사건이 목록에 섞여있는 것만으로 화면 전체(목록 재렌더링→
    // 상세보기)가 조용히 멈추는 심각한 문제로 이어졌다.
    고객명: String(rowValues[col.고객명] || ''),
    사건명: rowValues[col.사건명],
    세목: rowValues[col.세목],
    업무유형: rowValues[col.업무유형],
    담당자: rowValues[col.담당자],
    의뢰일: work_dateStr_(rowValues[col.의뢰일]),
    기준일: work_dateStr_(rowValues[col.기준일]),
    법정일: work_dateStr_(rowValues[col.법정일]),
    납세자: taxpayerForRead_,
    상태: rowValues[col.상태],
    완료전법정일: work_dateStr_(rowValues[col.완료전법정일]),
    개요: rowValues[col.개요],
    처리방향: rowValues[col.처리방향],
    처리대상: rowValues[col.처리대상],
    하위업무: subtasks,
    작업일지: workLog,
    법령예규판례: precedents,
    증빙목록: evidenceList,
    세액계산결과: taxCalcResults,
    사건개요: caseOverview,
    my_report_id: rowValues[col.my_report_id],
    폴더ID: rowValues[col.폴더ID],
    생성일: rowValues[col.생성일],
    수정일: rowValues[col.수정일]
  };
}

function work_findCaseRow_(sheet, col, caseId) {
  const data = sheet.getDataRange().getValues();
  for (let i = 1; i < data.length; i++) {
    if (String(data[i][col.id]).trim() === String(caseId).trim()) {
      return { rowIndex: i + 1, row: data[i] };
    }
  }
  return null;
}

// [2026.09] "사건분류 목록이 casehandling.html과 Code.js(WORK_EVIDENCE_TEMPLATES_) 두 곳에
// 따로 하드코딩돼 있어 한쪽만 고치면 조용히 어긋날 수 있다"는 지적 — 실제로 지금까지 어긋난
// 적은 없었지만(직접 대조 확인됨), 근본적으로 없애려면 한 곳(여기, 필요증빙 템플릿이 있는
// Code.js)만 진짜 목록을 갖고 화면은 그걸 그대로 받아쓰게 해야 한다. casehandling.html은
// 이제 이 목록 앞에 빈 선택지와 "일반OO"만 붙여서 그대로 렌더링한다.
function work_getEvidenceClassificationOptions_() {
  const options = {};
  Object.keys(WORK_EVIDENCE_TEMPLATES_).forEach(function (semok) {
    options[semok] = Object.keys(WORK_EVIDENCE_TEMPLATES_[semok].사건분류 || {});
  });
  return options;
}

function work_getCases(params) {
  const sheet = work_getSheet_();
  const data = sheet.getDataRange().getValues();
  const col = work_colMap_(data[0]);
  const cases = [];
  for (let i = 1; i < data.length; i++) {
    if (!data[i][col.id]) continue;
    cases.push(work_readRow_(col, data[i]));
  }
  return { success: true, cases: cases, evidenceClassificationOptions: work_getEvidenceClassificationOptions_() };
}

// [2026.09] 5단계 — 사건 시작 시 증빙관리(getDefaultFolder(), "고객사건" 루트)에 자동으로 폴더를
// 만든다. 이미 같은 이름 폴더가 있으면(예: 메모에서 먼저 만들어졌거나 재시도) 그대로 재사용한다.
// my.netax.kr 연결 여부와 상관없이 "제출자료"/"보고서" 하위폴더도 처음부터 같이 만들어둔다
// (my_getOrCreateSubfolder_·MY_SUBFOLDER_UPLOAD/REPORT는 my_ 모듈이 이미 쓰던 것 그대로 재사용 —
// 나중에 my.netax.kr에 연결해도 같은 이름이라 새로 안 만들고 이 폴더를 그대로 쓰게 된다).
// 실패해도(Drive 권한 등) 사건 생성 자체는 막지 않는다 — 폴더ID가 빈 채로 저장될 뿐이다.
// [2026.09] 폴더명은 이제 사건명(work_generateUniqueCaseName_이 이미 "홍길동_양도_신고"처럼
// 고객명까지 포함해 만들어준 값)을 그대로 쓴다 — 예전처럼 "고객명 + 사건명"을 다시 이어붙이면
// 고객명이 두 번 들어가는(예: "홍길동 홍길동 상속 신고") 문제가 있었다.
// [2026.09] "내부보고서" — 검토서(내부문서)와, 아직 고객에게 발행 안 한 외부보고서 초안(.md)을
// 담는 폴더. "제출자료"/"보고서"와 같은 급으로 사건 폴더 안에 두되, my.netax.kr(my_ 모듈)은
// 이 폴더의 존재 자체를 모른다 — 고객이 볼 수 있는 통로가 "보고서" 폴더 하나뿐이어야 하므로.
// [2026.09.16 변경] 세무사님 지시로 "내부보고서"/"보고서" → "보고서_내부"/"보고서_외부"로
// 개명(가나다 정렬에서도 "보고서_내부"/"보고서_외부"가 나란히 붙어 더 명확함). 기존에 이미
// 만들어져 있던 폴더들은 migrateReportFoldersAndFilenames_로 일괄 개명했다.
const WORK_SUBFOLDER_INTERNAL_REPORT = '보고서_내부';
// [2026.10.19 세무사님 지시] "문서별 pdf파일을 기본으로 하고 신고를 위한 파일은 <신고제출>이라는 폴더에 따로 복사해서 홈택스첨부기준에
// 맞춰 제출" · "신고사건의 경우 <신고제출>폴더를 만들도록 … 그리고 <확보자료>폴더도 만들어라. 거기에 시스템이 확보하는 매매실례가,
// 공동주택가격, 개별주택가격, 개별공시지가, 건물기준시가 등의 확보자료를 넣도록 하자."
//  · 이름에 꺾쇠(<>)는 넣지 않는다 — J: 드라이브(구글 드라이브 PC 동기화)는 윈도 이름 규칙이라 < > 를 못 쓴다.
//  · 신고제출 = 신고 사건(업무유형 '신고')만, 확보자료 = 폴더가 있는 모든 사건. 사건 폴더가 처음 생길 때·업무유형이 신고로 바뀔 때 만든다.
//    이미 있는 사건 폴더에는 일괄로 만들지 않는다 — 설정 🛠 「📂 신고제출·확보자료 폴더 점검」(미리 보기 → 고른 것만 만들기).
//  · 입력 규칙은 3번 판정 함수 하나로(tcIsSubmitDir_ — _신고제출만 뺌, 밑줄 없는 지난 사건의 "신고제출"은 입력 / tcIsOrigPhotoDir_·tcPdfConvDropIn_ —
//    PDF로 바뀐 원본 사진만 뺌). 확보자료는 데이터 확보 대상 — 입력이다(세무사님 "확보자료는 제외하면 안된다"). 3번(신고제출 묶음)도 이 상수를 쓴다.
// [2026.10.19 세무사님] "<신고제출>폴더도 <_신고제출>로 변경해야 하겠구나" — 밑줄 하나 + 신고제출(꺾쇠 없음). 확보자료는 말씀 없어 그대로.
const WORK_SUBFOLDER_FILING_ = '_신고제출';
const WORK_SUBFOLDER_SECURED_ = '확보자료';
function work_isFilingUpType_(upType) { return String(upType || '').trim() === '신고'; }
// 사건 폴더 안 표준 하위폴더(이미 있으면 그대로 — 새로 만든 이름만 돌려줌)
function work_ensureCaseStdSubfolders_(caseFolder, upType) {
  const made = [];
  const want = [WORK_SUBFOLDER_SECURED_].concat(work_isFilingUpType_(upType) ? [WORK_SUBFOLDER_FILING_] : []);
  want.forEach(function (n) { if (!caseFolder.getFoldersByName(n).hasNext()) { caseFolder.createFolder(n); made.push(n); } });
  return made;
}
// 사건 폴더 안 하위폴더 하나(없으면 만듦) — 3번 신고제출 묶음·확보자료 저장이 쓴다
function work_caseSubfolder_(caseFolder, name) { return my_getOrCreateSubfolder_(caseFolder, name); }

function work_getOrCreateCaseFolder_(사건명, upType) {
  try {
    const folderName = String(사건명 || '').trim();
    if (!folderName) return '';
    const root = getDefaultFolder();
    const existing = root.getFoldersByName(folderName);
    const caseFolder = existing.hasNext() ? existing.next() : root.createFolder(folderName);
    my_getOrCreateSubfolder_(caseFolder, MY_SUBFOLDER_UPLOAD);
    my_getOrCreateSubfolder_(caseFolder, MY_SUBFOLDER_REPORT);
    my_getOrCreateSubfolder_(caseFolder, WORK_SUBFOLDER_INTERNAL_REPORT);
    try { work_ensureCaseStdSubfolders_(caseFolder, upType); } catch (e) { console.log('신고제출·확보자료 폴더 만들기 실패(사건 폴더는 계속): ' + e.message); }
    return caseFolder.getId();
  } catch (err) {
    return '';
  }
}

// [2026.09 버그수정] 사건 생성 당시 Drive 오류 등으로 폴더 생성이 실패했거나, 폴더ID 컬럼이
// 생기기 전에 만들어진 옛날 사건은 c.폴더ID가 비어있다 — 이 상태로 "고객창구 연결하기"를
// 누르면(casehandling.html) my_handleAdminCreateCase가 폴더ID 없음으로 판단해 완전히 다른
// 곳(MY_ROOT_FOLDER_ID)에 새 폴더를 만들어버려서, 고객이 my.netax.kr에 올린 파일을 증빙관리·
// 작성관리가 영영 찾지 못하는 문제가 있었다. 연결하기 전에 항상 이 함수로 올바른 위치의
// 폴더(증빙관리와 같은 "고객사건" 루트 밑)를 먼저 확보하고 사건에 저장해둔다.
function work_ensureCaseFolder(params) {
  return withLock_(8000, function () {
    const sheet = work_getSheet_();
    const col = work_colMap_(sheet.getDataRange().getValues()[0]);
    const found = work_findCaseRow_(sheet, col, params.id);
    if (!found) return { success: false, message: '존재하지 않는 사건입니다.' };
    let folderId = found.row[col.폴더ID];
    if (!folderId) {
      folderId = work_getOrCreateCaseFolder_(found.row[col.사건명], found.row[col.업무유형]);
      if (!folderId) return { success: false, message: '드라이브 폴더를 만들지 못했습니다.' };
      sheet.getRange(found.rowIndex, col.폴더ID + 1).setValue(folderId);
    }
    return { success: true, folderId: folderId };
  });
}

// [2026.10.19] 이미 있는 사건 폴더의 신고제출·확보자료 — 일괄로 만들지 않고 미리 보기 → 고른 것만 만들기(설정 🛠 정비도구).
//  미리 보기: 폴더가 있는 사건마다 빠진 폴더(확보자료는 모든 사건, 신고제출은 업무유형 '신고')를 센다. 지우거나 옮기는 것은 없다.
//  사건이 많으면 4분 30초에서 멈추고 지금까지 본 것만 돌려준다(partial — 다시 누르면 처음부터).
function work_stdSubfoldersMissing_(folderId, upType) {
  const f = DriveApp.getFolderById(folderId);
  const want = [WORK_SUBFOLDER_SECURED_].concat(work_isFilingUpType_(upType) ? [WORK_SUBFOLDER_FILING_] : []);
  return { folder: f, missing: want.filter(function (n) { return !f.getFoldersByName(n).hasNext(); }) };
}
function work_planStdSubfolders(params) {
  const t0 = Date.now();
  const sheet = work_getSheet_();
  const data = sheet.getDataRange().getValues();
  const col = work_colMap_(data[0]);
  const items = [];
  let checked = 0, partial = false, broken = 0;
  for (let i = 1; i < data.length; i++) {
    const fid = String(data[i][col.폴더ID] || '').trim();
    if (!fid || !data[i][col.id]) continue;
    if (Date.now() - t0 > 270000) { partial = true; break; }
    checked++;
    try {
      const m = work_stdSubfoldersMissing_(fid, data[i][col.업무유형]);
      if (m.missing.length) items.push({ id: data[i][col.id], 사건명: data[i][col.사건명], 업무유형: data[i][col.업무유형], 상태: data[i][col.상태], missing: m.missing });
    } catch (e) { broken++; }
  }
  return { success: true, items: items, checked: checked, broken: broken, partial: partial };
}
function work_applyStdSubfolders(params) {
  const ids = Array.isArray(params.ids) ? params.ids.map(String) : [];
  if (!ids.length) return { success: false, message: '만들 사건을 고르세요.' };
  const sheet = work_getSheet_();
  const col = work_colMap_(sheet.getDataRange().getValues()[0]);
  const done = [], failed = [];
  ids.forEach(function (id) {
    const found = work_findCaseRow_(sheet, col, id);
    if (!found || !found.row[col.폴더ID]) { failed.push({ id: id, why: '사건 또는 폴더 없음' }); return; }
    try {
      const made = work_ensureCaseStdSubfolders_(DriveApp.getFolderById(found.row[col.폴더ID]), found.row[col.업무유형]);
      done.push({ id: id, 사건명: found.row[col.사건명], made: made });
    } catch (e) { failed.push({ id: id, why: String(e && e.message || e) }); }
  });
  return { success: true, done: done, failed: failed };
}

// 상담신청(예약) 때 받은 고객유형/현재세무처리상황/관련분야를 개요(진행메모) 맨 앞에
// "[예약 접수 정보]" 블록으로 얹어준다 — 해당 값이 하나도 없으면(직접 등록 등) 그냥
// 원래 개요만 반환한다.
function work_prependBookingInfo_(params) {
  const 개요 = String(params.개요 || '').trim();
  const lines = [];
  if (params.고객유형) lines.push('고객유형: ' + String(params.고객유형).trim());
  if (params.현재세무처리) lines.push('현재 세무처리: ' + String(params.현재세무처리).trim());
  if (params.관련분야) lines.push('관련 분야: ' + String(params.관련분야).trim());
  if (!lines.length) return 개요;
  const infoBlock = '[예약 접수 정보]\n' + lines.join('\n');
  return 개요 ? (infoBlock + '\n\n[상담 내용]\n' + 개요) : infoBlock;
}

// [2026.09] 사건명(= Drive 폴더명, work_getOrCreateCaseFolder_가 더 이상 "고객명 + 사건명"으로
// 중복해서 붙이지 않고 이 값을 그대로 폴더명으로 쓴다) 생성 규칙 — "홍길동_양도_신고" 형식.
// - 동명이인(다른 고객ID)이 이미 같은 이름을 쓰고 있으면 고객명 뒤에 번호(홍길동2)를 붙인다.
//   이 번호는 그 고객ID의 기존 사건에서 이미 쓰인 적이 있으면 그대로 재사용한다(한 사람은
//   항상 같은 번호로 불려야 헷갈리지 않으므로) — 그래야 동명이인끼리 폴더가 섞이지 않는다.
// - 같은 고객이 정말 똑같은 조합(세목+업무유형, 동명이인 번호까지 같음)으로 사건을 또 만들면
//   맨 뒤에 번호를 붙인다(홍길동_양도_신고2).
function work_generateUniqueCaseName_(sheet, col, 고객ID, 고객명, seMok, upType, 납세자) {
  const data = sheet.getDataRange().getValues();
  const semokLabel = WORK_SEMOK_LABELS_[seMok] || seMok;

  const escaped = 고객명.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const prefixRe = new RegExp('^' + escaped + '(\\d*)\\(');
  const custIdToNum = {};
  const numsInUse = {};
  for (let i = 1; i < data.length; i++) {
    const m = String(data[i][col.사건명] || '').match(prefixRe);
    if (!m) continue;
    const num = m[1] || '';
    const rid = data[i][col.고객ID];
    numsInUse[num] = true;
    if (rid && !Object.prototype.hasOwnProperty.call(custIdToNum, rid)) custIdToNum[rid] = num;
  }

  let nameNum;
  if (고객ID && Object.prototype.hasOwnProperty.call(custIdToNum, 고객ID)) {
    nameNum = custIdToNum[고객ID];
  } else if (!numsInUse['']) {
    nameNum = '';
  } else {
    let n = 2;
    while (numsInUse[String(n)]) n++;
    nameNum = String(n);
  }

  // [2026.09 규칙변경] 세무사님 지시: 납세자가 고객명과 같아도 생략하지 않고 항상 표시해야
  // 이름 형태가 일관되어 폴더를 직접 열어보지 않고도 목록만으로 사건을 관리할 수 있다.
  // "고객명(납세자)_세목_업무유형" 순서로 통일(이전엔 납세자가 같으면 생략하고 맨 끝에 붙였음).
  const taxpayerDisplay = 납세자 || 고객명;
  const base = 고객명 + nameNum + '(' + taxpayerDisplay + ')' + '_' + semokLabel + (upType ? '_' + upType : '');

  const taken = {};
  for (let i = 1; i < data.length; i++) {
    taken[String(data[i][col.사건명] || '').trim()] = true;
  }
  if (!taken[base]) return base;
  let n2 = 2;
  while (taken[base + n2]) n2++;
  return base + n2;
}

function work_createCase(params) {
  return withLock_(8000, function () {
    const sheet = work_getSheet_();
    const col = work_colMap_(sheet.getDataRange().getValues()[0]);

    const id = Utilities.getUuid();
    const now = new Date();
    const seMok = String(params.세목 || '').trim();
    const upType = String(params.업무유형 || '').trim();
    const 기준일 = String(params.기준일 || '').trim();
    const 고객명 = String(params.고객명 || '').trim();
    const 납세자 = String(params.납세자 || '').trim();
    // 고객ID를 직접 안 주면(화면에서 이름만 입력한 경우) 같은 이름의 고객을 고객관리에서 찾고,
    // 없으면 그 자리에서 새 고객으로 등록해서 연결한다 — 사건 등록 흐름이 예전과 똑같이
    // 이름만 입력하면 되도록 유지하면서도 자동으로 고객관리 명단이 쌓이게 하기 위함.
    const 전화 = String(params.전화 || '').trim();
    let clientMatch = null;
    const 고객ID = String(params.고객ID || '').trim() || (고객명 ? (clientMatch = client_findOrCreateByName_(고객명, 전화)).id : '');
    // [2026.09] "사건명이 애매하다"는 지적에 따라 사람이 직접 입력하지 않고 자동으로 만든다 —
    // "고객명(납세자) 세목 업무유형" (납세자가 고객명과 다를 때만 괄호 표시), 예: "홍길동(이순신) 상속 신고".
    const 사건명 = work_generateUniqueCaseName_(sheet, col, 고객ID, 고객명, seMok, upType, 납세자);

    const newRow = [];
    newRow[col.id] = id;
    newRow[col.고객ID] = 고객ID;
    newRow[col.고객명] = 고객명;
    newRow[col.사건명] = 사건명;
    newRow[col.세목] = seMok;
    newRow[col.업무유형] = upType;
    newRow[col.담당자] = String(params.담당자 || '').trim();
    newRow[col.의뢰일] = String(params.의뢰일 || '').trim();
    newRow[col.기준일] = 기준일;
    // 상담·해명자료는 법정기한이 없어 자동계산하지 않고 사용자가 입력한 처리시한을 그대로 저장한다.
    newRow[col.법정일] = WORK_MANUAL_DEADLINE_TYPES_.indexOf(upType) !== -1
      ? String(params.법정일 || '').trim()
      : work_calcDeadline_(seMok, upType, 기준일);
    newRow[col.납세자] = 납세자;
    newRow[col.상태] = params.상태 || '진행';
    // [2026.09] 상담신청(예약) 때 받은 고객유형/현재세무처리상황/관련분야가 "이 예약으로
    // 사건 시작" 시 그동안 통째로 버려지고 있었다 — 사건 컬럼을 새로 늘리는 대신, 개요
    // (진행메모) 맨 앞에 참고정보로 얹어서 최소한 사라지지 않고 눈에 보이게 한다.
    newRow[col.개요] = work_prependBookingInfo_(params);
    newRow[col.처리방향] = String(params.처리방향 || '').trim();
    newRow[col.처리대상] = String(params.처리대상 || '').trim();
    newRow[col.하위업무] = '[]';
    newRow[col.작업일지] = '[]';
    newRow[col.법령예규판례] = '[]';
    // [2026.09] "사건개요(사실관계)가 먼저 정리돼야 필요증빙도 제대로 나온다"는 지적에 따라
    // 예전처럼 사건 생성 시점에 증빙목록 템플릿을 바로 채우지 않는다 — work_updateCase가
    // 사건개요를 처음 저장할 때 채운다(work_buildEvidenceFromTemplate_ 주석 참고).
    newRow[col.증빙목록] = '[]';
    newRow[col.세액계산결과] = '[]';
    // [2026.09.16 버그수정] 실사용 지적 — 새 사건을 등록하면서 납세자를 입력했는데, 처음
    // 처리개요를 열어보면 수증자(또는 양도인·피상속인 등) 성명란이 비어있었다. 이 필드는
    // work_updateCase(사건을 "수정"할 때)만 납세자↔사건개요 양방향 동기화를 해줬는데,
    // 생성 시점엔 사건개요를 통째로 빈 객체로 시작해서 그 동기화가 아예 한 번도 안 걸렸다 —
    // 생성 시점에도 WORK_TAXPAYER_FIELD_BY_SEMOK_과 같은 규칙으로 미리 채워 넣는다.
    const taxpayerFieldForCreate_ = 납세자 && WORK_TAXPAYER_FIELD_BY_SEMOK_[seMok];
    const initialOverview_ = taxpayerFieldForCreate_ ? (function () { const o = {}; o[taxpayerFieldForCreate_] = 납세자; return o; })() : {};
    work_linkPartyClientIds_(initialOverview_, seMok);
    newRow[col.사건개요] = JSON.stringify(initialOverview_);
    // [2026.09.18 신규] "상담을 자문과 상담으로 세분 — 파일이 작성 안 돼 폴더가 필요 없는
    // 사건은 상담, 검토서·보고서가 작성되는 사건은 자문으로" — 상담 사건은 개별 Drive 폴더를
    // 만들지 않는다(폴더ID 빈 값). 이 값이 비어있으면 위쪽의 의뢰서템플릿 자동적용·아래쪽의
    // my.netax.kr 자동연결이 이미 조용히 건너뛰도록 되어 있어(둘 다 `if (newRow[col.폴더ID])`
    // 로 감싸져 있음) 별도로 더 손댈 곳이 없다 — 애초에 파일이 없는 사건이니 자연스럽다.
    newRow[col.폴더ID] = (upType === '상담') ? '' : work_getOrCreateCaseFolder_(사건명, upType);
    newRow[col.생성일] = now;
    newRow[col.수정일] = now;

    // [2026.09] 의뢰서템플릿 자동 적용 — 아래 my.netax.kr 자동연결과 마찬가지로 실패해도
    // 사건 생성 자체는 막지 않는다.
    if (newRow[col.폴더ID]) {
      try {
        const semokLabel_ = WORK_SEMOK_LABELS_[seMok] || seMok;
        // 우선순위: "양도신고"처럼 세목+업무유형을 합친 이름(가장 구체적) → "세무조사"처럼
        // 업무유형만으로 이미 고유한 이름(불복 세부유형) → 세목 이름만(마지막 안전망).
        // [2026.09.17] 의뢰서템플릿 파일명이 전부 "의뢰서_" 접두어를 쓰는 규칙으로 바뀌어
        // 후보 이름에도 똑같이 접두어를 붙여야 찾을 수 있다.
        work_seedCaseTemplateIfAny_(DriveApp.getFolderById(newRow[col.폴더ID]), [semokLabel_ + upType, upType, semokLabel_].map(function (n) { return CASE_TEMPLATE_NAME_PREFIX_ + n; }));
      } catch (err) {
        console.log('의뢰서템플릿 적용 중 오류(사건 생성은 계속 진행): ' + err.message);
      }
    }

    // [2026.09] "고객창구 연결하기"를 세무사가 나중에 수동으로 눌러야만 접속코드가 생기다 보니,
    // 그 전에 고객이 my페이지에 들어오면 안내할 코드가 아예 없어서 "상담 신청해달라"는 엉뚱한
    // 안내만 보게 되는 문제 — 사건이 생성되는 즉시 자동으로 연결해서 접속코드를 바로 발급한다.
    // 실패해도(드라이브 권한 등) 사건 생성 자체는 막지 않는다 — my_report_id가 빈 채로 저장될 뿐,
    // 처리개요의 "고객창구 연결하기"로 나중에 수동 재시도 가능.
    if (newRow[col.폴더ID]) {
      try {
        const myResult = my_handleAdminCreateCase({
          admin_code: PropertiesService.getScriptProperties().getProperty('ADMIN_CODE'),
          name: 고객명,
          case_name: 사건명,
          checklist: [],
          permission: '허용',
          folder_id: newRow[col.폴더ID]
        });
        if (myResult.success !== false && myResult.report_id) {
          newRow[col.my_report_id] = myResult.report_id;
        }
      } catch (err) {
        console.log('사건 생성 시 고객창구 자동연결 실패: ' + err.message);
      }
    }

    sheet.appendRow(newRow);
    SpreadsheetApp.flush();
    // [2026.10.09 버그수정] 시트에 쓴 날짜시각은 다시 읽으면 시트 시간대 때문에 몇 시간 어긋나고 밀리초가 잘린 값으로 돌아온다.
    // 방금 만든 new Date()를 그대로 돌려주면, 화면이 그 값을 기대수정일로 보내는 다음 저장이 시트 값과 안 맞아 매번 "다른 화면이 먼저
    // 저장했습니다" 충돌로 막혔다(세액계산 💾 저장 직후 사건개요 동기화, 증빙 연속 체크 등 — 실사용 점검에서 발견, 실제 7시간 차이).
    // 시트에 실제로 저장된 값을 다시 읽어 돌려준다(목록 조회 때와 같은 값이 되도록).
    try {
      const lastRow = sheet.getLastRow();
      if (String(sheet.getRange(lastRow, col.id + 1).getValue()) === String(newRow[col.id])) {
        newRow[col.생성일] = sheet.getRange(lastRow, col.생성일 + 1).getValue();
        newRow[col.수정일] = sheet.getRange(lastRow, col.수정일 + 1).getValue();
      }
    } catch (e) { /* 다시 읽기 실패해도 생성 결과는 그대로 돌려준다 */ }

    const caseObj = work_readRow_(col, newRow);
    const calendarOk = work_syncCaseCalendar_(caseObj);
    const result = { success: true, case: caseObj };
    if (clientMatch && clientMatch.nameConflict) {
      result.warning = '"' + 고객명 + '" 이름의 고객이 이미 있지만 전화번호가 달라 다른 사람으로 보고 새 고객으로 등록했습니다. 동명이인이 맞는지 고객관리에서 확인해주세요.';
    }
    if (!calendarOk) {
      result.calendarSyncFailed = true;
      result.warning = (result.warning ? result.warning + ' ' : '') + '캘린더 동기화에 실패했습니다 — 법정기한이 캘린더에 반영되지 않았을 수 있으니 수동으로 확인해주세요.';
    }
    return result;
  });
}

function work_updateCase(params) {
  return withLock_(8000, function () {
    const sheet = work_getSheet_();
    const col = work_colMap_(sheet.getDataRange().getValues()[0]);
    const found = work_findCaseRow_(sheet, col, params.id);
    if (!found) return { success: false, message: '존재하지 않는 사건입니다.' };

    const row = found.row;
    // [2026.09 버그수정] 동시편집 낙관적 잠금 — 작업일지/증빙목록/법령예규판례/세액계산결과처럼
    // "배열 전체를 읽어서 항목 하나 더하거나 지운 뒤 통째로 다시 저장"하는 화면들은, 두 사람이
    // (또는 같은 사람이 다른 탭에서) 거의 동시에 저장하면 나중 저장이 먼저 저장을 통째로 덮어써
    // 먼저 한 사람의 변경이 조용히 사라질 수 있다(실측 확인됨). 클라이언트가 자기가 마지막으로
    // 읽었던 수정일(params.기대수정일)을 같이 보내오면, 그 사이 다른 저장이 있었는지(수정일이
    // 달라졌는지) 확인해서 다르면 저장을 막고 최신 사건 데이터를 그대로 돌려준다 — 이 값을
    // 안 보내는 기존 호출(단순 필드 편집 등)은 지금처럼 그대로 동작한다(하위호환).
    if (params.기대수정일) {
      const actualModified = row[col.수정일] instanceof Date ? row[col.수정일].getTime() : new Date(row[col.수정일] || 0).getTime();
      const expectedModified = new Date(params.기대수정일).getTime();
      if (Number.isFinite(actualModified) && Number.isFinite(expectedModified) && actualModified !== expectedModified) {
        // [2026.09 버그수정] 충돌 시 화면을 새로고침해서 다른 사람의 저장을 지키는 것까지는
        // 맞는데, 그 과정에서 지금 사용자가 막 입력하던 내용(예: 방금 추가하려던 작업일지 한
        // 줄)도 같이 사라진다는 걸 안내하지 않아서 "분명히 입력했는데 없어졌다"는 당혹감을
        // 줄 수 있었다 — 메시지에서 명확히 알려준다.
        return { success: false, conflict: true, message: '다른 화면(또는 다른 사람)이 방금 먼저 저장해서, 지금 보고 있는 내용이 최신이 아닙니다. 화면을 최신 내용으로 새로고침했습니다 — 방금 입력하신 내용은 반영되지 않았을 수 있으니 확인 후 다시 시도해주세요.', case: work_readRow_(col, row) };
      }
    }
    // [2026.10.14] 세무사님 지시 — 의뢰인만 알던 때 만든 사건명·폴더명을, 처리 중 납세자가 확인되면 바로 "고객명(납세자)_세목_업무유형"으로.
    // 처리개요의 납세의무자 칸(양도인·수증자·피상속인)을 이번에 바꿔 저장했고, 사건 납세자가 비었거나 상속에서 고객명(의뢰인)으로 잘못 들어가 있으면 납세자도 같이 바꾼다.
    if (params.사건개요 !== undefined && params.납세자 === undefined) {
      try {
        const tf = WORK_TAXPAYER_FIELD_BY_SEMOK_[params.세목 || row[col.세목]];
        let newOv = params.사건개요; if (typeof newOv === 'string') newOv = JSON.parse(newOv || '{}');
        let oldOv = {}; try { oldOv = JSON.parse(row[col.사건개요] || '{}') || {}; } catch (e0) { oldOv = {}; }
        const nv = tf && newOv ? String(newOv[tf] || '').replace(/\([^)]*\)/g, '').trim() : '';
        const ov0 = tf ? String(oldOv[tf] || '').replace(/\([^)]*\)/g, '').trim() : '';
        const curTp = String(row[col.납세자] || '').trim(), cust = String(row[col.고객명] || '').trim();
        const wrongTp = !curTp || ((params.세목 || row[col.세목]) === 'inheritance' && curTp === cust) || curTp === ov0;
        if (nv && nv !== ov0 && nv !== curTp && wrongTp) params.납세자 = nv;
      } catch (e) { /* 납세자 동기화 실패해도 저장은 계속 */ }
    }
    const wasCompleted = row[col.상태] === '완료'; // 아래서 덮어쓰기 전에 미리 기억해둔다
    const oldSemok = row[col.세목]; // 세목이 실제로 바뀌었는지 판단하려고 덮어쓰기 전에 기억해둔다
    ['고객명', '사건명', '담당자', '상태', '납세자', '개요', '처리방향', '처리대상', 'my_report_id'].forEach(function (key) {
      if (params[key] !== undefined) row[col[key]] = String(params[key]).trim();
    });
    // 작업일지는 하위업무처럼 배열 통째로 다시 저장한다(화면에서 항목을 더하거나 지운 뒤
    // 전체 배열을 그대로 보내는 방식 — work_saveTree_와 같은 방식이라 별도 액션을 안 만들었다).
    if (params.작업일지 !== undefined) {
      let workLog = params.작업일지;
      if (typeof workLog === 'string') { try { workLog = JSON.parse(workLog); } catch (e) { workLog = null; } }
      if (Array.isArray(workLog)) row[col.작업일지] = JSON.stringify(workLog);
    }
    if (params.법령예규판례 !== undefined) {
      let precedents = params.법령예규판례;
      if (typeof precedents === 'string') { try { precedents = JSON.parse(precedents); } catch (e) { precedents = null; } }
      if (Array.isArray(precedents)) row[col.법령예규판례] = JSON.stringify(precedents);
    }
    if (params.증빙목록 !== undefined) {
      let evidenceList = params.증빙목록;
      if (typeof evidenceList === 'string') { try { evidenceList = JSON.parse(evidenceList); } catch (e) { evidenceList = null; } }
      if (Array.isArray(evidenceList)) row[col.증빙목록] = JSON.stringify(evidenceList);
    }
    if (params.세액계산결과 !== undefined) {
      let taxCalcResults = params.세액계산결과;
      if (typeof taxCalcResults === 'string') { try { taxCalcResults = JSON.parse(taxCalcResults); } catch (e) { taxCalcResults = null; } }
      if (Array.isArray(taxCalcResults)) row[col.세액계산결과] = JSON.stringify(taxCalcResults);
    }
    // [2026.09 버그수정] 예전엔 params.사건개요가 이번 호출에 실제로 실려왔을 때만 필요증빙
    // 템플릿을 재계산했다 — 그래서 작업관리에서 세목/업무유형만 바꾸고(예: "상담"→"신고")
    // 사건개요서는 다시 저장 안 하면(흔한 흐름: 수임 확정되면 업무유형만 바꿈), 새 업무유형에
    // 맞는 필요증빙이 하나도 안 채워졌다. 세목/업무유형이 바뀌는 모든 저장에서도 같이
    // 재계산하도록 조건을 넓히고, 사건개요 자체가 이번에 안 왔으면 기존 저장값을 그대로
    // 참고만 한다(overview를 새로 쓰지는 않음 — 사건개요 저장은 여전히 그 화면에서만).
    if (params.사건개요 !== undefined || params.세목 !== undefined || params.업무유형 !== undefined) {
      const overviewProvided = params.사건개요 !== undefined;
      // [2026.09 버그수정] 세목이 실제로 바뀌었는데(예: 증여→양도) 사건개요서를 이번에 새로
      // 안 보내면, 예전엔 옛 세목 때 입력했던 필드(수증자·증여자 등)가 사건개요 안에 그대로
      // 숨어있다가 나중에 세목을 다시 되돌리면(양도→증여) 마치 최신 값처럼 부활했다 — 세목
      // 분류 자체가 바뀌는 건 다른 종류의 사건이 되는 것이므로, 새로 채워지는 사건개요를
      // 명시적으로 같이 안 보낸 경우엔 옛 사건개요를 비우고 새로 시작한다.
      const semokActuallyChanged = params.세목 !== undefined && String(params.세목).trim() !== String(oldSemok || '').trim();
      const shouldWipeOverview = semokActuallyChanged && !overviewProvided;
      let oldOverviewForClassification = {};
      try { oldOverviewForClassification = JSON.parse(row[col.사건개요] || '{}'); } catch (e) { oldOverviewForClassification = {}; }
      let overview;
      if (overviewProvided) {
        overview = params.사건개요;
        if (typeof overview === 'string') { try { overview = JSON.parse(overview); } catch (e) { overview = null; } }
      } else if (shouldWipeOverview) {
        overview = {};
      } else {
        try { overview = JSON.parse(row[col.사건개요] || '{}'); } catch (e) { overview = {}; }
      }
      if (overview && typeof overview === 'object' && !Array.isArray(overview)) {
        // [2026.09] "사건개요(사실관계)가 먼저 정리돼야 필요증빙도 제대로 나온다"는 지적에
        // 따라, 필요증빙 템플릿은 사건 생성 시점이 아니라 사건개요를 저장하는 이 순간에
        // 적용한다. 처음엔 사건분류를 아직 못 정했다가(공통 항목만 채워짐) 나중에 사건분류를
        // 정해서 다시 저장하면 그때 사건분류 전용 항목이 새로 생겨야 하므로("예상가액 소급
        // 정정"과 같은 원칙 — 나중에 확실해진 정보를 반영), "완전히 비어있을 때만"이 아니라
        // 매번 템플릿을 계산해서 "라벨이 아직 없는 항목만" 추가한다. 이미 있는 항목(직접
        // 추가했든 이전에 템플릿으로 들어왔든, 확보 상태까지)은 절대 건드리지 않는다.
        let currentEvidence = [];
        try { currentEvidence = JSON.parse(row[col.증빙목록] || '[]'); } catch (e) { currentEvidence = []; }
        if (!Array.isArray(currentEvidence)) currentEvidence = [];
        const seMokForTemplate = params.세목 !== undefined ? String(params.세목).trim() : row[col.세목];
        const upTypeForTemplate = params.업무유형 !== undefined ? String(params.업무유형).trim() : row[col.업무유형];
        const templateItems = work_buildEvidenceFromTemplate_(seMokForTemplate, upTypeForTemplate, overview.사건분류, overview.물건목록, overview.취득계약일괄, overview.양도계약일괄);
        // [2026.09 버그수정] slotKey(물건 인덱스·그룹 번호 등 안정적 식별자)가 있으면 그것으로
        // 같은 슬롯을 알아보고 라벨만 최신으로 갱신한다(소재지 정정 등으로 라벨 문자열이 바뀌어도
        // 중복 생성되지 않는다) — 확보상태·비고는 그대로 유지. slotKey가 없는 옛 항목(이 수정
        // 이전에 저장됐거나 수동으로 추가한 항목)은 예전처럼 라벨 문자열로만 비교한다.
        const existingBySlotKey = {};
        currentEvidence.forEach(function (e) { if (e.slotKey) existingBySlotKey[e.slotKey] = e; });
        const existingLabels = currentEvidence.map(function (e) { return e.label; });
        let labelsChanged = false;
        const newItems = [];
        templateItems.forEach(function (item) {
          if (item.slotKey && existingBySlotKey[item.slotKey]) {
            if (existingBySlotKey[item.slotKey].label !== item.label) { existingBySlotKey[item.slotKey].label = item.label; labelsChanged = true; }
            return;
          }
          if (!item.slotKey && existingLabels.indexOf(item.label) !== -1) return;
          newItems.push(item);
        });
        if (newItems.length || labelsChanged) row[col.증빙목록] = JSON.stringify(currentEvidence.concat(newItems));
        if (overviewProvided || shouldWipeOverview) {
          work_linkPartyClientIds_(overview, seMokForTemplate);
          row[col.사건개요] = JSON.stringify(overview);
        }
      }
    }
    if (params.고객명 !== undefined) {
      const newCustomerName = row[col.고객명]; // 위 forEach에서 이미 새 이름으로 덮어써진 상태
      const linkedClientId = row[col.고객ID];
      if (!newCustomerName) {
        row[col.고객ID] = '';
      } else if (linkedClientId) {
        // [2026.09 버그수정] 이미 연결된 고객이 있는데 사건의 고객명만 고치면, 예전엔 새
        // 이름으로 다시 "이름으로 찾기"를 해서 재연결했다 — 동명이인이 있으면 완전히 다른
        // 사람의 고객 레코드로 잘못 연결될 위험이 있었다(오늘 밤 사건 폴더 이름에서 고친
        // 것과 같은 종류의 위험). 대신 원래 연결된 고객 레코드의 이름 자체를 고쳐서(오타
        // 정정 등) 같은 고객ID를 그대로 유지한다 — 고객관리 쪽 이름도 같이 맞춰진다.
        client_updateClient({ id: linkedClientId, 성명: newCustomerName });
      } else {
        row[col.고객ID] = client_findOrCreateByName_(newCustomerName).id;
      }
    }
    // [2026.09 버그수정] "필드가 이번 요청에 실려왔다" ≠ "값이 실제로 바뀌었다"인데 이 셋을
    // 혼동해서, 세목/업무유형/기준일을 매번 통째로 같이 보내는 화면(작업관리의 저장 폼)에서는
    // 값이 하나도 안 바뀌었어도 recalc가 항상 true가 됐다 — 그 결과 아래 "완료 취소 시 원래
    // 마감일 복원" 로직(!recalc가 조건)이 그 화면에서는 사실상 한 번도 작동하지 않아서,
    // 상담·해명자료처럼 마감일을 직접 입력하는 사건을 완료했다가 재오픈하면 원래 처리시한이
    // 영구히 사라지고 완료 처리한 날짜로 바뀌어버렸다. 실제로 값이 달라졌을 때만 recalc로 본다.
    let recalc = false;
    if (params.세목 !== undefined) {
      if (String(params.세목).trim() !== String(row[col.세목] || '').trim()) recalc = true;
      row[col.세목] = String(params.세목).trim();
    }
    const prevUpType = String(row[col.업무유형] || '').trim(); // [2026.10.19] 신고로 바뀌는 순간 신고제출 폴더(아래)
    if (params.업무유형 !== undefined) {
      if (String(params.업무유형).trim() !== String(row[col.업무유형] || '').trim()) recalc = true;
      row[col.업무유형] = String(params.업무유형).trim();
    }
    if (params.기준일 !== undefined) {
      if (String(params.기준일).trim() !== String(row[col.기준일] || '').trim()) recalc = true;
      row[col.기준일] = String(params.기준일).trim();
    }
    const upType = row[col.업무유형];
    // [2026.09.18 버그수정] "법정일이 이상한 날짜인데 고칠 방법이 없다"는 지적 — 예전엔 신고 등
    // 자동계산 유형은 params.법정일을 아예 무시하고 항상 기준일 기반 재계산 결과만 반영해서,
    // 기준일 자체가 잘못됐거나 계산이 어긋난 경우 직접 고칠 길이 없었다. 상담·해명자료(원래도
    // 직접입력)와 같은 원칙으로 확장 — params.법정일이 명시적으로 왔으면(=화면에서 사용자가
    // 그 칸을 실제로 고쳤을 때만 보냄, workmanage.html의 dirty-check 참고) 자동계산보다 항상
    // 우선한다. 안 보냈으면(평소 저장) 기존처럼 기준일이 바뀌었을 때만 자동계산한다.
    if (params.법정일 !== undefined) {
      row[col.법정일] = String(params.법정일).trim();
    } else if (WORK_MANUAL_DEADLINE_TYPES_.indexOf(upType) === -1 && recalc) {
      row[col.법정일] = work_calcDeadline_(row[col.세목], upType, row[col.기준일]);
    }
    // [2026.08] 완료 처리하는 순간(진행/보류→완료로 바뀔 때만, 이미 완료인 걸 다시 저장할
    // 때는 건드리지 않음) 법정일/처리시한이 아직 남은 미래 날짜라도 실제 완료일(오늘)로
    // 갱신한다 — 사용자 지적: "처리기한이 남아있는데 완료처리하면 완료일로 바뀌어야". 원래
    // 값은 완료전법정일에 백업해뒀다가, 나중에 완료를 취소하면(완료→진행/보류) 그 값을
    // 그대로 복구한다 — 단, 복구 시점에 기준일 등도 같이 바꿔서 recalc가 새로 일어났다면
    // 그 새 계산값이 우선(사용자가 그 요청에서 다른 것도 같이 바꾼 거라 더 최신 정보).
    if (params.상태 === '완료' && !wasCompleted) {
      row[col.완료전법정일] = row[col.법정일];
      // [2026.09.16 버그수정] "시스템 개통 전에 이미 끝난 사건을 지금 완료 처리했더니 완료일이
      // 오늘(개통일 무렵) 날짜로 찍혀버린다"는 지적 — 예전엔 무조건 오늘 날짜로만 덮어써서,
      // 지난 사건을 뒤늦게 기록할 방법이 없었다. 클라이언트가 실제 완료일(params.완료일)을
      // 명시적으로 보내면 그 값을 쓰고, 안 보내면(다른 호출부와의 하위호환) 예전처럼 오늘로.
      const completionDateStr = params.완료일 ? String(params.완료일).trim() : Utilities.formatDate(new Date(), Session.getScriptTimeZone(), 'yyyy-MM-dd');
      row[col.법정일] = completionDateStr;
      // [2026.09] my.netax.kr 이용기간도 이 시점(자문용역 종료일)+30일로 확정한다 — 예전엔
      // 완성된 보고서 하나 열람이 전부라 발급일+30일 고정이었지만, 이제는 사건 시작부터
      // 연결되므로 "진행 중엔 무제한, 종료되면 그 시점부터 30일"이 되어야 한다.
      try {
        const expiryBase = new Date(completionDateStr + 'T00:00:00');
        const expiryDate = isNaN(expiryBase.getTime()) ? new Date() : expiryBase;
        expiryDate.setDate(expiryDate.getDate() + 30);
        my_setExpiryByReportId_(row[col.my_report_id], expiryDate);
      } catch (err) {
        console.log('my.netax.kr 만료일 갱신 실패: ' + err.message);
      }
    } else if (wasCompleted && params.상태 !== undefined && params.상태 !== '완료') {
      if (!recalc && row[col.완료전법정일]) row[col.법정일] = row[col.완료전법정일];
      row[col.완료전법정일] = '';
      // [2026.09] 완료 취소 시 my.netax.kr 이용기간도 되돌린다 — 다시 진행 중이 되었으니 만료 없음.
      try {
        my_setExpiryByReportId_(row[col.my_report_id], null);
      } catch (err) {
        console.log('my.netax.kr 만료일 되돌리기 실패: ' + err.message);
      }
    }
    // [2026.09.16 신규] "그냥 즉시 연동되도록 하자" — 예전엔 고객명/납세자/세목/업무유형을
    // 고쳐도 사건명(=Drive 폴더명)은 그대로 남아있어서, 증빙확보의 "🏷 사건명 점검"을 따로 열어
    // 수동으로 "일괄 적용"해야만 반영됐다(그래서 작업관리 목록의 고객명(납세자) 배지 — 이건
    // 항상 실시간 필드를 보여줌 — 와 실제 사건명 문자열이 서로 다른 값을 보여주는 혼란이
    // 있었다). 이 네 필드 중 하나라도 이번 저장에 실려왔으면 사건명도 이 저장 안에서 바로
    // 다시 계산해 같이 맞춘다. work_generateUniqueCaseName_은 "새 사건 하나"를 기준으로 즉석
    // 번호를 매기는 함수라, 자기 자신의 옛 이름과 충돌하지 않도록 시트의 사건명 칸을 먼저
    // 비워두고 계산한다(normalizeAllCaseNamesAndClients_에서 쓴 것과 같은 방식). "🏷 사건명
    // 점검"은 이 경로를 안 타는 다른 방식으로 데이터가 바뀐 경우를 위한 안전망으로 그대로 둔다.
    let folderRenameFailed = false;
    if (params.고객명 !== undefined || params.납세자 !== undefined || params.세목 !== undefined || params.업무유형 !== undefined) {
      const oldCaseName = row[col.사건명];
      sheet.getRange(found.rowIndex, col.사건명 + 1).setValue('');
      const newCaseName = work_generateUniqueCaseName_(sheet, col, row[col.고객ID], row[col.고객명], row[col.세목], upType, row[col.납세자]);
      row[col.사건명] = newCaseName;
      if (newCaseName !== oldCaseName && row[col.폴더ID]) {
        // [2026.09.18 버그수정] "고객명·납세자를 바로잡아 저장했는데 폴더명은 자동수정이 안 됐다"
        // — 예전엔 실패해도 console.log로만 남겨서(Apps Script 실행 로그는 세무사님이 볼 수
        // 없음) 화면상으로는 아무 문제 없이 저장된 것처럼 보였다. 실패하면 화면에도 경고로
        // 보이게 한다(증빙확보의 "🏷 사건명 점검"으로 나중에 다시 잡아낼 수도 있지만, 저장하는
        // 그 순간 바로 알려주는 게 맞다).
        try { DriveApp.getFolderById(row[col.폴더ID]).setName(newCaseName); } catch (err) {
          console.log('사건명 변경 시 폴더명 동기화 실패: ' + err.message);
          folderRenameFailed = true;
        }
      }
      // [2026.10.09 버그수정] 사건명이 바뀌면 드라이브 폴더명은 따라 바뀌는데, 고객창구(my.netax.kr) 시트의 사건명·고객명은
      // 옛 이름 그대로 남았다(시험사건 정리 중 발견 — 고객 화면과 job의 사건명이 어긋남). 같이 맞춘다. 실패해도 저장은 계속.
      if (row[col.my_report_id] && (newCaseName !== oldCaseName || params.고객명 !== undefined)) {
        try { my_setCaseNamesByReportId_(row[col.my_report_id], newCaseName, row[col.고객명]); } catch (err) { console.log('고객창구 사건명 동기화 실패: ' + err.message); }
      }
      // [2026.10.18 탭연결 12번] 보고서 모음 목록(_보고서인덱스)의 사건명·고객명도 같이 맞춘다 — 예전엔 밤 재정리 때까지 옛 사건명으로 보였다
      // (사건 삭제 때 목록에서 바로 빼는 work_deleteCase와 같은 방식). 실패해도 저장은 계속.
      if (newCaseName !== oldCaseName || params.고객명 !== undefined) {
        try {
          const idxList = rh_loadReportIndex_();
          if (idxList) {
            let changed = false;
            idxList.forEach(function (x) {
              if (x.caseId !== params.id) return;
              if (x.사건명 !== newCaseName || x.고객명 !== row[col.고객명]) { x.사건명 = newCaseName; x.고객명 = row[col.고객명]; changed = true; }
            });
            if (changed) rh_saveReportIndex_(idxList);
          }
        } catch (err) { console.log('사건명 변경 시 보고서 목록 동기화 실패: ' + err.message); }
      }
    }
    // [2026.09.18 신규] "상담 사건이 나중에 자문/신고로 발전하면 그 시점에 개별 폴더를 만들자"
    // — 상담일 때는 폴더ID가 비어있었는데, 업무유형이 자문·신고로 바뀌면(검토서·보고서를 쓰게
    // 되면) 그 순간 개별 Drive 폴더를 새로 만든다. 반대 방향(자문·신고→상담)은 이미 파일이
    // 쌓여있을 수 있어 폴더를 지우지 않는다 — 그대로 둔다.
    if (upType !== '상담' && !row[col.폴더ID] && row[col.사건명]) {
      const newFolderId = work_getOrCreateCaseFolder_(row[col.사건명], upType);
      if (newFolderId) {
        row[col.폴더ID] = newFolderId;
        // [2026.10.18 탭연결 1번] 상담 사건에서 증빙을 올리려다 업무유형을 정해 폴더가 생긴 경우(script.html nxOpenCaseDocs_)에도
        // 처음부터 자문·신고로 만든 사건과 똑같이 고객창구(my.netax.kr)를 바로 연결한다(work_createCase와 같은 호출) — 그래야
        // 고객도 바로 자료를 올릴 수 있다. 실패해도 저장은 계속(처리개요 고객창구 카드의 [연결]로 다시 할 수 있음).
        if (!row[col.my_report_id]) {
          try {
            const myResult = my_handleAdminCreateCase({
              admin_code: PropertiesService.getScriptProperties().getProperty('ADMIN_CODE'),
              name: row[col.고객명],
              case_name: row[col.사건명],
              checklist: [],
              permission: '허용',
              folder_id: newFolderId
            });
            if (myResult.success !== false && myResult.report_id) row[col.my_report_id] = myResult.report_id;
          } catch (err) {
            console.log('상담→' + upType + ' 전환 시 고객창구 자동연결 실패: ' + err.message);
          }
        }
      }
    }
    // [2026.10.19] 폴더가 이미 있는 사건의 업무유형이 이번 저장에서 신고로 바뀌면 그때 신고제출(·확보자료) 폴더를 만든다.
    // 바뀌지 않은 저장에서는 만들지 않는다 — 이미 있는 사건 폴더는 설정 🛠 정비도구로만(미리 보기 → 고른 것만).
    if (row[col.폴더ID] && work_isFilingUpType_(upType) && prevUpType !== String(upType || '').trim()) {
      try { work_ensureCaseStdSubfolders_(DriveApp.getFolderById(row[col.폴더ID]), upType); } catch (err) { console.log('신고제출 폴더 만들기 실패(저장은 계속): ' + err.message); }
    }
    row[col.수정일] = new Date();

    sheet.getRange(found.rowIndex, 1, 1, row.length).setValues([work_rowForWrite_(col, row, sheet)]);
    SpreadsheetApp.flush();
    // [2026.10.09 버그수정] 시트에 쓴 날짜시각은 다시 읽으면 시트 시간대 때문에 몇 시간 어긋나고 밀리초가 잘린 값으로 돌아온다.
    // 방금 만든 new Date()를 그대로 돌려주면, 화면이 그 값을 기대수정일로 보내는 다음 저장이 시트 값과 안 맞아 매번 "다른 화면이 먼저
    // 저장했습니다" 충돌로 막혔다(세액계산 💾 저장 직후 사건개요 동기화, 증빙 연속 체크 등 — 실사용 점검에서 발견, 실제 7시간 차이).
    // 시트에 실제로 저장된 값을 다시 읽어 돌려준다(목록 조회 때와 같은 값이 되도록).
    row[col.수정일] = sheet.getRange(found.rowIndex, col.수정일 + 1).getValue();

    const caseObj = work_readRow_(col, row);
    const calendarOk = work_syncCaseCalendar_(caseObj);
    const result = { success: true, case: caseObj };
    const warnings = [];
    if (!calendarOk) warnings.push('캘린더 동기화에 실패했습니다 — 법정기한이 캘린더에 반영되지 않았을 수 있으니 수동으로 확인해주세요.');
    if (folderRenameFailed) warnings.push('사건명은 바뀌었지만 실제 Drive 폴더 이름은 자동으로 바꾸지 못했습니다 — 증빙확보의 "🏷 사건명 점검"에서 다시 확인해주세요.');
    if (warnings.length) {
      result.calendarSyncFailed = !calendarOk;
      result.warning = warnings.join(' ');
    }
    return result;
  });
}

function work_deleteCase(params) {
  return withLock_(8000, function () {
    const sheet = work_getSheet_();
    const col = work_colMap_(sheet.getDataRange().getValues()[0]);
    const found = work_findCaseRow_(sheet, col, params.id);
    if (!found) return { success: false, message: '존재하지 않는 사건입니다.' };
    // [2026.09] 사건을 지워도 my.netax.kr 쪽은 완전히 별개 시트라 그대로 살아있어서, 고객이
    // 삭제된 줄 모르고 계속 로그인·자료 업로드를 할 수 있었다 — 사건 삭제 = 그 접속도 끝나야
    // 하므로, 여기서도 만료일을 어제 날짜로 확정해 즉시 막는다(my_setExpiryByReportId_).
    const myReportId = found.row[col.my_report_id];
    const deletedCaseName = String(found.row[col.사건명] || '');
    sheet.deleteRow(found.rowIndex);
    // [2026.10.18 탭연결 13번] 지운 사건의 수금(자문내역) 기록은 사건ID가 죽은 값으로 남아 수금관리에서 "사건 없음"처럼 보였다 —
    // 돈 기록은 그대로 두고, 내용 끝에 "[삭제된 사건: 사건명]"을 붙인 뒤 연결만 푼다(수금관리에서 다른 사건으로 다시 연결할 수 있음).
    try {
      const logSheet = client_getSheets_().log;
      const logData = logSheet.getDataRange().getValues();
      const lh = logData[0];
      const iCase = lh.indexOf('사건ID'), iText = lh.indexOf('내용');
      if (iCase !== -1 && iText !== -1) {
        for (let r = 1; r < logData.length; r++) {
          if (String(logData[r][iCase]) !== String(params.id)) continue;
          logSheet.getRange(r + 1, iText + 1).setValue(String(logData[r][iText] || '') + ' [삭제된 사건: ' + (deletedCaseName || params.id) + ']');
          logSheet.getRange(r + 1, iCase + 1).setValue('');
        }
      }
    } catch (err) {
      console.log('사건 삭제 시 수금 기록 정리 실패: ' + err.message);
    }
    work_deleteCaseCalendarEvents_(params.id);
    // [2026.09 버그수정] 예약에서 시작된 사건을 지워도 그 예약의 연결사건ID가 안 지워져서,
    // 예약목록엔 죽은 사건을 가리키는 "🔗 사건 연결됨" 버튼이 영원히 남고, 눌러도 조용히
    // 아무 반응이 없었다(사건을 못 찾아서). 사건 삭제 시 연결된 예약이 있으면 링크를 풀어서
    // "🗂 사건 시작" 버튼이 다시 뜨게 한다.
    try {
      booking_clearCaseLink_(params.id);
    } catch (err) {
      console.log('사건 삭제 시 예약 연결 해제 실패: ' + err.message);
    }
    if (myReportId) {
      try {
        const yesterday = new Date();
        yesterday.setDate(yesterday.getDate() - 1);
        my_setExpiryByReportId_(myReportId, yesterday);
      } catch (err) {
        console.log('사건 삭제 시 my.netax.kr 접속 차단 실패: ' + err.message);
      }
    }
    // [2026.10.09 버그수정] 사건을 지워도 그 사건의 문서가 "보고서 모음" 목록(인덱스)에 밤 재정리 때까지 남아 있었다
    // (실사용 점검에서 발견 — 지운 시험사건 문서가 계속 보임). 지우는 즉시 그 사건 항목만 걷어낸다.
    try {
      const idxList = rh_loadReportIndex_();
      if (idxList) {
        const kept = idxList.filter(function (x) { return x.caseId !== params.id; });
        if (kept.length !== idxList.length) rh_saveReportIndex_(kept);
      }
    } catch (err) {
      console.log('사건 삭제 시 보고서 목록 정리 실패: ' + err.message);
    }
    return { success: true };
  });
}

// ---- 하위업무 트리 조작 (깊이 제한 없음. 실사용은 "단계→세부항목" 2단계 예상) ----
// 트리를 순회하며 id가 일치하는 노드를 찾으면 콜백(nodes, idx)을 호출한다.
function work_walkTree_(nodes, nodeId, callback) {
  for (let i = 0; i < nodes.length; i++) {
    if (String(nodes[i].id) === String(nodeId)) {
      if (callback(nodes, i)) return true;
    }
    if (Array.isArray(nodes[i].children) && work_walkTree_(nodes[i].children, nodeId, callback)) return true;
  }
  return false;
}

function work_loadTree_(row, col) {
  let tree = [];
  try { tree = JSON.parse(row[col.하위업무] || '[]'); } catch (e) { tree = []; }
  return Array.isArray(tree) ? tree : [];
}

function work_saveTree_(sheet, rowIndex, col, tree) {
  sheet.getRange(rowIndex, col.하위업무 + 1).setValue(JSON.stringify(tree));
  sheet.getRange(rowIndex, col.수정일 + 1).setValue(new Date());
  SpreadsheetApp.flush();
  return sheet.getRange(rowIndex, 1, 1, sheet.getLastColumn()).getValues()[0];
}

function work_addSubtask(params) {
  return withLock_(8000, function () {
    const sheet = work_getSheet_();
    const col = work_colMap_(sheet.getDataRange().getValues()[0]);
    const found = work_findCaseRow_(sheet, col, params.id);
    if (!found) return { success: false, message: '존재하지 않는 사건입니다.' };

    const tree = work_loadTree_(found.row, col);
    const newNode = {
      id: Utilities.getUuid(),
      title: String(params.title || '').trim(),
      status: '대기',
      assignee: String(params.assignee || '').trim(),
      dueDate: String(params.dueDate || '').trim(),
      children: []
    };
    if (!newNode.title) return { success: false, message: '항목 이름을 입력해주세요.' };

    if (params.parentId) {
      let added = false;
      work_walkTree_(tree, params.parentId, function (nodes, idx) {
        if (!Array.isArray(nodes[idx].children)) nodes[idx].children = [];
        nodes[idx].children.push(newNode);
        added = true;
        return true;
      });
      if (!added) return { success: false, message: '상위 항목을 찾을 수 없습니다.' };
    } else {
      tree.push(newNode);
    }

    const updatedRow = work_saveTree_(sheet, found.rowIndex, col, tree);
    const caseObj = work_readRow_(col, updatedRow);
    const calendarOk = work_syncCaseCalendar_(caseObj);
    const result = { success: true, case: caseObj };
    if (!calendarOk) {
      result.calendarSyncFailed = true;
      result.warning = '캘린더 동기화에 실패했습니다 — 마감일이 캘린더에 반영되지 않았을 수 있으니 수동으로 확인해주세요.';
    }
    return result;
  });
}

function work_updateSubtask(params) {
  return withLock_(8000, function () {
    const sheet = work_getSheet_();
    const col = work_colMap_(sheet.getDataRange().getValues()[0]);
    const found = work_findCaseRow_(sheet, col, params.id);
    if (!found) return { success: false, message: '존재하지 않는 사건입니다.' };

    const tree = work_loadTree_(found.row, col);
    let updated = false;
    work_walkTree_(tree, params.nodeId, function (nodes, idx) {
      ['title', 'status', 'assignee', 'dueDate'].forEach(function (key) {
        if (params[key] !== undefined) nodes[idx][key] = params[key];
      });
      updated = true;
      return true;
    });
    if (!updated) return { success: false, message: '하위업무를 찾을 수 없습니다.' };

    const updatedRow = work_saveTree_(sheet, found.rowIndex, col, tree);
    const caseObj = work_readRow_(col, updatedRow);
    const calendarOk = work_syncCaseCalendar_(caseObj);
    const result = { success: true, case: caseObj };
    if (!calendarOk) {
      result.calendarSyncFailed = true;
      result.warning = '캘린더 동기화에 실패했습니다 — 마감일이 캘린더에 반영되지 않았을 수 있으니 수동으로 확인해주세요.';
    }
    return result;
  });
}

function work_deleteSubtask(params) {
  return withLock_(8000, function () {
    const sheet = work_getSheet_();
    const col = work_colMap_(sheet.getDataRange().getValues()[0]);
    const found = work_findCaseRow_(sheet, col, params.id);
    if (!found) return { success: false, message: '존재하지 않는 사건입니다.' };

    const tree = work_loadTree_(found.row, col);
    function removeFrom(nodes) {
      for (let i = 0; i < nodes.length; i++) {
        if (String(nodes[i].id) === String(params.nodeId)) { nodes.splice(i, 1); return true; }
        if (Array.isArray(nodes[i].children) && removeFrom(nodes[i].children)) return true;
      }
      return false;
    }
    if (!removeFrom(tree)) return { success: false, message: '하위업무를 찾을 수 없습니다.' };

    const updatedRow = work_saveTree_(sheet, found.rowIndex, col, tree);
    const caseObj = work_readRow_(col, updatedRow);
    const calendarOk = work_syncCaseCalendar_(caseObj);
    const result = { success: true, case: caseObj };
    if (!calendarOk) {
      result.calendarSyncFailed = true;
      result.warning = '캘린더 동기화에 실패했습니다 — 마감일이 캘린더에 반영되지 않았을 수 있으니 수동으로 확인해주세요.';
    }
    return result;
  });
}

// ---- 구글캘린더 동기화 (syncCalendarForPath_ 패턴 응용, Code.js:3790 참고) ----
// 이 사건 태그가 붙은 기존 일정을 전부 지우고, 법정일 + 마감일 있는 하위업무를 종일 일정으로
// 다시 만든다. 매번 통째로 재생성하는 방식이라 항목을 지우거나 날짜를 바꿔도 항상 정확히 따라온다.
// [2026.09 버그수정] 캘린더 권한이 취소되거나 일시 오류가 나도 이 함수가 예외를 조용히
// 삼켜서, 사건은 "저장했습니다"로 뜨는데 법정기한이 캘린더에 하나도 안 올라가는 상황이
// 화면 어디에도 안 보였다(이 앱의 핵심 가치가 "법정기한을 놓치지 않는 것"이라 위험도가
// 크다) — 성공 여부를 반환해서 호출부가 사용자에게 경고할 수 있게 한다.
function work_syncCaseCalendar_(caseObj) {
  try {
    const cal = CalendarApp.getDefaultCalendar();
    const tag = '[NX:work:' + caseObj.id + ']';
    work_deleteEventsByTag_(cal, tag);

    // [2026.09] 사건명 자체가 이미 고객명을 포함하므로("홍길동_양도_신고") 따로 붙이지 않는다.
    // [2026.09 버그수정] "보류" 상태 사건도 진행 사건과 똑같은 제목으로 캘린더에 떠서 구분이
    // 안 됐다 — 완전히 지우지는 않는다(보류 중에도 진짜 법정기한은 그대로 다가오므로, 잊고
    // 넘기면 더 위험함), 대신 제목에 [보류] 표시를 붙여 한눈에 구분되게 한다.
    const holdPrefix = caseObj.상태 === '보류' ? '[보류] ' : '';
    const label = holdPrefix + (caseObj.사건명 || caseObj.고객명 || '');
    if (caseObj.법정일) {
      work_createAllDayEvent_(cal, '[NX] ' + label + ' — 법정기한', caseObj.법정일, tag);
    }
    (caseObj.하위업무 || []).forEach(function visit(node) {
      if (node.dueDate) {
        work_createAllDayEvent_(cal, '[NX] ' + label + ' — ' + String(node.title || '').slice(0, 60), node.dueDate, tag);
      }
      (node.children || []).forEach(visit);
    });
    (caseObj.작업일지 || []).forEach(function (entry) {
      if (entry.dueDate) {
        work_createAllDayEvent_(cal, '[NX] ' + label + ' — 다음할일: ' + String(entry.text || '').slice(0, 50), entry.dueDate, tag);
      }
    });
    return true;
  } catch (err) {
    // 캘린더 접근 권한이 없거나 오류가 나도 사건/하위업무 저장 자체는 계속 진행돼야 함
    console.log('사건 캘린더 동기화 실패(' + (caseObj && caseObj.id) + '): ' + err.message);
    return false;
  }
}

function work_deleteCaseCalendarEvents_(caseId) {
  try {
    const cal = CalendarApp.getDefaultCalendar();
    work_deleteEventsByTag_(cal, '[NX:work:' + caseId + ']');
  } catch (err) { }
}

function work_deleteEventsByTag_(cal, tag) {
  const searchStart = new Date(); searchStart.setFullYear(searchStart.getFullYear() - 1);
  const searchEnd = new Date(); searchEnd.setFullYear(searchEnd.getFullYear() + WORK_CALENDAR_SEARCH_HORIZON_YEARS_);
  cal.getEvents(searchStart, searchEnd, { search: tag }).forEach(function (ev) {
    try { ev.deleteEvent(); } catch (e) { }
  });
}

function work_createAllDayEvent_(cal, title, dateStr, tag) {
  try {
    const d = new Date(dateStr + 'T00:00:00');
    if (isNaN(d.getTime())) return;
    cal.createAllDayEvent(title, d, { description: tag });
  } catch (e) { }
}

function work_doPost(body) {
  switch (body.action) {
    case 'work_get_cases': return work_getCases(body);
    case 'work_create_case': return work_createCase(body);
    case 'work_update_case': return work_updateCase(body);
    case 'work_delete_case': return work_deleteCase(body);
    case 'work_add_subtask': return work_addSubtask(body);
    case 'work_update_subtask': return work_updateSubtask(body);
    case 'work_delete_subtask': return work_deleteSubtask(body);
    case 'send_my_portal_sms': return work_sendMyPortalSms(body);
    case 'get_case_subfolders': return work_getCaseSubfolders(body);
    case 'ensure_case_folder': return work_ensureCaseFolder(body);
    case 'work_audit_case_folder_names': return work_auditCaseFolderNames(body);
    case 'work_audit_unlinked_case_folders': return work_auditUnlinkedCaseFoldersAction_(body);
    case 'work_plan_std_subfolders': return work_planStdSubfolders(body); // [2026.10.19] 신고제출·확보자료 폴더 점검(미리 보기)
    case 'work_apply_std_subfolders': return work_applyStdSubfolders(body); // 고른 사건만 만들기
    case 'work_link_case_folder': return work_linkCaseFolder(body);
    case 'work_reassign_case_folder': return work_reassignCaseFolder(body);
    case 'work_fix_completion_after_receipt': return work_fixCompletionAfterReceipt(body);
    case 'work_backfill_receipt_case_links': return work_backfillReceiptCaseLinksAction_(body);
    case 'work_plan_report_filename_cleanup': return work_reportFilenameCleanupAction_(body);
    case 'work_apply_report_filename_cleanup': return work_applyReportFilenameCleanup(body);
    case 'migrate_report_template_names': return handleMigrateReportTemplateNames_(body);
    case 'work_resync_all_calendars': return work_resyncAllCalendars();
    case 'work_apply_receipt_only_case_cleanup': return work_applyReceiptOnlyCaseCleanup(body);
    case 'work_backfill_party_client_ids': return work_backfillPartyClientIds(body);
    default: return { success: false, message: '알 수 없는 action: ' + body.action };
  }
}

// [2026.09] "폴더명 규칙(work_generateUniqueCaseName_ 참고 — 고객명[동명이인번호](납세자)_세목
// _업무유형)을 제대로 안 지키고 있는 것 같다"는 지적 — 실제로 사건명(=Drive 폴더명)은 사건
// 생성 시점에 딱 한 번만 이 규칙대로 만들어지고, 그 뒤 고객명 정정·세목 변경 등이 있어도
// "자동으로 안 바뀌는 기존 정책"(work_updateCase의 고객명 동기화 주석 참고) 때문에 사건명·
// 폴더명은 예전 상태 그대로 남는다 — 시간이 지날수록 실제 규칙과 어긋나는 폴더가 쌓인다.
// 전체 사건을 훑어 "지금 값 기준으로 새로 이름을 만들면 어떻게 되는지" 다시 계산해서 실제
// 저장된 사건명과 다른 것만 골라낸다. 원래 규칙(work_generateUniqueCaseName_)은 "새 사건 하나"
// 기준으로 즉석에서 번호를 매기는 함수라 그대로 재사용하면 전체를 훑을 때마다 서로 다른 번호가
// 나올 수 있어(현재 사건명 자체가 이미 예전 번호를 차지하고 있으므로), 생성일 순으로 전체를
// 다시 훑으며 번호를 처음부터 새로 배정한다(가장 먼저 만들어진 사건이 번호 없는 이름을
// 차지하는 우선순위는 기존 정책과 동일하게 유지).
function work_computeCanonicalCaseFolderNames_() {
  const sheet = work_getSheet_();
  const col = work_colMap_(sheet.getDataRange().getValues()[0]);
  const data = sheet.getDataRange().getValues();
  const rows = [];
  for (let i = 1; i < data.length; i++) rows.push({ rowIndex: i + 1, row: data[i] });
  rows.sort(function (a, b) {
    const da = a.row[col.생성일] ? new Date(a.row[col.생성일]).getTime() : 0;
    const db = b.row[col.생성일] ? new Date(b.row[col.생성일]).getTime() : 0;
    return da - db;
  });
  const custIdToNum = {};
  const numsInUseByName = {};
  const takenFullNames = {};
  const results = [];
  rows.forEach(function (r) {
    const row = r.row;
    const 고객명 = String(row[col.고객명] || '').trim();
    if (!고객명) return; // 고객명이 아예 없는(테스트/불완전) 사건은 대상에서 제외
    const 고객ID = row[col.고객ID];
    const seMok = row[col.세목];
    const upType = row[col.업무유형];
    // [2026.09.23 버그수정] 시트의 납세자 칸만 보면 work_readRow_의 자기치유(사건개요에만
    // 값이 있고 납세자 칸은 비어있는 경우)를 놓쳐서, 이 도구가 제안하는 사건명이 다른 화면이
    // 보여주는 납세자와 어긋날 수 있었다 — work_resolveTaxpayer_로 동일하게 판정.
    let caseOverviewForName_ = {};
    try { caseOverviewForName_ = JSON.parse(row[col.사건개요] || '{}'); } catch (e) { caseOverviewForName_ = {}; }
    if (!caseOverviewForName_ || typeof caseOverviewForName_ !== 'object' || Array.isArray(caseOverviewForName_)) caseOverviewForName_ = {};
    const 납세자 = work_resolveTaxpayer_(seMok, row[col.납세자], caseOverviewForName_);
    const semokLabel = WORK_SEMOK_LABELS_[seMok] || seMok;

    if (!numsInUseByName[고객명]) numsInUseByName[고객명] = {};
    let nameNum;
    if (고객ID && Object.prototype.hasOwnProperty.call(custIdToNum, 고객ID)) {
      nameNum = custIdToNum[고객ID];
    } else if (!numsInUseByName[고객명]['']) {
      nameNum = '';
    } else {
      let n = 2;
      while (numsInUseByName[고객명][String(n)]) n++;
      nameNum = String(n);
    }
    numsInUseByName[고객명][nameNum] = true;
    if (고객ID) custIdToNum[고객ID] = nameNum;

    // [2026.09.16 버그수정] 이 함수가 2026.09 초에 만들어진 뒤 명명규칙이 "납세자가 고객명과
    // 같으면 괄호 생략, 맨 끝에 붙임"(고객명_세목_업무유형(납세자))에서 "항상 표시, 고객명 바로
    // 뒤"(고객명(납세자)_세목_업무유형)로 바뀌었는데(work_generateUniqueCaseName_ 참고) 이 함수는
    // 갱신이 안 돼 옛 규칙으로 "제안"을 계산하고 있었다 — 그대로 "일괄 적용"했다면 이미 규칙대로
    // 된 사건까지 옛 형식으로 되돌리는 대형 오류가 날 뻔했다. work_generateUniqueCaseName_과
    // 완전히 같은 공식으로 맞춘다.
    const taxpayerDisplay = 납세자 || 고객명;
    const base = 고객명 + nameNum + '(' + taxpayerDisplay + ')' + '_' + semokLabel + (upType ? '_' + upType : '');
    let finalName = base;
    if (takenFullNames[finalName]) {
      let n2 = 2;
      while (takenFullNames[base + n2]) n2++;
      finalName = base + n2;
    }
    takenFullNames[finalName] = true;

    const currentName = String(row[col.사건명] || '').trim();
    // [2026.09.18 버그수정] "고객명·납세자를 고쳐서 저장했는데 폴더명은 자동수정이 안 됐다" —
    // 이 함수는 원래 시트에 저장된 사건명 문자열끼리만 비교해서, 사건명은 이미 규칙대로인데
    // 실제 Drive 폴더 이름만 따로 뒤처진 경우(work_updateCase의 자동동기화가 폴더 이름변경만
    // 조용히 실패했을 때 등)는 전혀 잡아내지 못하는 사각지대가 있었다. 폴더가 연결돼 있으면
    // 그 폴더의 실제 이름도 같이 확인해서, 시트 문자열은 맞아도 폴더만 어긋난 경우까지 잡는다.
    const 폴더ID = String(row[col.폴더ID] || '').trim();
    let liveFolderMismatch = false;
    if (폴더ID) {
      try {
        if (DriveApp.getFolderById(폴더ID).getName() !== finalName) liveFolderMismatch = true;
      } catch (err) {
        // 폴더를 못 찾으면(삭제됨·권한 문제 등) 이 검사는 건너뛰고 사건명 문자열 비교만 본다.
      }
    }
    if (currentName !== finalName || liveFolderMismatch) {
      results.push({
        rowIndex: r.rowIndex, id: row[col.id], 고객명: 고객명,
        현재사건명: currentName, 제안사건명: finalName, 폴더ID: 폴더ID,
        // [2026.09.23 신규] apply 단계가 work_updateCase를 그대로 태우려면 이 두 값이 필요하다
        // (낙관적 잠금용 수정일, 재계산을 트리거할 납세자 — 아래 work_auditCaseFolderNames 참고).
        납세자: 납세자, 수정일: row[col.수정일]
      });
    }
  });
  return results;
}

// dryRun(기본값)은 저장소를 전혀 건드리지 않고 무엇이 바뀔지만 보여준다. apply:true일 때만
// 실제로 사건명을 바꾼다.
// [2026.09.23 버그수정, "전수조사" 지시로 발견] 예전엔 시트 셀과 Drive 폴더명을 여기서 직접
// setValue/setName으로 고쳤다 — work_updateCase를 거치지 않아 (1) 낙관적 잠금 검사가 전혀
// 없어 다른 화면에서 동시에 저장 중이던 내용을 조용히 덮어쓸 수 있었고, (2) work_syncCaseCalendar_
// 가 안 불려서 일괄변경 후 구글 캘린더의 "[NX] 옛 사건명" 이벤트가 안 갱신된 채 남을 수 있었다.
// work_updateCase는 이미 "고객명/납세자/세목/업무유형 중 하나라도 들어오면 사건명 재계산+
// 폴더명 동기화+캘린더 동기화를 한 번에 다 해주므로(2026.09.16 로직, 위 함수 근처 주석 참고)
// 그 경로를 그대로 태운다 — 이 함수 자신은 lock을 잡지 않는다(work_updateCase가 매 건마다
// 자기 lock을 잡으므로, 여기서 또 감싸면 같은 실행 안에서 lock을 중첩 요청하게 된다).
function work_auditCaseFolderNames(params) {
  const diffs = work_computeCanonicalCaseFolderNames_();
  if (!params || !params.apply) {
    return { success: true, dryRun: true, count: diffs.length, items: diffs };
  }
  const applied = [];
  const failed = [];
  diffs.forEach(function (d) {
    const res = work_updateCase({ id: d.id, 납세자: d.납세자, 기대수정일: d.수정일 });
    if (res && res.success) {
      applied.push({ 고객명: d.고객명, 현재사건명: d.현재사건명, 제안사건명: (res.case && res.case.사건명) || d.제안사건명, 폴더수정됨: !(res.warning && res.warning.indexOf('폴더') !== -1) });
    } else {
      failed.push({ 고객명: d.고객명, 현재사건명: d.현재사건명, 사유: (res && (res.message || res.error)) || '알 수 없는 오류' });
    }
  });
  return { success: true, applied: applied.length, items: applied, failed: failed };
}

// [2026.09.19 정비도구 재정비] "완료일 일괄 보정"(시스템 개통 무렵 잘못 찍힌 완료일 보정)
// 도구는 그 개통 시점이 다시 올 수 없어 영구적으로 대상이 없는 상태라 삭제했다. 다만 그
// 도구가 남긴 캘린더 재동기화 헬퍼(work_resyncCalendarForRows_)는 다른 완료일 보정 도구
// (완료일-영수증일 보정)가 계속 쓰므로 그대로 둔다.
// [2026.09.18 버그수정] "일정에 [NX] 표시가 붙은 데이터가 왜곡된 것으로 보인다" — 이 파일의
// 완료일 일괄보정 도구 네 개가 전부 work_updateCase를 거치지 않고 시트 셀을 직접 덮어써서,
// work_updateCase 안에만 있던 캘린더 동기화(work_syncCaseCalendar_)가 한 번도 안 걸렸다.
// 사건 데이터(법정일)는 고쳐졌는데 구글 캘린더의 "[NX] ... — 법정기한" 일정은 옛날 값 그대로
// 남아있었던 것 — 데이터와 캘린더가 서로 어긋나 보인 진짜 원인. 네 도구 모두 적용 직후 이
// 헬퍼로 영향받은 행만 다시 동기화한다.
function work_resyncCalendarForRows_(rowIndices) {
  if (!rowIndices || !rowIndices.length) return;
  const sheet = work_getSheet_();
  const data = sheet.getDataRange().getValues();
  const col = work_colMap_(data[0]);
  rowIndices.forEach(function (rowIndex) {
    const rowValues = data[rowIndex - 1];
    if (!rowValues) return;
    try { work_syncCaseCalendar_(work_readRow_(col, rowValues)); } catch (err) { /* 캘린더 동기화 실패해도 사건 자체 수정은 이미 끝났다 */ }
  });
}
// [2026.09.18 신규] 위 버그가 고쳐지기 전(오늘 이 배포 이전)에 이미 네 도구로 완료일을
// 고쳤던 사건들은, 시트 값은 맞는데 캘린더만 옛날 값으로 남아있다 — 그리고 각 도구는 이제
// "현재값===새값이면 다시 안 보여줌"이므로, 이미 시트가 맞아버린 그 사건들은 도구를 다시
// 눌러도 더 이상 목록에 안 나와 자동으로는 재동기화가 안 된다. 오늘 하루의 잔여 왜곡을
// 한 번에 바로잡는 전체 재동기화 도구.
function work_resyncAllCalendars() {
  return withLock_(30000, function () {
    const sheet = work_getSheet_();
    const data = sheet.getDataRange().getValues();
    const col = work_colMap_(data[0]);
    let synced = 0, failed = 0;
    for (let i = 1; i < data.length; i++) {
      if (!data[i][col.id]) continue;
      try {
        if (work_syncCaseCalendar_(work_readRow_(col, data[i]))) synced++; else failed++;
      } catch (err) { failed++; }
    }
    return { success: true, synced: synced, failed: failed };
  });
}

// [2026.09.18 신규, 1회성] "상담을 자문/상담으로 세분"한 뒤 — 기존 사건 중에도 알고 보면
// "파일이 현금영수증 하나뿐이라 사실은 상담이었어야 했던" 사건들이 있다는 지적. 사건 폴더를
// 전수조사해서, 폴더 안(하위폴더 포함)에 "현금영수증"이 들어간 파일만 있고 다른 파일이 전혀
// 없는 경우를 찾아 그 파일을 "<고객명>_현금영수증"으로 이름 바꿔 "상담사건" 공용 폴더로
// 옮기고, 그 사건 폴더는 휴지통으로 보낸 뒤(완전삭제 아님, 되돌릴 수 있음) 그 사건 자체도
// 업무유형을 '상담'으로 맞춘다(사건명도 새 업무유형 기준으로 다시 계산). "상담사건" 폴더에
// 이미 같은 이름의 파일이 있으면(같은 고객이 상담을 여러 번 한 경우 등) 자동으로 겹쳐쓰지
// 않고 "확인 필요" 목록으로만 보여준다. 폴더 안에 관련파일이 아예 0개(현금영수증조차 없는
// 완전히 빈 폴더)인 사건도 같은 이유(작성된 서류가 없다=상담)로 대상에 포함 — 이 경우 옮길
// 파일이 없으므로 폴더만 휴지통으로 보내고 업무유형만 상담으로 정리한다.
function work_collectAllFilesRecursive_(folder, out) {
  const fi = folder.getFiles();
  while (fi.hasNext()) out.push(fi.next());
  const si = folder.getFolders();
  while (si.hasNext()) work_collectAllFilesRecursive_(si.next(), out);
}
function work_findReceiptOnlyCaseFolders_() {
  const sheet = work_getSheet_();
  const data = sheet.getDataRange().getValues();
  const col = work_colMap_(data[0]);
  const ready = [], needsReview = [];
  let consultFolder = null;
  try { consultFolder = getConsultSharedFolder_(); } catch (err) { /* 아래서 폴더 없이도 이름충돌 검사만 건너뛰고 계속 진행 */ }
  const takenNames = {};
  if (consultFolder) {
    const it = consultFolder.getFiles();
    while (it.hasNext()) takenNames[it.next().getName()] = true;
  }
  for (let i = 1; i < data.length; i++) {
    const folderId = String(data[i][col.폴더ID] || '').trim();
    if (!folderId) continue;
    let folder;
    try { folder = DriveApp.getFolderById(folderId); } catch (err) { continue; }
    const allFiles = [];
    try { work_collectAllFilesRecursive_(folder, allFiles); } catch (err) { continue; }
    const receiptFiles = allFiles.filter(function (f) { return f.getName().indexOf('현금영수증') !== -1; });
    const otherFiles = allFiles.filter(function (f) { return f.getName().indexOf('현금영수증') === -1; });
    if (allFiles.length && (!receiptFiles.length || otherFiles.length)) continue; // 파일이 있는데 현금영수증뿐이 아니면 대상 아님
    // 완전히 빈 폴더(관련파일 0건)는 '완료' 상태인 사건만 대상 — 아직 서류 작성 전인
    // 진행중 신규 사건까지 휩쓸려 폴더가 휴지통으로 가는 것을 막기 위한 안전장치.
    if (!allFiles.length && String(data[i][col.상태] || '') !== '완료') continue;
    const 고객명 = String(data[i][col.고객명] || '').trim();
    const fileMoves = [];
    let hasCollision = false;
    receiptFiles.forEach(function (f, idx) {
      const extMatch = f.getName().match(/\.[a-zA-Z0-9]+$/);
      const ext = extMatch ? extMatch[0] : '';
      const newName = 고객명 + '_현금영수증' + (receiptFiles.length > 1 ? '_' + (idx + 1) : '') + ext;
      if (takenNames[newName]) hasCollision = true;
      fileMoves.push({ fileId: f.getId(), oldName: f.getName(), newName: newName });
    });
    const rec = { rowIndex: i + 1, caseId: data[i][col.id], 고객명: 고객명, 사건명: data[i][col.사건명], 업무유형현재: data[i][col.업무유형], folderId: folderId, fileMoves: fileMoves, emptyFolder: allFiles.length === 0 };
    if (hasCollision) {
      needsReview.push(rec);
    } else {
      fileMoves.forEach(function (fm) { takenNames[fm.newName] = true; }); // 같은 배치 안에서도 중복 방지
      ready.push(rec);
    }
  }
  return { ready: ready, needsReview: needsReview };
}
function work_applyReceiptOnlyCaseCleanup(params) {
  return withLock_(60000, function () {
    const found = work_findReceiptOnlyCaseFolders_();
    if (!params.apply) return { success: true, dryRun: true, ready: found.ready, needsReview: found.needsReview };
    const consultFolder = getConsultSharedFolder_();
    if (!consultFolder) return { success: false, message: '"상담사건" 폴더를 만들 수 없습니다.' };
    const sheet = work_getSheet_();
    const col = work_colMap_(sheet.getDataRange().getValues()[0]);
    let applied = 0, failed = 0;
    const log = [];
    found.ready.forEach(function (rec) {
      try {
        rec.fileMoves.forEach(function (fm) {
          const f = DriveApp.getFileById(fm.fileId);
          f.setName(fm.newName);
          consultFolder.addFile(f);
          const parents = f.getParents();
          while (parents.hasNext()) {
            const p = parents.next();
            if (p.getId() !== consultFolder.getId()) p.removeFile(f);
          }
        });
        try { DriveApp.getFolderById(rec.folderId).setTrashed(true); } catch (err) { /* 이미 없어졌을 수 있음 — 무시 */ }
        const row = sheet.getRange(rec.rowIndex, 1, 1, sheet.getLastColumn()).getValues()[0];
        row[col.폴더ID] = '';
        row[col.업무유형] = '상담';
        sheet.getRange(rec.rowIndex, col.사건명 + 1).setValue(''); // 자기 자신의 옛 이름과 안 겹치게 먼저 비움
        const newCaseName = work_generateUniqueCaseName_(sheet, col, row[col.고객ID], row[col.고객명], row[col.세목], '상담', row[col.납세자]);
        row[col.사건명] = newCaseName;
        row[col.수정일] = new Date();
        sheet.getRange(rec.rowIndex, 1, 1, row.length).setValues([work_rowForWrite_(col, row, sheet)]);
        applied++;
        log.push('"' + rec.사건명 + '" → 상담으로 정리' + (rec.fileMoves.length ? (', 현금영수증 ' + rec.fileMoves.length + '건을 상담사건 폴더로 이동') : ' (관련파일 0건, 빈 폴더만 정리)'));
      } catch (err) {
        failed++;
        log.push('"' + rec.사건명 + '" 처리 실패: ' + err.message);
      }
    });
    SpreadsheetApp.flush();
    work_resyncCalendarForRows_(found.ready.map(function (r) { return r.rowIndex; }));
    return { success: true, applied: applied, failed: failed, log: log };
  });
}

// [2026.09.19 정비도구 재정비] "완료일-보고서작성일 보정"과 "신고파일 작성일 반영" 도구는
// 전부 삭제했다 — 전자는 위(이미 삭제된) "완료일 일괄 보정"이 임시로 찍어둔 2026-06-30을
// 재조정하는 후속 작업이라 짝이 없어지면서 같이 끝난 일이고, 후자는 2026.09.18에 세무사님이
// 딱 한 번 화면 캡처로 알려준 실제 고객 14명의 이름+날짜가 코드에 그대로 박혀 있던
// 일회성 수기 반영 도구였다(개인정보를 코드에 남겨둘 이유가 없어 완전히 제거).

// [2026.09.17 재설계] "현금영수증이 고객에만 연결되다니 말이 안 된다 — 사건에 먼저 연결되고
// 나서 고객에 연결되어야 한다"는 지적으로 findCaseForFile_/runCashReceiptScan_의 실제 버그를
// 발견·수정(이미 알고 있던 사건ID를 그냥 안 넘기고 있었을 뿐, 애초에 특정 불가능한 게
// 아니었다) — 이제부터 새로 스캔되는 현금영수증은 사건ID가 정확히 채워진다. 이 함수는
// **사건ID로 직접 연결된 영수증을 최우선**으로 쓰고, 사건ID가 아직 없는 옛 기록(위 수정
// 이전 것, 또는 사건ID가 없는 홈택스 매출내역 가져오기 등)만 "그 고객이 사건을 하나뿐
// 가진 경우"에 한해 보완적으로 쓴다(여러 사건 가진 고객의 사건ID 없는 영수증은 여전히
// 어느 사건 것인지 특정 불가 — "확인 필요" 목록으로).
function work_findCompletionAfterReceipt_() {
  const workSheet = work_getSheet_();
  const wdata = workSheet.getDataRange().getValues();
  const wcol = work_colMap_(wdata[0]);
  const sheets = client_getSheets_();
  const ldata = sheets.log.getDataRange().getValues();
  const lcol = client_colMap_(ldata[0], CONSULT_HEADERS);

  const caseCountByClient = {};
  for (let i = 1; i < wdata.length; i++) {
    const cid = String(wdata[i][wcol.고객ID] || '').trim();
    if (cid) caseCountByClient[cid] = (caseCountByClient[cid] || 0) + 1;
  }
  const latestReceiptByCase = {};
  const latestReceiptByClient = {};
  for (let i = 1; i < ldata.length; i++) {
    if (String(ldata[i][lcol.수취증빙] || '').trim() !== '현금영수증') continue;
    const d = work_dateStr_(ldata[i][lcol.날짜]);
    if (!d) continue;
    const caseId = String(ldata[i][lcol.사건ID] || '').trim();
    if (caseId) {
      if (!latestReceiptByCase[caseId] || d > latestReceiptByCase[caseId]) latestReceiptByCase[caseId] = d;
      continue;
    }
    const cid = String(ldata[i][lcol.고객ID] || '').trim();
    if (!cid) continue;
    if (!latestReceiptByClient[cid] || d > latestReceiptByClient[cid]) latestReceiptByClient[cid] = d;
  }

  const items = [], ambiguous = [];
  for (let i = 1; i < wdata.length; i++) {
    if (String(wdata[i][wcol.상태] || '').trim() !== '완료') continue;
    const caseId = String(wdata[i][wcol.id] || '').trim();
    const cid = String(wdata[i][wcol.고객ID] || '').trim();
    const curDate = work_dateStr_(wdata[i][wcol.법정일]);
    if (!curDate) continue;
    let receiptDate = latestReceiptByCase[caseId];
    let viaCase = true;
    if (!receiptDate) {
      viaCase = false;
      if (cid && caseCountByClient[cid] === 1) receiptDate = latestReceiptByClient[cid];
    }
    if (!receiptDate || curDate <= receiptDate) continue;
    const row = { rowIndex: i + 1, id: wdata[i][wcol.id], 고객명: wdata[i][wcol.고객명], 사건명: wdata[i][wcol.사건명], 현재완료일: curDate, 영수증발행일: receiptDate };
    if (viaCase || caseCountByClient[cid] === 1) items.push(row); else ambiguous.push(row);
  }
  return { items: items, ambiguous: ambiguous };
}
// [2026.09.17 신규] runCashReceiptScan_ 수정 이전에 이미 쌓인 기존 자문내역 중, "현금영수증
// 파일 자동 인식(파일명)" 형태로 기록됐지만 사건ID가 비어있는 것들을 찾아, 내용에 남아있는
// 파일명으로 그 파일을 다시 찾아(findCaseForFile_) 사건ID·고객ID를 뒤늦게 채운다. 수동으로
// 입력한 기록(이 문구가 없는 것)은 건드리지 않는다.
function work_backfillReceiptCaseLinks_() {
  const sheets = client_getSheets_();
  const logSheet = sheets.log;
  const ldata = logSheet.getDataRange().getValues();
  const lcol = client_colMap_(ldata[0], CONSULT_HEADERS);
  let updated = 0, notFound = 0;
  for (let i = 1; i < ldata.length; i++) {
    if (String(ldata[i][lcol.사건ID] || '').trim()) continue;
    const content = String(ldata[i][lcol.내용] || '');
    const m = content.match(/현금영수증 파일 자동 인식\(([^)]+)\)/);
    if (!m) continue;
    const fileName = m[1];
    try {
      const iter = DriveApp.getFilesByName(fileName);
      let matched = null;
      while (iter.hasNext()) {
        const f = iter.next();
        const caseInfo = findCaseForFile_(f.getId());
        if (caseInfo) { matched = caseInfo; break; }
      }
      if (matched) {
        logSheet.getRange(i + 1, lcol.사건ID + 1).setValue(matched.caseId);
        if (matched.고객ID && !String(ldata[i][lcol.고객ID] || '').trim()) {
          logSheet.getRange(i + 1, lcol.고객ID + 1).setValue(matched.고객ID);
        }
        updated++;
      } else {
        notFound++;
      }
    } catch (err) {
      notFound++;
    }
  }
  return { updated: updated, notFound: notFound };
}
function work_backfillReceiptCaseLinksAction_(body) {
  return work_backfillReceiptCaseLinks_();
}
function work_fixCompletionAfterReceipt(params) {
  return withLock_(15000, function () {
    const found = work_findCompletionAfterReceipt_();
    if (!params.apply) return { success: true, dryRun: true, count: found.items.length, items: found.items, ambiguousCount: found.ambiguous.length, ambiguous: found.ambiguous };
    const sheet = work_getSheet_();
    const col = work_colMap_(sheet.getDataRange().getValues()[0]);
    found.items.forEach(function (it) {
      sheet.getRange(it.rowIndex, col.법정일 + 1).setValue(it.영수증발행일);
    });
    work_resyncCalendarForRows_(found.items.map(function (it) { return it.rowIndex; }));
    return { success: true, applied: found.items.length };
  });
}

// [2026.09.16 신규] "고객E(고객E 피상속인)_상속_상담 사건은 폴더가 있는데 연결되지 않아서 없는 것으로
// 나온다"는 지적으로 발견 — 폴더ID가 비어있는 사건은 work_auditCaseFolderNames에서 "폴더 없음
// (사건명만 수정)"으로만 표시되는데, 실제로는 폴더 자체는 있고 시트에 연결(폴더ID)만 안 된
// 경우가 섞여있다(2026-09-12 흡수 작업 때 빠졌거나, 상담 단계로 폴더 없이 등록된 사건에
// 나중에 누군가 수동으로 폴더를 만든 경우 등). work_getOrCreateCaseFolder_처럼 "현재 사건명과
// 정확히 같은 이름의 폴더"만 찾으면, 이름 규칙이 여러 번 바뀌는 동안 폴더 자체는 옛 이름
// 그대로일 수 있어 못 찾고 새 빈 폴더를 만들어버릴 위험이 있다(실제 자료가 있는 폴더와
// 분리됨) — 그래서 고객명 기준 느슨한 매칭으로 "후보"만 찾아 사람이 확인 후 연결하게 한다.
function work_auditUnlinkedCaseFolders_() {
  const root = getDefaultFolder();
  const sheet = work_getSheet_();
  const data = sheet.getDataRange().getValues();
  const col = work_colMap_(data[0]);
  const registered = {};
  for (let i = 1; i < data.length; i++) {
    const fid = String(data[i][col.폴더ID] || '').trim();
    if (fid) registered[fid] = true;
  }
  const unlinkedRows = [];
  for (let i = 1; i < data.length; i++) {
    const 사건명 = String(data[i][col.사건명] || '').trim();
    const 고객명 = String(data[i][col.고객명] || '').trim();
    const 폴더ID = String(data[i][col.폴더ID] || '').trim();
    if (!사건명 || 폴더ID) continue;
    unlinkedRows.push({ id: data[i][col.id], 사건명: 사건명, 고객명: 고객명 });
  }
  if (!unlinkedRows.length) return { count: 0, items: [] };

  const candidateFolders = []; // 이미 등록되지 않은 폴더만 후보가 될 수 있음
  const iter = root.getFolders();
  while (iter.hasNext()) {
    const f = iter.next();
    if (registered[f.getId()]) continue;
    if (work_isSpecialRootFolder_(f.getName())) continue;
    candidateFolders.push({ id: f.getId(), name: f.getName(), createdDate: Utilities.formatDate(f.getDateCreated(), 'Asia/Seoul', 'yyyy-MM-dd') });
  }

  const items = unlinkedRows.map(function (row) {
    const candidates = row.고객명
      ? candidateFolders.filter(function (f) { return f.name.indexOf(row.고객명) !== -1; })
      : [];
    return { id: row.id, 사건명: row.사건명, 고객명: row.고객명, candidates: candidates };
  });
  return { count: items.length, items: items };
}
function work_auditUnlinkedCaseFoldersAction_(body) {
  const result = work_auditUnlinkedCaseFolders_();
  return { success: true, dryRun: true, count: result.count, items: result.items };
}
// 후보 목록에서 세무사님이 직접 고른 폴더 하나를 그 사건에 연결한다(폴더/사건명 자체는 안
// 바꾸고 폴더ID만 채움 — 이름이 다르면 위 "🏷 폴더명 점검"으로 별도 정리).
function work_linkCaseFolder(params) {
  return withLock_(8000, function () {
    const caseId = String(params.caseId || '').trim();
    // [2026.09.16 신규] 자동 후보 검색(work_auditUnlinkedCaseFolders_, 최상위 폴더+고객명
    // 부분일치만 봄)이 못 찾는 경우 — 하위 폴더에 있거나 이름이 다른 경우 — 를 위해, 폴더
    // 링크나 ID를 사람이 직접 붙여넣어도 연결되도록 sanitizeDriveId_로 정규화한다.
    const folderId = sanitizeDriveId_(String(params.folderId || '').trim());
    if (!caseId || !folderId) return { success: false, message: 'caseId 또는 folderId가 없습니다.' };
    const sheet = work_getSheet_();
    const data = sheet.getDataRange().getValues();
    const col = work_colMap_(data[0]);
    const found = work_findCaseRow_(sheet, col, caseId);
    if (!found) return { success: false, message: '존재하지 않는 사건입니다.' };
    if (String(found.row[col.폴더ID] || '').trim()) return { success: false, message: '이미 폴더가 연결된 사건입니다.' };
    for (let i = 1; i < data.length; i++) {
      if (String(data[i][col.폴더ID] || '').trim() === folderId) {
        // [2026.09.16 신규] "잘못 부여된 사건명" 중복 등록(고객명·납세자가 뒤바뀌었거나 정정
        // 전 이름 그대로 남은 옛 사건이 진짜 폴더를 이미 차지한 경우)을 화면에서 바로 정리할
        // 수 있게, 어느 사건과 충돌하는지 id도 같이 내려준다(work_reassignCaseFolder에서 사용).
        return { success: false, message: '이 폴더는 이미 다른 사건(' + data[i][col.사건명] + ')에 연결되어 있습니다.', conflictCaseId: data[i][col.id], conflictCaseName: data[i][col.사건명] };
      }
    }
    try { DriveApp.getFolderById(folderId); } catch (err) { return { success: false, message: '폴더를 찾을 수 없습니다: ' + err.message }; }
    sheet.getRange(found.rowIndex, col.폴더ID + 1).setValue(folderId);
    return { success: true };
  });
}

// [2026.09.16 신규] "고객F(고객F)/고객E 피상속인(고객E)는 잘못 부여된 사건명이니까 수정된 사건명으로
// 연결해주고 잘못된 사건명은 삭제해달라" — 옛날에 정정 전 이름(또는 고객명·납세자가 뒤바뀐
// 이름)으로 등록된 사건이 실제 Drive 폴더를 이미 차지하고 있고, 정정된 사건명의 새 사건 행은
// 폴더가 없는 상태로 따로 존재하는 경우를 한 번에 정리한다: 폴더를 옛 사건에서 떼어 새 사건에
// 옮기고, 옛 사건 행 자체를 삭제한다. 고객명 자체를 고쳐 재사용하지 않는 이유 — 옛 사건의
// 고객ID가 실제로 다른 진짜 고객 레코드를 가리키고 있을 수 있어(예: "고객E 피상속인"가 별도 실존
// 고객일 가능성), 고객명을 덮어쓰면 그 고객 레코드까지 오염될 위험이 있다. 행을 통째로
// 지우면 CLIENTS 시트는 전혀 건드리지 않아 안전하다.
function work_reassignCaseFolder(params) {
  return withLock_(10000, function () {
    const fromCaseId = String(params.fromCaseId || '').trim();
    const toCaseId = String(params.toCaseId || '').trim();
    if (!fromCaseId || !toCaseId) return { success: false, message: 'fromCaseId 또는 toCaseId가 없습니다.' };
    const sheet = work_getSheet_();
    const data = sheet.getDataRange().getValues();
    const col = work_colMap_(data[0]);
    const fromFound = work_findCaseRow_(sheet, col, fromCaseId);
    const toFound = work_findCaseRow_(sheet, col, toCaseId);
    if (!fromFound || !toFound) return { success: false, message: '사건을 찾을 수 없습니다.' };
    const folderId = String(fromFound.row[col.폴더ID] || '').trim();
    if (!folderId) return { success: false, message: '옛 사건에 연결된 폴더가 없습니다.' };
    if (String(toFound.row[col.폴더ID] || '').trim()) return { success: false, message: '새 사건에는 이미 폴더가 연결되어 있습니다.' };
    sheet.getRange(toFound.rowIndex, col.폴더ID + 1).setValue(folderId);
    sheet.deleteRow(fromFound.rowIndex);
    return { success: true, folderId: folderId };
  });
}

// [2026.09] "내부보고서"/"보고서" 폴더 ID를 이름 기반 경로탐색(listFolder) 없이 사건ID로
// 직접·안전하게 얻는다 — 이 두 서브폴더는 find-or-create이므로, 이 세션 이전에 만들어진
// 옛날 사건(아직 "내부보고서" 폴더가 없음)이어도 이 호출 한 번으로 자동으로 만들어지고,
// 이름이 바뀌었거나 하는 것과 무관하게 항상 정확한 폴더를 가리킨다.
function work_getCaseSubfolders(params) {
  const caseId = String(params.caseId || '').trim();
  if (!caseId) return { error: 'caseId가 없습니다.' };
  const sheet = work_getSheet_();
  const data = sheet.getDataRange().getValues();
  const col = work_colMap_(data[0]);
  let folderId = '';
  for (let i = 1; i < data.length; i++) {
    if (data[i][col.id] === caseId) { folderId = data[i][col.폴더ID]; break; }
  }
  // [2026.10.18 탭연결 1번] 상담 사건은 일부러 폴더를 만들지 않는다 — 막다른 오류 대신 할 일을 알려주고, 화면은 noFolder를 보고 업무유형 묻기를 띄운다
  if (!folderId) return { error: '이 사건은 아직 드라이브 폴더가 없습니다(상담 사건은 폴더를 만들지 않습니다) — 업무유형을 자문·신고 등으로 정하면 폴더가 생깁니다.', noFolder: true };
  try {
    const caseFolder = DriveApp.getFolderById(folderId);
    const internalFolder = my_getOrCreateSubfolder_(caseFolder, WORK_SUBFOLDER_INTERNAL_REPORT);
    const reportFolder = my_getOrCreateSubfolder_(caseFolder, MY_SUBFOLDER_REPORT);
    // [2026.09 신규] 사건 폴더 "루트" 자체의 id도 같이 내려준다 — memo.html의 고객폴더 저장
    // 기능(writeMemoEntry_)이 만드는 "OOO사건.md" 등은 내부보고서/보고서 하위폴더가 아니라
    // 이 루트에 바로 생기는데, 지금까지 문서작성 화면이 이 루트를 전혀 훑지 않아서 이미
    // 존재하는 그 파일들을 열 방법이 없었다(rwRenderCaseReports_에서 이 값으로 루트도 같이 조회).
    return { success: true, internalFolderId: internalFolder.getId(), reportFolderId: reportFolder.getId(), caseFolderId: folderId };
  } catch (err) {
    return { error: '폴더 조회 중 오류: ' + err.message };
  }
}

// [2026.09] 5단계 — my.netax.kr 주소+접속코드를 고객 휴대폰으로 문자 발송. 전화번호는
// 클라이언트로 절대 내려주지 않고 서버 안에서만 조회·발송한다(work_ 사건엔 전화번호가 없어
// 고객관리(client_)에서 고객ID로 찾는다).
function work_sendMyPortalSms(params) {
  const caseId = String(params.caseId || '').trim();
  if (!caseId) return { success: false, message: 'caseId가 필요합니다.' };

  const sheet = work_getSheet_();
  const col = work_colMap_(sheet.getDataRange().getValues()[0]);
  const found = work_findCaseRow_(sheet, col, caseId);
  if (!found) return { success: false, message: '사건을 찾을 수 없습니다.' };
  const caseObj = work_readRow_(col, found.row);
  if (!caseObj.my_report_id) return { success: false, message: '아직 고객창구에 연결되지 않았습니다.' };

  let phone = '';
  const 고객ID = String(caseObj.고객ID || '').trim();
  if (고객ID) {
    const sheets = client_getSheets_();
    const data = sheets.clients.getDataRange().getValues();
    const ccol = client_colMap_(data[0], CLIENT_HEADERS);
    for (let i = 1; i < data.length; i++) {
      if (String(data[i][ccol.id]).trim() === 고객ID) { phone = String(data[i][ccol.전화번호] || '').trim(); break; }
    }
  }
  if (!phone) return { success: false, message: '연락처를 찾을 수 없습니다(고객관리에 전화번호를 등록해주세요).' };

  // [2026.09] 링크에 report_id를 쿼리로 넣어두면 고객창구(NETAX/my/index.html)이 접속코드
  // 입력칸을 자동으로 채워준다 — 고객이 직접 타이핑하지 않아도 됨.
  // my.netax.kr을 홈페이지(netax.kr/my/)로 흡수 — 고객이 이미 아는 홈페이지 주소 하나로
  // 안내하기 위함(전자명함·상담신청과 같은 nav 버튼으로도 들어올 수 있게 됨).
  const message = '이음세무컨설팅 고객창구을 안내드립니다.\nhttps://netax.kr/my/?report_id=' + caseObj.my_report_id;
  const smsResult = booking_sendSMS(phone, message);
  if (!smsResult || smsResult.success === false) {
    return { success: false, message: '문자 발송에 실패했습니다' + (smsResult && smsResult.message ? ': ' + smsResult.message : '') + '. 고객이 안내를 못 받았을 수 있으니 직접 전달해주세요.' };
  }
  return { success: true };
}

// ---- AI 채팅(넥스) 도구 연동 — DRIVE_TOOLS의 list_work_cases 등에서 호출됨 ----
// AI는 사건의 내부 id(UUID)를 모르므로, caseId가 없으면 고객명/사건명(부분일치, 없으면 지금
// 보고 있는 폴더의 경로)으로 사건 하나를 찾아준다. 여러 건이 걸리면 에러로 후보 목록을 돌려줘서
// AI가 사용자에게 다시 물어보게 한다.
function work_resolveCase_(input, contextPath) {
  const sheet = work_getSheet_();
  const data = sheet.getDataRange().getValues();
  const col = work_colMap_(data[0]);
  const rows = [];
  for (let i = 1; i < data.length; i++) {
    if (data[i][col.id]) rows.push({ row: data[i], rowIndex: i + 1 });
  }

  if (input.caseId) {
    const m = rows.find(function (x) { return String(x.row[col.id]).trim() === String(input.caseId).trim(); });
    if (!m) return { error: '해당 id의 사건을 작업관리에서 찾을 수 없습니다.' };
    return { sheet: sheet, col: col, row: m.row, rowIndex: m.rowIndex };
  }

  const customer = String(input.customerName || (contextPath && contextPath[0]) || '').trim();
  const caseName = String(input.caseName || (contextPath && contextPath[1]) || '').trim();
  if (!customer && !caseName) return { error: '어느 사건인지 특정할 수 없습니다. 고객명 또는 사건명을 알려주세요.' };

  const matches = rows.filter(function (x) {
    const c = String(x.row[col.고객명] || '').trim();
    const n = String(x.row[col.사건명] || '').trim();
    return (!customer || c.indexOf(customer) !== -1) && (!caseName || n.indexOf(caseName) !== -1);
  });
  if (matches.length === 0) return { error: '조건에 맞는 사건을 작업관리에서 찾지 못했습니다. list_work_cases로 먼저 확인해보세요.' };
  if (matches.length > 1) {
    return {
      error: '조건에 맞는 사건이 ' + matches.length + '건입니다. 어느 것인지 사용자에게 확인해주세요.',
      candidates: matches.map(function (x) { return { id: x.row[col.id], 고객명: x.row[col.고객명], 사건명: x.row[col.사건명] }; })
    };
  }
  return { sheet: sheet, col: col, row: matches[0].row, rowIndex: matches[0].rowIndex };
}

// 트리에서 title이 (부분)일치하는 첫 노드를 찾는다 — AI는 노드의 내부 id를 모르므로 이름으로 찾음.
function work_walkTitleSearch_(nodes, title, cb) {
  for (let i = 0; i < nodes.length; i++) {
    const t = String(nodes[i].title || '').trim();
    if (t === String(title).trim() || t.indexOf(title) !== -1) { cb(nodes[i]); return true; }
    if (Array.isArray(nodes[i].children) && work_walkTitleSearch_(nodes[i].children, title, cb)) return true;
  }
  return false;
}

function toolListWorkCases(status, customerName) {
  const res = work_getCases({});
  let cases = res.cases || [];
  if (status) cases = cases.filter(function (c) { return c.상태 === status; });
  if (customerName) cases = cases.filter(function (c) { return (c.고객명 || '').indexOf(customerName) !== -1; });
  return {
    success: true,
    cases: cases.map(function (c) {
      let total = 0, done = 0;
      (function walk(nodes) {
        (nodes || []).forEach(function (n) { total++; if (n.status === '완료') done++; walk(n.children); });
      })(c.하위업무);
      return {
        id: c.id, 고객명: c.고객명, 사건명: c.사건명, 세목: c.세목, 담당자: c.담당자,
        기준일: c.기준일, 법정일: c.법정일, 상태: c.상태,
        하위업무진행: total ? (done + '/' + total) : '없음'
      };
    })
  };
}

function toolCreateWorkCase(input, contextPath) {
  const 고객명 = String(input.customerName || (contextPath && contextPath[0]) || '').trim();
  const 사건명 = String(input.caseName || (contextPath && contextPath[1]) || '').trim();
  if (!고객명 || !사건명) return { error: '고객명과 사건명이 필요합니다. 사용자에게 확인해주세요.' };
  return work_createCase({
    고객명: 고객명, 사건명: 사건명, 세목: input.taxType,
    담당자: input.assignee, 의뢰일: input.requestDate, 기준일: input.baseDate
  });
}

function toolUpdateWorkCaseStatus(input, contextPath) {
  const resolved = work_resolveCase_(input, contextPath);
  if (resolved.error) return resolved;
  return work_updateCase({ id: resolved.row[resolved.col.id], 상태: input.status });
}

function toolAddWorkSubtask(input, contextPath) {
  const resolved = work_resolveCase_(input, contextPath);
  if (resolved.error) return resolved;

  let parentId = null;
  if (input.parentTitle) {
    const tree = work_loadTree_(resolved.row, resolved.col);
    let found = null;
    work_walkTitleSearch_(tree, input.parentTitle, function (node) { found = node; });
    if (!found) return { error: '"' + input.parentTitle + '" 이름의 상위 항목을 찾을 수 없습니다.' };
    parentId = found.id;
  }

  return work_addSubtask({
    id: resolved.row[resolved.col.id], parentId: parentId,
    title: input.title, dueDate: input.dueDate, assignee: input.assignee
  });
}

function toolUpdateWorkSubtaskStatus(input, contextPath) {
  const resolved = work_resolveCase_(input, contextPath);
  if (resolved.error) return resolved;

  const tree = work_loadTree_(resolved.row, resolved.col);
  let found = null;
  work_walkTitleSearch_(tree, input.title, function (node) { found = node; });
  if (!found) return { error: '"' + input.title + '" 이름의 하위업무를 찾을 수 없습니다.' };

  return work_updateSubtask({ id: resolved.row[resolved.col.id], nodeId: found.id, status: input.status });
}

function toolDeleteWorkCase(input, contextPath) {
  const resolved = work_resolveCase_(input, contextPath);
  if (resolved.error) return resolved;
  return work_deleteCase({ id: resolved.row[resolved.col.id] });
}

// [2026.10.06 신규, 재검토114] 세무대리인 정보 — 단일 테넌트(세무사 본인 정보라 전체 앱에
// 딱 1세트만 존재) 설정값이라 별도 시트 없이 스크립트 속성에 저장한다(API 키 등 기존 전역
// 설정값과 같은 방식). taxcalc.html의 모든 인쇄서식·전자신고파일 생성, settings.html의
// "세무대리인 정보" 입력화면 양쪽에서 이 두 함수만 호출한다.
// [2026.10.20 전자신고 대조] taxAgentBirth(세무대리인 생년월일 — 양도 HEADER 27, 관리번호와 둘 중 하나 필수)·hometaxUserId(홈택스 사용자ID — 세 세목 HEADER 10·12) 추가.
//  세무대리 대표자 주민등록번호는 민감 정보라 저장하지 않는다(화면이 파일 만들 때만 받고 지움).
const TAX_AGENT_SETTINGS_KEYS_ = ['taxAgentName', 'taxAgentBizNo', 'taxAgentMgmtNo', 'taxAgentPhone', 'taxAgentBirth', 'hometaxUserId'];
function getTaxAgentSettings_() {
  const props = PropertiesService.getScriptProperties();
  const result = {};
  TAX_AGENT_SETTINGS_KEYS_.forEach(function (key) {
    result[key] = props.getProperty('TAX_AGENT_' + key) || '';
  });
  return result;
}
function saveTaxAgentSettings_(body) {
  const props = PropertiesService.getScriptProperties();
  TAX_AGENT_SETTINGS_KEYS_.forEach(function (key) {
    if (body[key] !== undefined) props.setProperty('TAX_AGENT_' + key, String(body[key]).trim());
  });
  return { success: true };
}

function jsonResponse(obj) {
  return ContentService
    .createTextOutput(JSON.stringify(obj))
    .setMimeType(ContentService.MimeType.JSON);
}

// [2026.10.09] 구글 드라이브 무료 글자인식(OCR) — 이미지·PDF를 구글 문서로 복사하면 드라이브가 글자를 읽어준다.
// AI 비용 0원. 임시 문서는 읽자마자 휴지통으로 보낸다.
// [2026.10.16] 변환용 임시 사본을 둘 곳 — 업무관리자 "_글자인식기억" 폴더(실행이 끊겨 못 지워도 고객 사건 폴더에 남지 않게). 못 찾으면 빈 값(예전처럼 원본 옆).
function tcTmpMeta_(meta) { try { const fo = tcOcrStoreFolder_(); if (fo) meta.parents = [fo.getId()]; } catch (e) {} return meta; }
function ocrFileText_(fileId, tblKey) {
  // [2026.10.16] 임시 문서는 고객 사건 폴더가 아니라 업무관리자 "_글자인식기억" 폴더에 만든다 — 실행 시간 초과로 지우기 전에 끊기면
  //  고객 폴더에 "_ocr_tmp_….gdoc"가 남았다(고객X 사건). 기억 폴더를 못 찾으면 예전처럼 원본 옆에.
  let copy = null;
  try { copy = Drive.Files.copy(tcTmpMeta_({ name: '_ocr_tmp_' + Date.now(), mimeType: 'application/vnd.google-apps.document' }), fileId, { ocrLanguage: 'ko', fields: 'id' }); }
  catch (e0) {
    // [2026.10.19 3번 읽기 — 확보율 재측정 "읽기 실패"] 드라이브 글자인식이 거절한 파일:
    //  ① 너무 큰 사진(13MB 휴대폰 사진 "Request Too Large" — 고객Q 고객Q 관계인1.jpg)·변환 안 되는 그림 형식(webp) → 드라이브가 만든 축소본(2400px)으로 읽음(일괄 안에서만)
    //  ② 암호 걸린 PDF("Bad Request" — 고객AG 사망보험금 지급증명서는 비밀번호 없이는 안 열림) → 이유를 알아볼 수 있게 바꿔 던짐(비밀번호를 풀어 다시 받아야 함)
    const em = String(e0 && e0.message || e0);
    let mt0 = ''; try { mt0 = String(DriveApp.getFileById(fileId).getMimeType() || ''); } catch (e1) {}
    if (TC_BATCH_READ_ && /^image\//.test(mt0) && /Too Large|not supported|conversion/i.test(em)) {
      const th = tcThumbBytes_(fileId, 2400), tb2 = [];
      for (let k = 0; k < th.length; k++) tb2.push(th[k] > 127 ? th[k] - 256 : th[k]);
      return String(tcOcrBlob_(Utilities.newBlob(tb2, th[0] === 0x89 ? 'image/png' : 'image/jpeg', 'img')) || '');
    }
    if (/pdf/.test(mt0) && /Bad Request/i.test(em)) {
      let enc = false; try { const s0 = DriveApp.getFileById(fileId).getBlob().getDataAsString('ISO-8859-1'); enc = /\/Encrypt\s/.test(s0.slice(-4000)) || /\/Encrypt\s/.test(s0.slice(0, 4000)); } catch (e2) {}
      if (enc) throw new Error('암호 걸린 PDF — 비밀번호를 풀어 다시 올려 주셔야 읽을 수 있음(' + em.slice(0, 60) + ')');
    }
    throw e0;
  }
  try {
    const body = DocumentApp.openById(copy.id).getBody();
    // [2026.10.18 3번 세션 실험③] 드라이브는 글자층 PDF·워드를 바꿀 때 표(TABLE)를 만든다 — getText()는 칸마다 줄을 바꿔 줄·칸 연결이 사라진다
    //  (고객A 임대명세서: 층·호·면적·상호·사업자번호·보증금·월세가 한 줄씩 흩어짐). 같은 변환에서 칸 자리 지킨 표 글도 기억(ocrtbl1_)에 남긴다.
    //  메모 글(getText)은 그대로라 기존 정리 규칙 영향 없음. 칸 자리가 필요한 쪽은 tcDocTableText_로 받는다
    if (tblKey) { try { const tb = tcDocTableAware_(body); tcOcrStorePut_(tblKey, tb.tables ? tb.text : ''); } catch (e) {} }
    const got = body.getText();
    // [2026.10.19 3번 읽기 — 확보율 재측정] 글자가 모양(그림)으로만 찍힌 PDF — "Microsoft Print to PDF"로 저장한 웹 화면(국세법령정보 예규 등)은 글꼴은 있는데
    //  글자 표가 깨져 드라이브가 그 깨진 글자층을 그대로 써서 0자가 된다(개발용 22개 — 고객BD 관련예규 9·고객I 5·고객AF 4). 서버는 PDF를 그림으로 못 그리므로
    //  드라이브가 만든 첫 쪽 그림(축소본 2400px)을 글자인식(0원)한다 — 첫 쪽만이라 표시를 붙임. 일괄 안에서만(사이드바는 느려지지 않게)
    //  쪽당 글자로 본다 — 깨진 글자층에서 몇십 자만 건지는 것(고객AD 질의회신 20여 개, 2~5쪽에 46~120자)도 같은 경우라 쪽당 30자 미만이면
    const gotN = String(got || '').replace(/[^가-힣0-9]/g, '').length;
    let lowPdf = false;
    if (TC_BATCH_READ_ && gotN < 150) {
      try {
        const df0 = DriveApp.getFileById(fileId);
        if (/pdf/.test(String(df0.getMimeType() || ''))) { const np = (df0.getBlob().getDataAsString('ISO-8859-1').match(/\/Type\s*\/Page(?![s\w])/g) || []).length || 1; lowPdf = gotN < 30 || gotN / np < 30; }
      } catch (e) {}
    }
    if (lowPdf) {
      try {
        {
          const th = tcThumbBytes_(fileId, 2400), tb2 = [];
          for (let k = 0; k < th.length; k++) tb2.push(th[k] > 127 ? th[k] - 256 : th[k]);
          const tt = String(tcOcrBlob_(Utilities.newBlob(tb2, th[0] === 0x89 ? 'image/png' : 'image/jpeg', 'p1')) || '').trim();
          if (tt.replace(/[^가-힣0-9]/g, '').length >= 30) return String(got || '') + '\n[1쪽 — 글자가 그림 모양으로만 찍힌 PDF라 드라이브가 그린 첫 쪽 그림으로 읽음, 뒷쪽은 못 읽음]\n' + tt;
        }
      } catch (e) {}
    }
    return got;
  } finally {
    try { DriveApp.getFileById(copy.id).setTrashed(true); } catch (e) { /* 정리 실패는 무시 */ }
  }
}

// [2026.10.09] 현금영수증 금액·날짜를 OCR 글자에서 규칙으로 뽑는다(AI 비용 0원).
// 스스로 검산한다: 홈택스 영수증은 "공급가액+부가세(+봉사료)=총 거래금액", 카드단말기 영수증은 "거래금액×1.1≈합계".
// 검산이 맞거나 금액이 하나뿐일 때만 확정(confident), 아니면 금액을 비워 두고 "확인 필요"로 남긴다 — 틀린 숫자를 넣지 않는다.
function parseReceiptText_(text) {
  const t = String(text || '');
  const pad = function (n) { return ('0' + n).slice(-2); };
  let date = null;
  const dm = t.match(/(20\d{2})\s*[-./년]\s*(\d{1,2})\s*[-./월]\s*(\d{1,2})/);
  if (dm) date = dm[1] + '-' + pad(dm[2]) + '-' + pad(dm[3]);
  const toNum = function (s) { return Number(String(s).replace(/[^\d]/g, '')); };
  // ① 홈택스형 — "총 거래금액" 뒤 숫자들(공급가액, 부가세, [봉사료], 총액)
  const i = t.search(/총\s*거래\s*금액/);
  if (i >= 0) {
    const seg = t.slice(i).split(/가맹점/)[0].replace(/총\s*거래\s*금액/, '');
    const ns = (seg.match(/\d{1,3}(?:,\d{3})+|\b\d+\b/g) || []).map(toNum);
    if (ns.length >= 2) {
      const total = ns[ns.length - 1];
      const parts = ns.slice(0, -1).reduce(function (a, b) { return a + b; }, 0);
      if (total > 0 && parts === total) return { amount: total, date: date, confident: true, how: '홈택스형 검산 일치' };
    }
  }
  // ② 카드단말기형 — "합계" 근처의 "N원" 금액 중 가장 큰 값, 거래금액×1.1 검산
  if (/합\s*계|합\s*\n[\s\S]{0,40}계\s*:/.test(t)) {
    const won = (t.match(/\d{1,3}(?:,\d{3})+\s*원/g) || []).map(toNum).filter(function (v) { return v > 0; });
    if (won.length) {
      const max = Math.max.apply(null, won);
      const checked = won.some(function (v) { return v !== max && Math.abs(Math.round(v * 1.1) - max) <= 1; });
      const uniq = won.filter(function (v, k) { return won.indexOf(v) === k; });
      if (checked) return { amount: max, date: date, confident: true, how: '단말기형 검산 일치' };
      if (uniq.length === 1) return { amount: max, date: date, confident: true, how: '단말기형 합계 1개' };
    }
  }
  return { amount: null, date: date, confident: false, how: '금액 확정 못함 — 확인 필요' };
}
function extractReceiptAmountViaOCR_(fileId) {
  return parseReceiptText_(ocrFileText_(fileId));
}

// [2026.10.09] 서류 OCR 글자에서 특정인의 전화번호·주소·주민등록번호를 규칙으로 찾는다(AI 비용 0원).
// 문서에 여러 사람이 나올 수 있어 "그 이름이 나온 바로 뒤(300자 안)"에서만 찾는다 — 이름이 문서에 없으면
// 아무것도 채우지 않는다(남의 정보를 잘못 붙이지 않는 쪽을 택함). 찾은 것만 채우고, 후보 목록은 세무사님이 검토.
function parsePersonDetailText_(text, personName) {
  const t = String(text || '');
  const name = String(personName || '').replace(/\s+/g, '');
  if (name.length < 2) return {};
  const nameRe = new RegExp(name.split('').join('\\s*'), 'g');
  const out = {};
  let m;
  while ((m = nameRe.exec(t)) !== null) {
    let win = t.slice(m.index + m[0].length, m.index + m[0].length + 300);
    // 다음 사람의 주민번호가 나오면 그 앞에서 자른다 — 여러 사람이 나오는 서류에서 남의 정보를 붙이지 않게
    const rrnAll = []; const rrnRe = /\d{6}\s*-\s*[1-8]/g; let rm;
    while ((rm = rrnRe.exec(win)) !== null) rrnAll.push(rm.index);
    if (rrnAll.length >= 2) win = win.slice(0, rrnAll[1]);
    if (!out.주민등록번호) {
      const r = win.match(/\b(\d{6})\s*-\s*([1-8][\d*]{6})/);
      if (r) out.주민등록번호 = r[1] + '-' + r[2];
    }
    if (!out.전화번호) {
      const p = win.match(/\b(01[016789])[\s.)-]*(\d{3,4})[\s.-]*(\d{4})\b/) || win.match(/\b(0\d{1,2})[)-]\s*(\d{3,4})-(\d{4})\b/);
      if (p) out.전화번호 = p[1] + '-' + p[2] + '-' + p[3];
    }
    if (!out.주소) {
      const a = win.match(/(서울|부산|대구|인천|광주|대전|울산|세종|경기|강원|충청|충북|충남|전라|전북|전남|경상|경북|경남|제주)[^\n]{6,70}/);
      // 주소 뒤에 이어 붙은 전화번호·주민번호·"전화" 같은 칸 이름은 떼어낸다
      if (a) out.주소 = a[0].split(/\s*(?:\(?(?:전화|연락처|휴대폰|핸드폰|TEL|Tel)\)?\s*[:：]?|\b0\d{1,2}[-)\s.]?\d{3,4}[-\s.]\d{4}|\d{6}\s*-\s*[1-8])/)[0].replace(/\s+/g, ' ').trim();
    }
    if (out.주민등록번호 && out.전화번호 && out.주소) break;
  }
  return out;
}
function client_extractPersonDetailOCR_(fileId, mimeType, personName) {
  if (!/pdf/i.test(mimeType || '') && !/^image\//i.test(mimeType || '')) return {};
  Utilities.sleep(1500); // 드라이브 OCR 호출 한도 대비
  return parsePersonDetailText_(ocrFileText_(fileId), personName);
}
