  if (/(?:^|[^가-힣])(?:서면인터넷방문상담\s*\d\s*팀|서면\s*\d\s*팀|재산세과|소득세과|법인세과|부가가치세과|부가세과|징세과|법규과|부동산거래관리과?)\s*-\s*\d{2,6}/.test(n)) return true;
  if (/(?:^|[^가-힣])(?:서일|서이|서삼|재일|재산|재소득|재경)\s*\d{5}\s*-\s*\d{2,5}/.test(n)) return true;
  return false;
