          if (r.v) add('giftAmount', Math.floor(r.v * (kind === 'land' ? area : 1)), r.src + (kind === 'land' ? ' × ' + area + '㎡' : '') + ' — 증여일 현재 공시가격, 보충적 평가(§61) — 시가·감정가액이 있으면 그것이 우선', false);
          else notes.push(g0.loc + ' 공시가격 조회: ' + r.error);
