var JM_SIDO_RE_ = /^(?:[가-힣]{2,9}(?:시|도)\s+[가-힣]{1,6}(?:시|군|구)|세종특별자치시\s+[가-힣]{1,6}(?:동|읍|면|로|길))\s/;
