    if (mm && yy) { r.사망일 = ihYmd_(yy[1], mm[1], mm[2]); r.사망시각 = ('0' + mm[3]).slice(-2) + ':' + ('0' + mm[4]).slice(-2); r.사망일확인필요 = true; }
