  var ps = chief.getParents();
  if (!ps.hasNext()) throw new Error('0 NETAX 폴더를 찾지 못했습니다.');
  var root = getOrCreateSubfolder_(getOrCreateSubfolder_(ps.next(), '콘텐츠'), '쇼츠');
  getOrCreateSubfolder_(root, '_기준그림');
