      const mine = r.소재지 ? uniqA.filter(function (b) { return b.loc && (tcLocSame_(r.소재지, b.loc) || nm(b.loc).indexOf(nm(r.소재지)) !== -1 || nm(r.소재지).indexOf(nm(b.loc)) !== -1); }) : [];
